-- 0451 mil_lugares: 521 sitios de naturaleza curados (guía '1000 lugares de España')
-- entidades fuente=mil_lugares + puntuaciones MAX en categoría propia y naturaleza

-- === ENTIDADES ===
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('05003', 'sendero', 'Camín Real de la Mesa', 'Una de las rutas de trekking más emblemáticas y mejor conservadas de Asturias. Ideal para amantes del senderismo de larga distancia. El Camín Real de la Mesa es uno de los grandes tesoros del senderismo asturiano.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('33064', 'sendero', 'Camín Real de la Mesa', 'Una de las rutas de trekking más emblemáticas y mejor conservadas de Asturias. Ideal para amantes del senderismo de larga distancia. El Camín Real de la Mesa es uno de los grandes tesoros del senderismo asturiano.', 'mil_lugares');
