INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('25082', 'sendero', 'Carros de Foc', 'En el corazón de los Pirineos leridanos se alza uno de los paraísos montañosos más impresionantes de España. Carros de Foc recorre un paisaje dominado por picos graníticos que superan los 3000 metros y un sinfín de lagos de origen glacial que salpican valles y bosques de alta montaña.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('15043', 'sendero', 'O Camiño dos Faros', 'Una de las rutas de senderismo costero más fascinantes de Europa. El Camiño dos Faros recorre casi 200 km de litoral atlántico, enlazando faros emblemáticos a lo largo de la salvaje Costa da Morte. El camino combina impresionantes acantilados, playas ocultas, dunas vivas y bosques que llegan hasta el mar, mientras pasa por castros ancestrales y encantadores pueblos marineros llenos de autenticidad.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('90004', 'sendero', 'O Camiño dos Faros', 'Una de las rutas de senderismo costero más fascinantes de Europa. El Camiño dos Faros recorre casi 200 km de litoral atlántico, enlazando faros emblemáticos a lo largo de la salvaje Costa da Morte. El camino combina impresionantes acantilados, playas ocultas, dunas vivas y bosques que llegan hasta el mar, mientras pasa por castros ancestrales y encantadores pueblos marineros llenos de autenticidad.', 'mil_lugares');
