INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('24116', 'sendero', 'Anillo de los Picos de Europa', 'El Anillo de los Picos de Europa es una de las grandes travesías de alta montaña de la Península. Concebida por guardas de refugios, esta ruta circular de 110 km y más de 8000 metros de desnivel positivo rodea los tres macizos emblemáticos del parque nacional, ofreciendo una inmersión total en un paisaje de cumbres calizas espectaculares, gargantas profundas y valles glaciares.', 'mil_lugares');
