INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('22057', 'sendero', 'Transpirenaica', 'La Transpirenaica es el gran desafío de largo recorrido por los Pirineos. Esta mítica senda une el Cantábrico con el Mediterráneo atravesando algunos de los paisajes más salvajes y espectaculares de la cordillera. Bosques milenarios como el de Irati, cañones profundos, glaciares, lagos de alta montaña y cimas imponentes conforman un escenario de geología espectacular y biodiversidad excepcional.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('22125', 'sendero', 'Transpirenaica', 'La Transpirenaica es el gran desafío de largo recorrido por los Pirineos. Esta mítica senda une el Cantábrico con el Mediterráneo atravesando algunos de los paisajes más salvajes y espectaculares de la cordillera. Bosques milenarios como el de Irati, cañones profundos, glaciares, lagos de alta montaña y cimas imponentes conforman un escenario de geología espectacular y biodiversidad excepcional.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('27008', 'sendero', 'Transpirenaica', 'La Transpirenaica es el gran desafío de largo recorrido por los Pirineos. Esta mítica senda une el Cantábrico con el Mediterráneo atravesando algunos de los paisajes más salvajes y espectaculares de la cordillera. Bosques milenarios como el de Irati, cañones profundos, glaciares, lagos de alta montaña y cimas imponentes conforman un escenario de geología espectacular y biodiversidad excepcional.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('17095', 'sendero', 'Camí de Ronda', 'El Camí de Ronda es el sendero mítico que recorre la emblemática Costa Brava. Este camino costero bordea acantilados dramáticos, calas de aguas turquesas y playas salvajes, manteniendo su belleza intacta a pesar de su popularidad entre senderistas, corredores y visitantes.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('18017', 'sendero', 'Camí de Ronda', 'El Camí de Ronda es el sendero mítico que recorre la emblemática Costa Brava. Este camino costero bordea acantilados dramáticos, calas de aguas turquesas y playas salvajes, manteniendo su belleza intacta a pesar de su popularidad entre senderistas, corredores y visitantes.', 'mil_lugares');
