INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('11035', 'sendero', 'GR-7', 'El GR-7 fue el primer sendero de gran recorrido señalizado en España (1974) y sigue siendo uno de los más largos y variados del país. Sus casi 2600 km recorren el Levante mediterráneo, desde los Pirineos catalanes hasta el extremo sur de Tarifa, donde el viento y el Estrecho marcan el final de la aventura.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('03003', 'sendero', 'Travessia dels 8 Mils', 'La Travessia dels 8 Mils es un proyecto innovador de turismo activo que combina senderismo, patrimonio y gastronomía en la provincia de Alicante. Esta travesía de 190 km, dividida en nueve etapas, recorre las impresionantes sierras del interior valenciano, ofreciendo un desafío atractivo para amantes de las cumbres.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('07013', 'sendero', 'Camí de Cavalls', 'El Camí de Cavalls es el gran sendero que permite descubrir Menorca en toda su esencia. Esta ruta ancestral de 185 km, dividida en 20 etapas señalizadas, bordea la isla completa y se puede realizar por tramos o como una gran travesía circular.', 'mil_lugares');
