INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('09001', 'sendero', 'Senda del Duero', 'La Senda del Duero es un viaje profundo por el alma de Castilla y León. Este Camino Natural de 755 km recorre el valle del Duero, conectando paisajes, patrimonio y tradiciones que han marcado la historia de España. Viñedos legendarios como los de Toro, el rico patrimonio románico de Zamora, villas históricas como Tordesillas y Peñafiel, y la gastronomía de renombre en Aranda de Duero son solo algunos de los tesoros que salpican el camino.', 'mil_lugares');
