INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('28027', 'sendero', 'Senda Genaro', 'La Senda Genaro recorre la hermosa Sierra Norte de Madrid, una zona a menudo preservada en su intimidad natural. Este itinerario de 70 km, dividido en siete etapas, es el primer Gran Recorrido que transita íntegramente por la Comunidad de Madrid.', 'mil_lugares');
