INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('09006', 'sendero', 'Ruta de los Sentidos', 'La Ruta de los Sentidos recorre la comarca burgalesa de Las Merindades, un territorio de gran belleza y misterio situado entre la Cordillera Cantábrica y el valle del Ebro. Sus nueve etapas invitan a sumergirse en desfiladeros impresionantes, bosques de castaños y robles, y un paisaje marcado por la fuerza del río.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('09009', 'sendero', 'Ruta de los Sentidos', 'La Ruta de los Sentidos recorre la comarca burgalesa de Las Merindades, un territorio de gran belleza y misterio situado entre la Cordillera Cantábrica y el valle del Ebro. Sus nueve etapas invitan a sumergirse en desfiladeros impresionantes, bosques de castaños y robles, y un paisaje marcado por la fuerza del río.', 'mil_lugares');
