INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('38037', 'sendero', 'El Bastón de La Palma', 'El Bastón de La Palma es un espectacular tramo del GR-131 que atraviesa la Isla Bonita desde el nivel del mar hasta las alturas volcánicas. El sendero asciende desde costas oceánicas hasta el Roque de los Muchachos, pasando por los impresionantes acantilados de las Angustias y los miradores de la Caldera de Taburiente.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('38024', 'sendero', 'El Bastón de La Palma', 'El Bastón de La Palma es un espectacular tramo del GR-131 que atraviesa la Isla Bonita desde el nivel del mar hasta las alturas volcánicas. El sendero asciende desde costas oceánicas hasta el Roque de los Muchachos, pasando por los impresionantes acantilados de las Angustias y los miradores de la Caldera de Taburiente.', 'mil_lugares');
