INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('08099', 'sendero', 'Cavalls del Vent', 'Cavalls del Vent es una travesía de alta montaña imprescindible en Cataluña. La ruta conecta ocho refugios a través del Parc Natural del Cadí-Moixeró, una impresionante barrera montañosa con picos que superan los 2500 metros. El itinerario de más de 84 km ofrece un ambiente alpino auténtico, con vientos fuertes, crestas aéreas y paisajes fronterizos dominados por el Pedraforca.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('27006', 'sendero', 'Cavalls del Vent', 'Cavalls del Vent es una travesía de alta montaña imprescindible en Cataluña. La ruta conecta ocho refugios a través del Parc Natural del Cadí-Moixeró, una impresionante barrera montañosa con picos que superan los 2500 metros. El itinerario de más de 84 km ofrece un ambiente alpino auténtico, con vientos fuertes, crestas aéreas y paisajes fronterizos dominados por el Pedraforca.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('08002', 'sendero', 'Cavalls del Vent', 'Cavalls del Vent es una travesía de alta montaña imprescindible en Cataluña. La ruta conecta ocho refugios a través del Parc Natural del Cadí-Moixeró, una impresionante barrera montañosa con picos que superan los 2500 metros. El itinerario de más de 84 km ofrece un ambiente alpino auténtico, con vientos fuertes, crestas aéreas y paisajes fronterizos dominados por el Pedraforca.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('18094', 'sendero', 'Sendero Sulayr', 'El Sendero Sulayr (GR-240) es una de las travesías de alta montaña más destacadas de la Península. Con sus 300 km distribuidos en 19 etapas, recorre los tesoros del Parque Nacional de Sierra Nevada siguiendo las marcas blancas y rojas.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('18042', 'sendero', 'Sendero Sulayr', 'El Sendero Sulayr (GR-240) es una de las travesías de alta montaña más destacadas de la Península. Con sus 300 km distribuidos en 19 etapas, recorre los tesoros del Parque Nacional de Sierra Nevada siguiendo las marcas blancas y rojas.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('18180', 'sendero', 'Sendero Sulayr', 'El Sendero Sulayr (GR-240) es una de las travesías de alta montaña más destacadas de la Península. Con sus 300 km distribuidos en 19 etapas, recorre los tesoros del Parque Nacional de Sierra Nevada siguiendo las marcas blancas y rojas.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('18903', 'sendero', 'Sendero Sulayr', 'El Sendero Sulayr (GR-240) es una de las travesías de alta montaña más destacadas de la Península. Con sus 300 km distribuidos en 19 etapas, recorre los tesoros del Parque Nacional de Sierra Nevada siguiendo las marcas blancas y rojas.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('33009', 'sendero', 'Vuelta a Aralar', 'La Vuelta a Aralar es un clásico del montañismo vasco-navarro. Sus casi 100 km rodean la sierra de Aralar, un macizo cargado de simbolismo cultural donde mitos y leyendas se entretejen con el paisaje. El recorrido atraviesa un territorio salvaje y primitivo: prados de siega, bosques de hayas y robles, formaciones rocosas singulares y cumbres emblemáticas como el Txindoki.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('31144', 'sendero', 'Vuelta a Aralar', 'La Vuelta a Aralar es un clásico del montañismo vasco-navarro. Sus casi 100 km rodean la sierra de Aralar, un macizo cargado de simbolismo cultural donde mitos y leyendas se entretejen con el paisaje. El recorrido atraviesa un territorio salvaje y primitivo: prados de siega, bosques de hayas y robles, formaciones rocosas singulares y cumbres emblemáticas como el Txindoki.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('27007', 'sendero', 'Circular de la Val d''Aran', 'La Circular de la Val d’Aran es una magnífica forma de explorar uno de los valles más bellos de los Pirineos. Sus 92 km repartidos en siete etapas siguen antiguas veredas del GR-211, permitiendo descubrir la riqueza natural, cultural y etnográfica de la cuenca alta del río Garona.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('24116', 'sendero', 'Travesía de los Urrieles', 'La Travesía de los Urrieles es una ruta legendaria que atraviesa el corazón más salvaje de los Picos de Europa. Este camino alpino por etapas rinde homenaje a las cumbres y desfiladeros más emblemáticos del macizo, comenzando cerca del icónico Naranjo de Bulnes y culminando en la famosa Ruta del Cares.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('05004', 'sendero', 'Travesía de los Urrieles', 'La Travesía de los Urrieles es una ruta legendaria que atraviesa el corazón más salvaje de los Picos de Europa. Este camino alpino por etapas rinde homenaje a las cumbres y desfiladeros más emblemáticos del macizo, comenzando cerca del icónico Naranjo de Bulnes y culminando en la famosa Ruta del Cares.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('90795', 'sendero', 'Las Médulas', 'Las Médulas representan uno de los paisajes más extraordinarios y singulares de España. Modeladas por la ingeniería romana, la erosión y la regeneración natural, estas formaciones rojizas forman un conjunto declarado Patrimonio Mundial que cautiva a todo visitante.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('32002', 'sendero', 'Torcal de Antequera', 'El Torcal de Antequera es un paisaje kárstico asombroso y casi surrealista. Este paraje natural, declarado Patrimonio Mundial por la UNESCO, ofrece un espectáculo geológico único resultado de la orogenia alpina y miles de años de erosión.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('10054', 'poza', 'Garganta de los Infiernos', 'En el corazón del Valle del Jerte, bajo la imponente presencia del macizo de Gredos, se encuentra la Garganta de los Infiernos. Este paraje destaca por sus impresionantes cascadas y la explosión de color de los cerezos en flor, que atraen a miles de visitantes cada año.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('10183', 'poza', 'Garganta de los Infiernos', 'En el corazón del Valle del Jerte, bajo la imponente presencia del macizo de Gredos, se encuentra la Garganta de los Infiernos. Este paraje destaca por sus impresionantes cascadas y la explosión de color de los cerezos en flor, que atraen a miles de visitantes cada año.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('10107', 'poza', 'Garganta de los Infiernos', 'En el corazón del Valle del Jerte, bajo la imponente presencia del macizo de Gredos, se encuentra la Garganta de los Infiernos. Este paraje destaca por sus impresionantes cascadas y la explosión de color de los cerezos en flor, que atraen a miles de visitantes cada año.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('11020', 'sendero', 'Ruta de La Sauceda', 'La Ruta de La Sauceda recorre uno de los bosques más singulares de Europa: la laurisilva del Parque Natural de los Alcornocales. Este entorno envuelto en nieblas permanentes crea un ambiente mágico y exuberante, con vegetación densa que parece sacada de un cuento.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('05047', 'sendero', 'Trekking del circo de Gredos', 'El Trekking del Circo de Gredos es un desafío reservado para montañeros experimentados. Este recorrido integral de unos 20 km recorre el corazón del Macizo Central de la Sierra de Gredos, entre agujas, cresterías, brechas y riscos que combinan belleza salvaje y gran exigencia técnica.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('16215', 'sendero', 'Hoz de Tragavivos', 'La Hoz de Tragavivos es una de las rutas más emocionantes y vertiginosas de la Serranía de Cuenca. Esta senda estrecha y aérea discurre por el profundo desfiladero del río Guadiela, un entorno agreste y salvaje de gran belleza. El camino, en gran parte tallado en la roca y con pasos muy expuestos, sigue antiguas canalizaciones hidráulicas que unían el Molino de Chinca con la central del Infiernillo.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('16078', 'sendero', 'Hoz de Tragavivos', 'La Hoz de Tragavivos es una de las rutas más emocionantes y vertiginosas de la Serranía de Cuenca. Esta senda estrecha y aérea discurre por el profundo desfiladero del río Guadiela, un entorno agreste y salvaje de gran belleza. El camino, en gran parte tallado en la roca y con pasos muy expuestos, sigue antiguas canalizaciones hidráulicas que unían el Molino de Chinca con la central del Infiernillo.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('32002', 'sendero', 'Caminito del Rey', 'El Caminito del Rey es uno de los senderos más famosos y espectaculares de España. Este recorrido de poco más de 5 km discurre por pasarelas modernas suspendidas a más de 100 metros sobre el río Guadalhorce, en el impresionante desfiladero de los Gaitanes.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('32004', 'sendero', 'Caminito del Rey', 'El Caminito del Rey es uno de los senderos más famosos y espectaculares de España. Este recorrido de poco más de 5 km discurre por pasarelas modernas suspendidas a más de 100 metros sobre el río Guadalhorce, en el impresionante desfiladero de los Gaitanes.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('32025', 'sendero', 'Caminito del Rey', 'El Caminito del Rey es uno de los senderos más famosos y espectaculares de España. Este recorrido de poco más de 5 km discurre por pasarelas modernas suspendidas a más de 100 metros sobre el río Guadalhorce, en el impresionante desfiladero de los Gaitanes.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('03097', 'sendero', 'Barranco del Infierno', 'El Barranco del Infierno, en la Vall de Laguar, es una ruta circular de 14 km llena de historia y vértigo. El camino comienza con los famosos 6873 escalones de origen morisco y se adentra en un desfiladero mediterráneo esculpido por el río Girona.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('17118', 'activo', 'Boreas', 'El pecio del Boreas es uno de los atractivos submarinos más populares de la Costa Brava. Este barco de 40 metros, hundido intencionadamente en 1989 frente a Palamós para fomentar el turismo subacuático, se ha convertido en un arrecife artificial lleno de vida.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('30003', 'activo', 'S.S. Sirio', 'El S.S. Sirio ostenta el triste récord de ser el naufragio civil más trágico del Mediterráneo español. Hundido en 1906 (seis años antes del Titanic), el vapor dejó cerca de 500 víctimas al chocar contra el Bajo de Fuera, un peligroso espolón rocoso.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('03039', 'activo', 'Bou Ferrer', 'El Bou Ferrer es un tesoro arqueológico submarino único: el último barco romano accesible para buceadores en todo el Mediterráneo. Este mercante del siglo I yace a poca profundidad frente a las costas de Villajoyosa, sorprendentemente bien conservado.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('43148', 'activo', 'La Dragonera', 'La Dragonera es uno de los pecios más populares para el buceo en Tarragona. Este mercante hundido intencionadamente en 1994 se ha convertido en un exitoso arrecife artificial que beneficia tanto al turismo submarino como al ecosistema marino.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('30016', 'activo', 'Naranjito', 'El pecio Naranjito (también conocido como Isla Gomera) es uno de los más visitados y emblemáticos de la Región de Murcia. Hundido frente a las costas del Cabo de Palos, su accesibilidad y escasa dificultad técnica lo convierten en un destino ideal para buceadores de todos los niveles.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('39020', 'activo', 'Río Miera', 'El pecio del Río Miera es uno de los clásicos del buceo en Cantabria. Este barco botado en 1920 y hundido tras un choque yace entre los 38 y 45 metros de profundidad en aguas con visibilidad variable. Apto tanto para buceo recreativo como técnico, permite explorar su interior bajo la atenta mirada de crustáceos y otros habitantes marinos.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('39075', 'activo', 'Río Miera', 'El pecio del Río Miera es uno de los clásicos del buceo en Cantabria. Este barco botado en 1920 y hundido tras un choque yace entre los 38 y 45 metros de profundidad en aguas con visibilidad variable. Apto tanto para buceo recreativo como técnico, permite explorar su interior bajo la atenta mirada de crustáceos y otros habitantes marinos.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('18006', 'activo', 'Avvenire', 'El pecio Avvenire, conocido popularmente como el “Marmolero”, descansa frente a Cala Montgó en la Costa Brava. Este mercante se hundió al chocar contra un saliente rocoso mientras transportaba placas de mármol. A más de 40 metros de profundidad, la inmersión exige buena experiencia, especialmente por la visibilidad a menudo reducida en la zona.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('30016', 'activo', 'Standfield', 'El pecio Standfield es uno de los más exigentes y atractivos para buceo técnico en la Región de Murcia. Hundido durante la Primera Guerra Mundial, este navío de 120 metros de eslora yace a 60 metros de profundidad. La inmersión, reservada para buceadores experimentados, ofrece un desafío técnico y la oportunidad de explorar un gran barco en la penumbra.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('35016', 'activo', 'Kalais', 'El pecio Kalais es uno de los atractivos submarinos más accesibles de Gran Canaria. Este carguero griego de más de 100 metros, abandonado en el Puerto de la Luz tras una avería cuando se dirigía a Nigeria, descansa a solo 20 metros de profundidad.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('04017', 'activo', 'Vapor Arna', 'El Vapor Arna es uno de los pecios históricos más interesantes del Cabo de Gata. Hundido en 1828, este barco de 100 metros de eslora descansa a varias millas de la costa almeriense, expuesto a las corrientes del Mediterráneo. Cuando las condiciones lo permiten, es una inmersión fascinante que combina historia naval con la explosiva vida marina que coloniza sus restos.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('33044', 'sendero', 'Camino Primitivo', 'El Camino Primitivo es la ruta jacobea más antigua y auténtica. Partiendo desde Oviedo, sus 240 km de exigente terreno llevan al peregrino hasta Palas de Rei, en Lugo, siguiendo las huellas del rey Alfonso II el Casto, quien realizó la primera peregrinación oficial a Santiago.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('18087', 'sendero', 'Camino Mozárabe', 'El Camino Mozárabe es una de las rutas jacobeas más antiguas y con mayor carga histórica. Sus 380 km conectan Granada con Mérida, siguiendo los pasos de las comunidades mozárabes que, desde el siglo XI, unían la Vía de la Plata con Santiago de Compostela.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('06018', 'sendero', 'Camino Mozárabe', 'El Camino Mozárabe es una de las rutas jacobeas más antiguas y con mayor carga histórica. Sus 380 km conectan Granada con Mérida, siguiendo los pasos de las comunidades mozárabes que, desde el siglo XI, unían la Vía de la Plata con Santiago de Compostela.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('15078', 'sendero', 'Camino Portugués', 'El Camino Portugués es una de las rutas jacobeas más populares y asequibles. Sus 116 km desde Tui (Pontevedra) hasta Santiago de Compostela reviven la tradición de los peregrinos portugueses que partían desde Lisboa, Coímbra u Oporto.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('36011', 'sendero', 'Camino Portugués', 'El Camino Portugués es una de las rutas jacobeas más populares y asequibles. Sus 116 km desde Tui (Pontevedra) hasta Santiago de Compostela reviven la tradición de los peregrinos portugueses que partían desde Lisboa, Coímbra u Oporto.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('36012', 'sendero', 'Camino Portugués', 'El Camino Portugués es una de las rutas jacobeas más populares y asequibles. Sus 116 km desde Tui (Pontevedra) hasta Santiago de Compostela reviven la tradición de los peregrinos portugueses que partían desde Lisboa, Coímbra u Oporto.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('36039', 'sendero', 'Camino Portugués', 'El Camino Portugués es una de las rutas jacobeas más populares y asequibles. Sus 116 km desde Tui (Pontevedra) hasta Santiago de Compostela reviven la tradición de los peregrinos portugueses que partían desde Lisboa, Coímbra u Oporto.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('15065', 'sendero', 'Camino Portugués', 'El Camino Portugués es una de las rutas jacobeas más populares y asequibles. Sus 116 km desde Tui (Pontevedra) hasta Santiago de Compostela reviven la tradición de los peregrinos portugueses que partían desde Lisboa, Coímbra u Oporto.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('03003', 'sendero', 'Camino del Sureste', 'El Camino del Sureste es una de las variantes más largas y desafiantes del Camino de Santiago. Sus más de 800 km unen Alicante con Astorga, siguiendo el espíritu de los antiguos peregrinos que partían desde el Mediterráneo (Murcia, Elche y otras localidades).', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('26002', 'sendero', 'Camino del Sureste', 'El Camino del Sureste es una de las variantes más largas y desafiantes del Camino de Santiago. Sus más de 800 km unen Alicante con Astorga, siguiendo el espíritu de los antiguos peregrinos que partían desde el Mediterráneo (Murcia, Elche y otras localidades).', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('39035', 'sendero', 'Camino de la Costa', 'El Camino de la Costa es la versión más salvaje y atlántica del Camino de Santiago. Sus 830 km desde Irún hasta Arzúa (A Coruña) siguen los impresionantes perfiles de la costa cantábrica, ofreciendo paisajes espectaculares y un desafío constante.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('33036', 'sendero', 'Camino de la Costa', 'El Camino de la Costa es la versión más salvaje y atlántica del Camino de Santiago. Sus 830 km desde Irún hasta Arzúa (A Coruña) siguen los impresionantes perfiles de la costa cantábrica, ofreciendo paisajes espectaculares y un desafío constante.', 'mil_lugares');
