INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('21012', 'sendero', 'Camino de la Costa', 'El Camino de la Costa es la versión más salvaje y atlántica del Camino de Santiago. Sus 830 km desde Irún hasta Arzúa (A Coruña) siguen los impresionantes perfiles de la costa cantábrica, ofreciendo paisajes espectaculares y un desafío constante.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('26002', 'sendero', 'Vía de la Plata', 'La Vía de la Plata es una de las rutas jacobeas con mayor historia. Sus aproximadamente 500 km entre Mérida y Astorga siguen el trazado de una antigua calzada romana construida en el siglo I a.C., que sirvió primero a legiones y luego como importante vía comercial.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('06018', 'sendero', 'Vía de la Plata', 'La Vía de la Plata es una de las rutas jacobeas con mayor historia. Sus aproximadamente 500 km entre Mérida y Astorga siguen el trazado de una antigua calzada romana construida en el siglo I a.C., que sirvió primero a legiones y luego como importante vía comercial.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('08014', 'sendero', 'Camí de Sant Jaume', 'El Camí de Sant Jaume es una variante jacobea con un arranque inolvidable: el emblemático Monasterio de Montserrat. Sus casi 500 km terminan en Logroño, donde se une al Camino Francés, recorriendo otros santuarios catalanes y el espectacular valle del Ebro.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('26089', 'sendero', 'Camí de Sant Jaume', 'El Camí de Sant Jaume es una variante jacobea con un arranque inolvidable: el emblemático Monasterio de Montserrat. Sus casi 500 km terminan en Logroño, donde se une al Camino Francés, recorriendo otros santuarios catalanes y el espectacular valle del Ebro.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('15078', 'sendero', 'Camino Francés', 'El Camino Francés es la ruta jacobea más popular y transitada. Sus aproximadamente 30 etapas desde Roncesvalles hasta Santiago atraviesan los Pirineos y una gran variedad de paisajes ibéricos: bosques centenarios, prados, pueblos emblemáticos y joyas del románico.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('31211', 'sendero', 'Camino Francés', 'El Camino Francés es la ruta jacobea más popular y transitada. Sus aproximadamente 30 etapas desde Roncesvalles hasta Santiago atraviesan los Pirineos y una gran variedad de paisajes ibéricos: bosques centenarios, prados, pueblos emblemáticos y joyas del románico.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('33015', 'sendero', 'Camino Aragonés', 'El Camino Aragonés es una variante jacobea cargada de historia y misticismo, ligada a leyendas del Santo Grial. Sus más de 160 km comienzan en el Puerto de Somport y recorren paisajes pirenaicos espectaculares hasta unirse al Camino Francés en Puente la Reina.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('22130', 'sendero', 'Camino Aragonés', 'El Camino Aragonés es una variante jacobea cargada de historia y misticismo, ligada a leyendas del Santo Grial. Sus más de 160 km comienzan en el Puerto de Somport y recorren paisajes pirenaicos espectaculares hasta unirse al Camino Francés en Puente la Reina.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('15078', 'sendero', 'La extensión a Finisterre', 'La extensión a Finisterre es el complemento perfecto para muchos peregrinos. Sus 90 km desde Santiago hasta el fin del mundo (Finisterre) siguen la tradición de aquellos que, tras llegar a la catedral, continuaban hasta el cabo mítico donde los antiguos creían que terminaba la tierra.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('01011', 'sendero', 'La extensión a Finisterre', 'La extensión a Finisterre es el complemento perfecto para muchos peregrinos. Sus 90 km desde Santiago hasta el fin del mundo (Finisterre) siguen la tradición de aquellos que, tras llegar a la catedral, continuaban hasta el cabo mítico donde los antiguos creían que terminaba la tierra.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('01013', 'sendero', 'La extensión a Finisterre', 'La extensión a Finisterre es el complemento perfecto para muchos peregrinos. Sus 90 km desde Santiago hasta el fin del mundo (Finisterre) siguen la tradición de aquellos que, tras llegar a la catedral, continuaban hasta el cabo mítico donde los antiguos creían que terminaba la tierra.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('15023', 'sendero', 'La extensión a Finisterre', 'La extensión a Finisterre es el complemento perfecto para muchos peregrinos. Sus 90 km desde Santiago hasta el fin del mundo (Finisterre) siguen la tradición de aquellos que, tras llegar a la catedral, continuaban hasta el cabo mítico donde los antiguos creían que terminaba la tierra.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('15037', 'sendero', 'La extensión a Finisterre', 'La extensión a Finisterre es el complemento perfecto para muchos peregrinos. Sus 90 km desde Santiago hasta el fin del mundo (Finisterre) siguen la tradición de aquellos que, tras llegar a la catedral, continuaban hasta el cabo mítico donde los antiguos creían que terminaba la tierra.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('90641', 'activo', 'Parque Natural de Redes', 'El Parque Natural de Redes es un paraíso para jinetes aventureros. Declarado Reserva de la Biosfera en 2001, ofrece terrenos de exploración pura entre vegas verdes, hayedos centenarios y aldeas que parecen detenidas en el tiempo. La ruta permite trazar caminos propios en un templo de soledad y naturaleza salvaje, coronado por la hospitalidad de posadas como el refugio de Brañagallones.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('33067', 'activo', 'Parque Natural de Redes', 'El Parque Natural de Redes es un paraíso para jinetes aventureros. Declarado Reserva de la Biosfera en 2001, ofrece terrenos de exploración pura entre vegas verdes, hayedos centenarios y aldeas que parecen detenidas en el tiempo. La ruta permite trazar caminos propios en un templo de soledad y naturaleza salvaje, coronado por la hospitalidad de posadas como el refugio de Brañagallones.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('33062', 'activo', 'Los Oscos', 'Cabalgando por la frontera entre Asturias y Galicia, Los Oscos ofrecen una Reserva de la Biosfera llena de contrastes: fuego de hogueras, tejados de pizarra, piedra desnuda y bosques impenetrables. En dos jornadas se puede seguir un trazado primitivo hacia Santiago, disfrutando de la calidez de sus gentes y una comunión profunda con la naturaleza.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('33027', 'activo', 'Los Oscos', 'Cabalgando por la frontera entre Asturias y Galicia, Los Oscos ofrecen una Reserva de la Biosfera llena de contrastes: fuego de hogueras, tejados de pizarra, piedra desnuda y bosques impenetrables. En dos jornadas se puede seguir un trazado primitivo hacia Santiago, disfrutando de la calidez de sus gentes y una comunión profunda con la naturaleza.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('22130', 'activo', 'Alto Aragón', 'Una semana de contrastes sorprendentes espera en Alto Aragón. Partiendo desde Jaca, la ruta combina pistas forestales y huellas de animales, pasando de las caprichosas formas de los Mallos de Riglos a la fuerza benévola del río Gállego.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('05105', 'activo', 'Sierra de Gredos', 'La Sierra de Gredos ofrece una de las cabalgadas más habituales y recomendables para iniciarse en expediciones a caballo. En un par de jornadas se atraviesan valles emblemáticos como el del Tormes, Alberche o Tiétar, con paisajes que cambian según la estación.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('33068', 'activo', 'Parque Natural de Somiedo', 'En pleno territorio de osos, Somiedo propone una semana irrechazable de aventura a caballo. Entre brañas, teitos, ríos salmoneros y extensos prados salpicados de bosque, el parque es hogar de lobos y rebecos. Es una grandiosa experiencia ecuestre en uno de los enclaves más salvajes y mejor conservados de Asturias.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('07013', 'activo', 'La vuelta a Menorca', 'La Camí de Cavalls es tan apta para senderistas como para jinetes. Sus casi 100 km bordean las costas de Menorca, ofreciendo un muestrario constante de naturaleza virgen y calas paradisíacas. Accesible en tres o cuatro jornadas, es una ruta costera mágica donde cada rincón invita a disfrutar del mar y la isla desde la silla de montar.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('07006', 'activo', 'La vuelta a Menorca', 'La Camí de Cavalls es tan apta para senderistas como para jinetes. Sus casi 100 km bordean las costas de Menorca, ofreciendo un muestrario constante de naturaleza virgen y calas paradisíacas. Accesible en tres o cuatro jornadas, es una ruta costera mágica donde cada rincón invita a disfrutar del mar y la isla desde la silla de montar.', 'mil_lugares');
