INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('90850', 'activo', 'La vuelta a Menorca', 'La Camí de Cavalls es tan apta para senderistas como para jinetes. Sus casi 100 km bordean las costas de Menorca, ofreciendo un muestrario constante de naturaleza virgen y calas paradisíacas. Accesible en tres o cuatro jornadas, es una ruta costera mágica donde cada rincón invita a disfrutar del mar y la isla desde la silla de montar.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('26061', 'activo', 'Sierra de la Demanda', 'Desde el animado pueblo de Ezcaray, la Sierra de la Demanda propone tres o cuatro jornadas exigentes por su vertiente septentrional. Numerosas villas dan acogida al camino, aunque algunas secciones de montaña son poco transitadas y requieren pericia y sangre fría.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('40194', 'activo', 'Segovia por su historia', 'Recorrer Segovia a caballo durante una semana es sumergirse en sus joyas históricas (castillo de Pedraza, Sotosalbos, La Granja de San Ildefonso) y sus glorias naturales: vistas alpinas de Guadarrama, senderos de trashumancia, bosques de Valsaín y gargantas del río Duratón. Una combinación perfecta de patrimonio cultural y naturaleza desafiante.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('10107', 'activo', 'Valle del Jerte', 'El Valle del Jerte es especialmente mágico durante la floración del cerezo. Cabalgar por caminos ganaderos y vías romanas con el telón de fondo de la sierra de Candelario y el rumor del río Jerte es una ensoñación primaveral. Un destino ideal para jornadas ecuestres en cualquier época, pero inolvidable en primavera.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('33070', 'activo', 'Playas del Occidente Asturiano', 'Recorrer decenas de kilómetros al trote por el Occidente Asturiano es una de las experiencias ecuestres más vibrantes del norte. La ruta combina pueblos marineros con encanto, playas solitarias que cambian con las mareas, calas escondidas y extensos bosques que llegan hasta el mar.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('05011', 'activo', 'Playas del Occidente Asturiano', 'Recorrer decenas de kilómetros al trote por el Occidente Asturiano es una de las experiencias ecuestres más vibrantes del norte. La ruta combina pueblos marineros con encanto, playas solitarias que cambian con las mareas, calas escondidas y extensos bosques que llegan hasta el mar.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('05008', 'activo', 'Playas del Occidente Asturiano', 'Recorrer decenas de kilómetros al trote por el Occidente Asturiano es una de las experiencias ecuestres más vibrantes del norte. La ruta combina pueblos marineros con encanto, playas solitarias que cambian con las mareas, calas escondidas y extensos bosques que llegan hasta el mar.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('33041', 'activo', 'Playas del Occidente Asturiano', 'Recorrer decenas de kilómetros al trote por el Occidente Asturiano es una de las experiencias ecuestres más vibrantes del norte. La ruta combina pueblos marineros con encanto, playas solitarias que cambian con las mareas, calas escondidas y extensos bosques que llegan hasta el mar.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('23009', 'activo', 'Parque Natural de los Valles Occidentales', 'El Parque Natural de los Valles Occidentales es un paraíso ecuestre en el Pirineo aragonés. Cumbres desafiantes como el Bisaurín o el Aspe dominan un paisaje geológico espectacular donde cinco ríos horadan valles glaciares tapizados de hayas, robles y abetos.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('22028', 'activo', 'Parque Natural de los Valles Occidentales', 'El Parque Natural de los Valles Occidentales es un paraíso ecuestre en el Pirineo aragonés. Cumbres desafiantes como el Bisaurín o el Aspe dominan un paisaje geológico espectacular donde cinco ríos horadan valles glaciares tapizados de hayas, robles y abetos.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('22170', 'activo', 'Valle del Tena', 'El Valle del Tena es el corazón geográfico del Pirineo aragonés. Aquí esperan descensos emocionantes, travesías clásicas y coqueteos con cimas como el Midi, junto a ibones congelados y crestas espectaculares. El Balneario de Panticosa sirve como base perfecta para explorar este paraíso de nieve y montaña, ideal para amantes de la alta montaña en cualquier estación.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('33033', 'activo', 'Peña Ubiña', 'Peña Ubiña (2417 m) es uno de los dosmiles menos visitados y más solemnes de la Cordillera Cantábrica. Su macizo está salpicado de glaciares, cortados y valles escondidos. La ruta más popular, la Canal Este desde Tuiza de Arriba, ofrece una ascensión exigente pero muy gratificante con paisajes de gran belleza.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('22230', 'activo', 'Cresta de los Gabietos', 'La Cresta de los Gabietos es un cordal exigente que pone a prueba técnica y mental. Cimas como punta Escuzana y Mondarruego ofrecen vistas fabulosas sobre las gargantas del río Ara en Ordesa. En invierno se convierte en un desafío alpino serio.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('22054', 'activo', 'Aneto', 'El Aneto (3304 m) es el gigante de los Pirineos y una ascensión clásica para quien busca doctorarse en alpinismo. Con nieve, la ruta gana una dimensión épica. Es recomendable tomárselo con calma, pernoctar en refugio y, si es posible, contar con guía.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('32083', 'activo', 'Macizo de Peña Trevinca', 'El Macizo de Peña Trevinca, con cimas como Peña Trevinca (2121 m), Peña Negra y Peña Surbia, forma un grupo montañoso imponente en la sierra Do Eixo. Ríos profundos, cañones y glaciares místicos caracterizan este territorio aislado y azotado por los vientos.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('34056', 'activo', 'Integral de la Montaña Palentina', 'La Integral de la Montaña Palentina enlaza cumbres emblemáticas como Curavacas, Espigüete y Tres Provincias en el Parque Natural de Fuentes Carrionas. Con miles de metros de desnivel y gran parte por encima de los 2000 m, es una poderosa travesía circular a medida.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('34199', 'activo', 'Integral de la Montaña Palentina', 'La Integral de la Montaña Palentina enlaza cumbres emblemáticas como Curavacas, Espigüete y Tres Provincias en el Parque Natural de Fuentes Carrionas. Con miles de metros de desnivel y gran parte por encima de los 2000 m, es una poderosa travesía circular a medida.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('34185', 'activo', 'Integral de la Montaña Palentina', 'La Integral de la Montaña Palentina enlaza cumbres emblemáticas como Curavacas, Espigüete y Tres Provincias en el Parque Natural de Fuentes Carrionas. Con miles de metros de desnivel y gran parte por encima de los 2000 m, es una poderosa travesía circular a medida.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('18903', 'activo', 'Tresmiles de Sierra Nevada', 'Sierra Nevada ofrece más de 50 cumbres por encima de los 3000 m. El refugio Poqueira sirve como campo base perfecto para jornadas de skimo y travesías por circos y cimas. En invierno el macizo se transforma en un escenario de fantasía, lleno de emoción y descubrimiento para esquiadores de montaña.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('05105', 'activo', 'Glaciarismo en Gredos', 'El glaciarismo en Gredos representa el alpinismo clásico en su forma más pura y sobria. Rincones como el Cuchillar de las Navajas o el valle de Cinco Lagunas concentran líneas de hielo efímeras y austeras. Una experiencia para deleitarse con el golpeo de piolets en uno de los macizos más clásicos de la Península.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('05267', 'activo', 'Glaciarismo en Gredos', 'El glaciarismo en Gredos representa el alpinismo clásico en su forma más pura y sobria. Rincones como el Cuchillar de las Navajas o el valle de Cinco Lagunas concentran líneas de hielo efímeras y austeras. Una experiencia para deleitarse con el golpeo de piolets en uno de los macizos más clásicos de la Península.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('07015', 'activo', 'Navegando Mallorca', 'Mallorca es un clásico vacacional que nunca decepciona. Un periplo en catamarán permite descubrir sus tranquilas calas mediterráneas, horizontes abiertos donde avistar delfines y ballenas, y costas abruptas de gran belleza. De vez en cuando se abandona el confort del barco para explorar cuevas con lagos subterráneos o disfrutar de la excelente gastronomía en coquetas villas costeras.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('17138', 'activo', 'Costa Brava', 'La Costa Brava ofrece una travesía inolvidable entre calas escondidas, playas, cabos e islotes protegidos por acantilados rugientes vestidos de pinar. Navegar en kayak de mar permite pasar de rincones prístinos a paisajes donde la mano del hombre ha dejado su huella.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('90033', 'activo', 'Costa Brava', 'La Costa Brava ofrece una travesía inolvidable entre calas escondidas, playas, cabos e islotes protegidos por acantilados rugientes vestidos de pinar. Navegar en kayak de mar permite pasar de rincones prístinos a paisajes donde la mano del hombre ha dejado su huella.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('07009', 'activo', 'Ibiza y Formentera en Velero', '¡Izad las velas! Ibiza y Formentera guardan tesoros accesibles solo por mar. A bordo de un velero se descubren espacios paradisíacos con aguas cristalinas, brisas suaves y la posibilidad de combinar navegación con inmersiones de buceo o snorkel.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('07026', 'activo', 'Ibiza y Formentera en Velero', '¡Izad las velas! Ibiza y Formentera guardan tesoros accesibles solo por mar. A bordo de un velero se descubren espacios paradisíacos con aguas cristalinas, brisas suaves y la posibilidad de combinar navegación con inmersiones de buceo o snorkel.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('46259', 'activo', 'Río Cabriel', 'El río Cabriel es una referencia nacional del rafting y el packraft gracias a sus aguas revueltas y rápidos emocionantes. Varios días de descenso permiten acampar en sus riberas y disfrutar de kilómetros de naturaleza deshabitada. Una aventura llena de adrenalina en un entorno espectacular que atraviesa provincias del interior.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('46254', 'activo', 'Río Cabriel', 'El río Cabriel es una referencia nacional del rafting y el packraft gracias a sus aguas revueltas y rápidos emocionantes. Varios días de descenso permiten acampar en sus riberas y disfrutar de kilómetros de naturaleza deshabitada. Una aventura llena de adrenalina en un entorno espectacular que atraviesa provincias del interior.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('36011', 'activo', 'Rías Baixas', 'Las Rías Baixas ofrecen una navegación serena y auténtica entre islotes, costas indomables, hórreos colgados de acantilados y playas de fama mundial como Rodas. Jornadas tranquilas al ritmo de las palas permiten descubrir enclaves históricos y rincones de gran intimidad e inspiración.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('36015', 'activo', 'Rías Baixas', 'Las Rías Baixas ofrecen una navegación serena y auténtica entre islotes, costas indomables, hórreos colgados de acantilados y playas de fama mundial como Rodas. Jornadas tranquilas al ritmo de las palas permiten descubrir enclaves históricos y rincones de gran intimidad e inspiración.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('12040', 'activo', 'Islas Columbretes', 'Las Islas Columbretes son un destino emblemático para iniciarse en la navegación de altura. Desde el puerto de Grao de Castellón se pueden contratar jornadas de aprendizaje en aguas caprichosas del norte levantino, con la posibilidad de visitar este archipiélago si el tiempo lo permite.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('39032', 'activo', 'Río Ebro', 'Descender el río Ebro ayudados por la corriente es una de las grandes aventuras fluviales de España. Entre tres días y una semana, se exploran riberas ricas en paisajes y leyendas, con el Prepirineo, Sistema Ibérico y Picos de Europa como telón de fondo.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('43901', 'activo', 'Río Ebro', 'Descender el río Ebro ayudados por la corriente es una de las grandes aventuras fluviales de España. Entre tres días y una semana, se exploran riberas ricas en paisajes y leyendas, con el Prepirineo, Sistema Ibérico y Picos de Europa como telón de fondo.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('49275', 'activo', 'Río Duero', 'La travesía del río Duero se ha consolidado como un clásico de la aventura fluvial. Ocho etapas desde Zamora hasta Oporto recorren cañones, riberas pintorescas y paisajes modelados por el hombre. Una experiencia que combina navegación, cultura y el encanto de las gentes a ambos lados de la frontera.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('27045', 'activo', 'Río Navia', 'El río Navia ofrece 160 km de aguas mansas en un territorio indómito. Su nombre (que significa “navío”) refleja su navegabilidad histórica, ideal para una semana de singladura. Se desliza entre castros, aldeas olvidadas y profundos valles, siendo accesible para todo tipo de remeros.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('33041', 'activo', 'Río Navia', 'El río Navia ofrece 160 km de aguas mansas en un territorio indómito. Su nombre (que significa “navío”) refleja su navegabilidad histórica, ideal para una semana de singladura. Se desliza entre castros, aldeas olvidadas y profundos valles, siendo accesible para todo tipo de remeros.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('03003', 'activo', 'Costa Blanca', 'La Costa Blanca es uno de los litorales más propicios para la navegación en kayak o velero gracias a su clima benigno y excelentes playas. Hipnóticas poblaciones como Calp, Dénia o Xàbia y reservas como Sierra Helada sirven de referencia para descubrir cuevas y calas solo accesibles por mar.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('03014', 'activo', 'Costa Blanca', 'La Costa Blanca es uno de los litorales más propicios para la navegación en kayak o velero gracias a su clima benigno y excelentes playas. Hipnóticas poblaciones como Calp, Dénia o Xàbia y reservas como Sierra Helada sirven de referencia para descubrir cuevas y calas solo accesibles por mar.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('03022', 'activo', 'Costa Blanca', 'La Costa Blanca es uno de los litorales más propicios para la navegación en kayak o velero gracias a su clima benigno y excelentes playas. Hipnóticas poblaciones como Calp, Dénia o Xàbia y reservas como Sierra Helada sirven de referencia para descubrir cuevas y calas solo accesibles por mar.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('34120', 'ciclismo', 'Circuito de la Montaña Palentina', 'El Circuito de la Montaña Palentina es una ruta circular de bikepacking de dos o tres jornadas y casi 100 km. Rodea las imponentes montañas del norte de Palencia, faldeando cimas como el Curavacas y siguiendo pistas ganaderas por valles silenciosos.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('90628', 'ciclismo', 'Circuito Volcánico de Lanzarote', 'El Circuito Volcánico de Lanzarote es una espectacular ruta de mountain bike de 250 km y 3500 m de desnivel. Esta línea imaginaria rodea la isla completa en al menos cuatro jornadas, desde la costa de Teguise hasta Puerto del Carmen.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('35024', 'ciclismo', 'Circuito Volcánico de Lanzarote', 'El Circuito Volcánico de Lanzarote es una espectacular ruta de mountain bike de 250 km y 3500 m de desnivel. Esta línea imaginaria rodea la isla completa en al menos cuatro jornadas, desde la costa de Teguise hasta Puerto del Carmen.', 'mil_lugares');
