INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('35018', 'ciclismo', 'Circuito Volcánico de Lanzarote', 'El Circuito Volcánico de Lanzarote es una espectacular ruta de mountain bike de 250 km y 3500 m de desnivel. Esta línea imaginaria rodea la isla completa en al menos cuatro jornadas, desde la costa de Teguise hasta Puerto del Carmen.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('24106', 'ciclismo', 'Circuito Cantábrico de León', 'El Circuito Cantábrico de León recorre durante cinco etapas y 230 km los vigorosos contornos de la Cordillera Cantábrica. Esta osada ruta cicloturista atraviesa maravillas como los valles de Sajambre y Valdeón. Desiertos puertos de montaña y nieblas intimidantes exigen experiencia y buena orientación.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('24116', 'ciclismo', 'Circuito Cantábrico de León', 'El Circuito Cantábrico de León recorre durante cinco etapas y 230 km los vigorosos contornos de la Cordillera Cantábrica. Esta osada ruta cicloturista atraviesa maravillas como los valles de Sajambre y Valdeón. Desiertos puertos de montaña y nieblas intimidantes exigen experiencia y buena orientación.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('18903', 'ciclismo', 'Circuito de Sierra Nevada', 'El Circuito de Sierra Nevada es un sueño para ciclomontañeros. Sus cinco etapas y 236 km rodean todo el macizo, pasando por los grandes colosos que custodian Granada y los encantadores valles de la Alpujarra. Un viaje extraordinario por paisajes penibéticos de gran belleza y variedad.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('42009', 'ciclismo', 'Ruta del Císter', 'La Ruta del Císter es una gran clásica cicloturista de más de 100 km. Partiendo de Montblanc, ofrece un apacible y evocador recorrido por la historia medieval catalana, con especial protagonismo de los trascendentales monasterios construidos por la orden del Císter.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('43148', 'ciclismo', 'Ruta del Císter', 'La Ruta del Císter es una gran clásica cicloturista de más de 100 km. Partiendo de Montblanc, ofrece un apacible y evocador recorrido por la historia medieval catalana, con especial protagonismo de los trascendentales monasterios construidos por la orden del Císter.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('27008', 'ciclismo', 'Ruta del Císter', 'La Ruta del Císter es una gran clásica cicloturista de más de 100 km. Partiendo de Montblanc, ofrece un apacible y evocador recorrido por la historia medieval catalana, con especial protagonismo de los trascendentales monasterios construidos por la orden del Císter.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('39088', 'ciclismo', 'Vuelta al Macizo de Ándara', 'La Vuelta al Macizo de Ándara es un circuito corto pero muy impactante de poco más de 60 km con gran acumulación de desnivel. Aunque sus formaciones son más suaves que en otros macizos de los Picos de Europa, el paisaje sigue siendo asombroso.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('39022', 'ciclismo', 'Vuelta al Macizo de Ándara', 'La Vuelta al Macizo de Ándara es un circuito corto pero muy impactante de poco más de 60 km con gran acumulación de desnivel. Aunque sus formaciones son más suaves que en otros macizos de los Picos de Europa, el paisaje sigue siendo asombroso.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('18903', 'ciclismo', 'Ascensión al Veleta', 'La ascensión al Veleta (3398 m) es una de las escaladas en carretera más impresionantes de España. La carretera más alta de Europa permite pedalear hasta casi 3200 m, y luego continuar por repechos pedregosos hasta el vértice geodésico.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('18006', 'sendero', 'Sendero Histórico (GR-1)', 'El GR-1, conocido como Sendero Histórico, es una extensa travesía de 1600 km que recorre el norte de España. Sus marcas blancas y rojas comienzan en las ruinas grecorromanas de Empúries y terminan en Finisterre, atravesando comarcas, paisajes y poblaciones de gran peso histórico.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('01011', 'sendero', 'Sendero Histórico (GR-1)', 'El GR-1, conocido como Sendero Histórico, es una extensa travesía de 1600 km que recorre el norte de España. Sus marcas blancas y rojas comienzan en las ruinas grecorromanas de Empúries y terminan en Finisterre, atravesando comarcas, paisajes y poblaciones de gran peso histórico.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('50031', 'sendero', 'Ruta del Vino y del Pescado (GR-38)', 'La Ruta del Vino y del Pescado (GR-38) sigue antiguas vías de comercio entre los puertos cantábricos y los viñedos de La Rioja Alavesa. Sus seis etapas y unos 100 km pasan por pueblos, bosques, cañones y ciudades medievales como Laguardia o los montes de Toloño.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('48017', 'sendero', 'Ruta del Vino y del Pescado (GR-38)', 'La Ruta del Vino y del Pescado (GR-38) sigue antiguas vías de comercio entre los puertos cantábricos y los viñedos de La Rioja Alavesa. Sus seis etapas y unos 100 km pasan por pueblos, bosques, cañones y ciudades medievales como Laguardia o los montes de Toloño.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('09109', 'sendero', 'Ruta del Vino y del Pescado (GR-38)', 'La Ruta del Vino y del Pescado (GR-38) sigue antiguas vías de comercio entre los puertos cantábricos y los viñedos de La Rioja Alavesa. Sus seis etapas y unos 100 km pasan por pueblos, bosques, cañones y ciudades medievales como Laguardia o los montes de Toloño.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('11035', 'sendero', 'Senda del Mediterráneo', 'La Senda del Mediterráneo recorre casi 600 km de costa desde la frontera francesa hasta Tarifa. Siguiendo antiguos caminos de romanos, pescadores y carabineros, ofrece bahías, cabos, calas y un rico patrimonio histórico. Una ruta de contrastes paisajísticos y culturales a lo largo de cuatro comunidades autónomas.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('10904', 'sendero', 'Sendero del Valle del Tiétar (GR-180)', 'El GR-180 (207 km) ofrece más de una semana de senderismo emocionante por las grandiosas vertientes de Gredos y el acogedor Valle del Tiétar. Gargantas esculpidas por el deshielo, calzadas romanas, castros celtas y aldeas con gran herencia histórica conforman el recorrido.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('22125', 'sendero', 'Senderos de la Ribagorza (GR-18)', 'El GR-18 recorre de sur a norte la antigua Ribagorza, territorio fronterizo de gran importancia histórica. Pequeños pueblos hoy casi despoblados, valles glaciares, olivos y frutales configuran un paisaje anclado en el tiempo.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('19165', 'sendero', 'Sendero de la Arquitectura Negra', 'El Sendero de la Arquitectura Negra recorre la sierra de Ayllón en cinco etapas, visitando pueblos construidos con un estilo tradicional inspirado en la naturaleza. Un recorrido por ambientes ásperos y un insólito legado etnográfico.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('19060', 'sendero', 'Sendero de la Arquitectura Negra', 'El Sendero de la Arquitectura Negra recorre la sierra de Ayllón en cinco etapas, visitando pueblos construidos con un estilo tradicional inspirado en la naturaleza. Un recorrido por ambientes ásperos y un insólito legado etnográfico.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('19311', 'sendero', 'Sendero de la Arquitectura Negra', 'El Sendero de la Arquitectura Negra recorre la sierra de Ayllón en cinco etapas, visitando pueblos construidos con un estilo tradicional inspirado en la naturaleza. Un recorrido por ambientes ásperos y un insólito legado etnográfico.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('19262', 'sendero', 'Sendero de la Arquitectura Negra', 'El Sendero de la Arquitectura Negra recorre la sierra de Ayllón en cinco etapas, visitando pueblos construidos con un estilo tradicional inspirado en la naturaleza. Un recorrido por ambientes ásperos y un insólito legado etnográfico.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('26061', 'sendero', 'Ruedas de Lana', 'Ruedas de Lana es una ruta cicloturista circular de 270 km por la sierra de la Demanda. En una semana se recorren cañadas, montes y villas ligadas a la trashumancia, con valles de los ríos Oja, Iregua y Najerilla. Una experiencia llena de contrastes culturales e históricos.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('23028', 'sendero', 'Bosques del Sur (GR-247)', 'El GR-247, conocido como Bosques del Sur, recorre casi 500 km por el corazón del Parque Natural de Cazorla, Segura y las Villas. Un mosaico de montañas arrogantes, viejos castillos, cascadas y olivos susurrantes conforman el paisaje.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('15078', 'sendero', 'Sendero Rural de Galicia', 'El Sendero Rural de Galicia es una ruta de 130 km que sumerge al caminante en el denso mundo rural gallego. Desde Vigo hasta Santiago, sigue antiguas arterias que conectan rostros del pasado y el mágico corazón de Galicia. Una experiencia llena de brumas, misterios y autenticidad rural.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('36015', 'sendero', 'Sendero Rural de Galicia', 'El Sendero Rural de Galicia es una ruta de 130 km que sumerge al caminante en el denso mundo rural gallego. Desde Vigo hasta Santiago, sigue antiguas arterias que conectan rostros del pasado y el mágico corazón de Galicia. Una experiencia llena de brumas, misterios y autenticidad rural.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('22173', 'sendero', 'En una hamaca en Riglos', 'Dormir colgado en una hamaca a 100 metros de altura sobre los imponentes Mallos de Riglos es una experiencia única. Inspirada en las míticas escenas de Yosemite o Patagonia, la Rab Riglos Suite permite vivir noches inolvidables frente a uno de los paisajes más legendarios para los escaladores.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('42189', 'sendero', 'Al raso en el río Lobos', 'Pernoctar al aire libre en la pradera del cañón del río Lobos, junto a la ermita templaria de San Bartolomé, es una experiencia inolvidable. Declarado Parque Natural en 1985, este desfiladero ofrece un escenario mágico rodeado de paredes verticales, cuevas y una atmósfera mística.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('39015', 'sendero', 'Cabaña Verónica', 'La Cabaña Verónica es uno de los refugios más míticos de la Península. Situada a 2325 m en las estribaciones del pico Tesorero, esta pequeña cúpula metálica (extraída de un portaaviones estadounidense) ofrece una experiencia única en el corazón de los Picos de Europa.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('38007', 'sendero', 'Bajo la niebla de la laurisilva', 'La laurisilva de La Gomera es uno de los bosques más mágicos del mundo. Aunque está prohibido pernoctar dentro del Parque Nacional de Garajonay, en otros rincones limítrofes brumosos y encantadores es posible dormir bajo las estrellas o en zonas recreativas.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('42078', 'sendero', 'En la Laguna Helada', 'La Laguna Helada, oculta en los Picos de Urbión, es una de las grandes joyas glaciares de la Península. Accesible tras una caminata de 9 km a través de pinares monumentales, ofrece un entorno solitario y espectacular, especialmente en primavera e invierno.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('28068', 'sendero', 'Cara norte del Peñalara', 'La cara norte del Peñalara ofrece un paisaje salvaje y solitario, ideal para evocar leyendas montañeras. La ruta hasta la cima atraviesa majadas, viejos pinares y puertos históricos como el del Reventón. Con buen desnivel y exigencia, es perfecta para dos jornadas de vivac con vistas impresionantes.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('25017', 'sendero', 'Pica d''Estats', 'La Pica d’Estats, con sus más de 3000 m, es la cima más alta del Pirineo catalán. Este torreón vigila la frontera con Francia y ofrece un espectáculo de lagos y circos glaciares. Una travesía intensa de varias jornadas por un macizo exigente y bello.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('28068', 'sendero', 'Pradera del Yelmo', 'La Pradera del Yelmo es un lugar mítico en la Sierra de Guadarrama. Sus formaciones graníticas crean un laberinto espectacular con una gran roca rosada que se tiñe de plata bajo la luna. Pernoctar en la pradera a sus pies es una aventura imprescindible para escaladores y amantes de la naturaleza.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('90958', 'sendero', 'Sobre las copas de Zeanuri', 'En los límites del Parque Natural de Gorbea, Zeanuri ofrece una inmersión total en la naturaleza. Dormir en una cabaña posada en un majestuoso árbol o en un viejo carro zíngaro es una experiencia romántica y única. Un lugar perfecto para desconectar y disfrutar de la gastronomía vasca en pleno bosque.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('22199', 'sendero', 'En el ibón de Bucuesa', 'El ibón de Bucuesa, a 2190 m, es un rincón cristalino en la sierra de la Partacua. Sus aguas dan origen al río Aurín y ofrecen un atardecer grandioso con vistas al Balaitus, el Arriel y otras cumbres del Pirineo aragonés. Un emplazamiento ideal para pernoctar en alta montaña.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('40024', 'sendero', 'Vuelta al macizo de Ayllón', 'La Vuelta al macizo de Ayllón es una ruta cicloturista de tres etapas y unos 170 km. Recorre los paisajes más desconocidos del Sistema Central, con pueblos negros y joyas ambientales de gran categoría. Una travesía ideal para descubrir la tierra vacía y hermosa de Ayllón.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('18903', 'sendero', 'Laguna de la Mosca', 'La Laguna de la Mosca es uno de los rincones más insólitos de Sierra Nevada. Senderos exigentes como la Vereda de la Estrella llevan a este lugar donde es posible pernoctar cerca de los grandes tresmiles. Un destino mágico para noches de alta montaña.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('44037', 'sendero', 'Travesía de Els Ports', 'La Travesía de Els Ports conecta las provincias de Teruel, Castellón y Tarragona a través de un escarpado cordón montañoso. En tres etapas se recorren relieves vitales y abruptos, con cañones y bosques oceánicos.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('43071', 'sendero', 'Travesía de Els Ports', 'La Travesía de Els Ports conecta las provincias de Teruel, Castellón y Tarragona a través de un escarpado cordón montañoso. En tres etapas se recorren relieves vitales y abruptos, con cañones y bosques oceánicos.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('05004', 'sendero', 'Vuelta al Naranjo de Bulnes', 'La Vuelta al Naranjo de Bulnes (Picu Urriellu) es un mito para los amantes de la montaña. Su cara oeste, una pared de 500 m, es legendaria. Existe una pequeña ruta de 20 km que permite rodear este colmillo asturiano.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('04017', 'sendero', 'Parque Natural del Cabo de Gata', 'El Parque Natural de Cabo de Gata es un mosaico de rincones costeros fascinantes: playas y calas escondidas, formas caprichosas, colores intensos y bellezas petrificadas. Pueblos pesqueros, antiguos refugios de piratas y la luz cálida del Mediterráneo sobre un paisaje volcánico singular hacen de este lugar uno de los más especiales de España.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('38004', 'sendero', 'El Hierro', 'El Hierro es un ejemplo de sostenibilidad y biodiversidad en el archipiélago canario. Sus bosques de laurisilva, piscinas naturales y cráteres volcánicos ofrecen un sinfín de contrastes, ideales para kayak, buceo, mountain bike o simplemente dejarse llevar por sus brisas.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('50251', 'sendero', 'A los pies del Moncayo', 'El Moncayo reina soberbio sobre valles de antiguas culturas. Selvas centenarias de hayas y robles cubren sus faldas, y los campos somontanos de Soria y Aragón custodian sus accesos. Declarado Parque Natural en 1979, es posible circunvalarlo a pie o en mountain bike, disfrutando de un paisaje de arroyos, huertas y pasado.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('50234', 'sendero', 'A los pies del Moncayo', 'El Moncayo reina soberbio sobre valles de antiguas culturas. Selvas centenarias de hayas y robles cubren sus faldas, y los campos somontanos de Soria y Aragón custodian sus accesos. Declarado Parque Natural en 1979, es posible circunvalarlo a pie o en mountain bike, disfrutando de un paisaje de arroyos, huertas y pasado.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('41011', 'sendero', 'A los pies del Moncayo', 'El Moncayo reina soberbio sobre valles de antiguas culturas. Selvas centenarias de hayas y robles cubren sus faldas, y los campos somontanos de Soria y Aragón custodian sus accesos. Declarado Parque Natural en 1979, es posible circunvalarlo a pie o en mountain bike, disfrutando de un paisaje de arroyos, huertas y pasado.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('22054', 'sendero', 'Al Posets por el valle de Eriste', 'El Posets (3375 m) es la segunda cima más alta de los Pirineos. La ascensión por el valle de Eriste, con noche en el refugio del Forcau, es una experiencia clásica y elegante. Conocida como La Ruta Real, ofrece paisajes aéreos y un reto accesible para montañeros.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('28068', 'sendero', 'Macizo de Cuerda Larga', 'La travesía del Macizo de Cuerda Larga es una de las clásicas de la Sierra de Guadarrama. Conecta puertos y cumbres notables por encima de los 2000 m, con vistas grandiosas y pasos emocionantes.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('33036', 'sendero', 'Surfeando Llanes', 'La costa de Llanes ofrece un catálogo de playas extenso y variado. Apuntarse a un surfcamp permite descubrir olas de calidad en spots como Torimbia, Portiellos o San Martín. Una experiencia perfecta para combinar surf y los bosques de la sierra de Cuera.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('32071', 'mirador', 'Miradores de la Ribeira Sacra', 'Los bravos desfiladeros tallados por los ríos Miño y Sil, con cicatrices milenarias, monasterios y bosques de robles y castaños, conforman uno de los paisajes fluviales más fabulosos de Galicia. Los miradores de la Ribeira Sacra ofrecen una experiencia viva del mundo rural y la espiritualidad gallega.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('39015', 'sendero', 'Canal de la Jenduda', 'El Canal de la Jenduda es una gran opción montañera que salva 800 m de desnivel. Esta ruta técnica, con trepada y sensación de cuerda fija, concentra en 3 km belleza y exigencia. Un terreno vertiginoso y aventurero donde se recomienda llevar casco.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('33062', 'poza', 'Cascada de la Seimeira', 'La Cascada de la Seimeira, de 30 m de altura, es uno de los saltos más evocadores del occidente asturiano. Una ruta corta y apacible de poco más de 6 km lleva hasta este lugar envuelto en una espesura susurrante.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('01007', 'sendero', 'Monte Pindo', 'El Monte Pindo, conocido como el "Olimpo celta", es hogar de mitos y curiosas esculturas rocosas. Un sendero de 10 km permite conocer uno de los sitios más icónicos del litoral gallego.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('14001', 'sendero', 'Hoz de Alarcón', 'La Hoz de Alarcón es una ruta que sumerge al viajero en fortines y farallones con vistas incomparables. El río Júcar ha tallado hoces espectaculares, con meandros y fortificaciones históricas.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('12139', 'sendero', 'Penyagolosa por la Pregunta', 'La ruta Penyagolosa por la Pregunta asciende a la icónica cima (1815 m) a través del antiguo cenobio de Sant Joan de Penyagolosa. Una ascensión atractiva y accesible en el Maestrazgo.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('26061', 'sendero', 'Los Siete Puentes', 'Los Siete Puentes es una ruta circular asequible que asciende el río Usaya buscando los siete puentes que cruzan su cauce. Un fascinante recorrido por valles y contrastes riojanos.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('33068', 'sendero', 'Lagos de Saliencia', 'Los Lagos de Saliencia son uno de los tesoros glaciares de Somiedo. Un entorno alpino con brañas, bosques y cimas que ofrece una travesía fabulosa.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('28068', 'sendero', 'El dragón de piedra', 'Los Siete Picos, conocidos popularmente como "El dragón de piedra", forman una imponente alineación de crestas graníticas que se elevan como la espina dorsal de un gigantesco dragón dormido. Esta formación geológica, una de las más singulares de la Sierra de Guadarrama, ofrece vistas panorámicas espectaculares y es un paraíso para senderistas y escaladores.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('33044', 'sendero', 'Desfiladero de las Xanas', 'El Desfiladero de las Xanas es un estrecho y espectacular cañón horadado por el río homónimo, donde las paredes verticales y la vegetación exuberante crean un entorno de cuento. La ruta de unos 6 km (con algunos tramos aéreos y exigentes) es ideal para familias aventureras y culmina en un paisaje de gran belleza.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('23001', 'sendero', 'Castiello de Tou', 'El Castiello de Tou, ruinas de un antiguo castillo medieval, se alza como un centinela eterno sobre el río Cinca y el valle de Aínsa. Desde sus restos se disfruta de una panorámica excepcional del Pirineo aragonés. Es un lugar cargado de historia que combina patrimonio y naturaleza en uno de los entornos más bellos del Sobrarbe.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('30036', 'sendero', 'Parque Regional Salinas de San Pedro', 'El Parque Regional Salinas de San Pedro es un humedal costero de gran valor ecológico donde molinos de viento, flamencos, dunas y playas se combinan en un paisaje único. Es uno de los mejores lugares de la Región de Murcia para la observación de aves (cormoranes, garzas, somormujos) y para disfrutar de la brisa marina en un entorno de alta biodiversidad.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('33064', 'sendero', 'Senda del Oso', 'La Senda del Oso es una de las vías verdes más bonitas y familiares de Asturias. Siguiendo el trazado de un antiguo ferrocarril minero, discurre entre cañones, puentes y bosques, ofreciendo la posibilidad de ver osos pardos en su cercado final.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('33072', 'sendero', 'Senda del Oso', 'La Senda del Oso es una de las vías verdes más bonitas y familiares de Asturias. Siguiendo el trazado de un antiguo ferrocarril minero, discurre entre cañones, puentes y bosques, ofreciendo la posibilidad de ver osos pardos en su cercado final.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('33052', 'sendero', 'Senda del Oso', 'La Senda del Oso es una de las vías verdes más bonitas y familiares de Asturias. Siguiendo el trazado de un antiguo ferrocarril minero, discurre entre cañones, puentes y bosques, ofreciendo la posibilidad de ver osos pardos en su cercado final.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('33053', 'sendero', 'Senda del Oso', 'La Senda del Oso es una de las vías verdes más bonitas y familiares de Asturias. Siguiendo el trazado de un antiguo ferrocarril minero, discurre entre cañones, puentes y bosques, ofreciendo la posibilidad de ver osos pardos en su cercado final.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('38002', 'sendero', 'Las vueltas de Taganana', 'Las vueltas de Taganana recorren uno de los rincones más salvajes y bellos del macizo de Anaga en Tenerife. Caminos entre densos bosques de fayas y brezales, cuevas ancestrales y vistas a las costas abruptas hacen de esta ruta una joya del norte de la isla.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('16041', 'sendero', 'Las Caras de Buendía', 'Las Caras de Buendía son un conjunto de impresionantes esculturas talladas directamente en la roca por maestros canteros de la Edad Media. Este singular galería al aire libre, ubicada en los bosques cercanos al embalse de Buendía, ofrece un ambiente misterioso y artístico.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('28068', 'espacio', 'Peñas del Arcipreste de Hita', 'Las Peñas del Arcipreste de Hita son formaciones rocosas singulares inmortalizadas por Juan Ruiz en el Libro del Buen Amor. Declaradas monumento natural en 1930, estas caprichosas peñas de granito ofrecen un paisaje de gran belleza, con senderos ligeros que atraviesan pinares y formaciones llamativas.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('05004', 'cueva', 'Una cueva secreta', 'Esta cueva de hielo, conocida como Peña Castil, es un lugar casi secreto donde se mantienen formaciones de hielo milenarias. Oculta en las entrañas de los Picos de Europa, es un enclave místico que requiere experiencia para visitar.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('38007', 'espacio', 'Pilares de los Órganos', 'Los Pilares de los Órganos son impresionantes formaciones rocosas de origen volcánico que recuerdan los tubos de un órgano gigante. Levantándose a decenas de metros sobre acantilados, estas columnas basálticas son accesibles solo por mar o con dificultad, confiriéndoles un carácter aventurero único en La Gomera.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('33036', 'espacio', 'Bufones de Pría', 'Los Bufones de Pría son un fenómeno natural espectacular donde el mar "respira" a través de grietas y chimeneas en los acantilados. Explosiones de agua y espuma surgen con fuerza, creando un espectáculo sonoro y visual único en la costa asturiana.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('90863', 'espacio', 'Bosque de las Blancas', 'El Bosque de las Blancas es un paraje de gran valor botánico en el Rincón de Ademuz. Sabinas monumentales y milenarias, junto con restos de bosques antiguos, crean un ambiente cargado de historia y tradición. Un lugar donde se pueden encontrar fósiles y disfrutar de la serenidad de un bosque mediterráneo singular.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('50067', 'espacio', 'Castillos de Armantes', 'Los Castillos de Armantes son impresionantes formaciones de arenisca que parecen torres y castillos erosionados. Antiguo escondite de bandoleros, este paisaje de "badlands" ofrece un escenario de western con torres, colmados y vistas espectaculares.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('19099', 'espacio', 'Barranco de la Hoz', 'El Barranco de la Hoz es un cañón espectacular labrado por el río Gallo. Sus paredes verticales y el bosque mediterráneo crean un entorno salvaje y bello. La senda permite disfrutar de uno de los paisajes más impresionantes del Alto Tajo.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('19311', 'espacio', 'El Ocejón', 'El Ocejón es una cima emblemática y arrogante de la sierra de Ayllón. Con 2.049 m, ofrece vistas excepcionales y un entorno de gran belleza. Una ascensión clásica y gratificante en el Sistema Central.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('19165', 'espacio', 'El Ocejón', 'El Ocejón es una cima emblemática y arrogante de la sierra de Ayllón. Con 2.049 m, ofrece vistas excepcionales y un entorno de gran belleza. Una ascensión clásica y gratificante en el Sistema Central.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('09109', 'espacio', 'Las Gobas de Laño', 'Las Gobas de Laño son un conjunto de cuevas rupestres excavadas en la roca caliza, utilizadas como refugio eremítico en la época visigoda. Este santuario rupestre es uno de los tesoros ocultos de Burgos, cargado de historia y misticismo.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('17199', 'activo', 'Illes Medes', 'Las Illes Medes son una Reserva Marina desde 1990 y uno de los puntos de buceo más icónicos de España. Los siete islotes frente a L’Estartit ofrecen una gran variedad de inmersiones para todos los niveles: cuevas, pecios como el Reggio Messina o el Avenire, fondos coralígenos y praderas de posidonia en excelente estado.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('38004', 'activo', 'El Hierro', 'El Hierro es uno de los mejores destinos nacionales para el buceo. Sus aguas cristalinas, morfología volcánica y temperaturas benignas durante todo el año invitan a explorar fondos ricos en vida marina mediterránea y atlántica. Un lugar ideal para buceadores de todos los niveles.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('04017', 'activo', 'Cabo de Gata', 'Los fondos marinos de Cabo de Gata son de los más ricos del Mediterráneo español. Barrancos submarinos, praderas de posidonia y pecios conviven en aguas de gran visibilidad. Un paraíso para el buceo con gran biodiversidad y paisajes volcánicos bajo el mar.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('07037', 'activo', 'Menorca', 'La Reserva Marina de Cavalleria en Menorca ofrece fondos rocosos y variados con excelente visibilidad. Sus abruptos farallones y la protección del área la convierten en un destino ideal para inmersiones con gran vida marina.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('35028', 'activo', 'Lanzarote', 'Lanzarote ofrece buceo en aguas cálidas y tranquilas con fondos volcánicos únicos. Sus corrientes serenas y la abundante vida marina la convierten en un destino perfecto para bautizos y buceadores experimentados.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('23028', 'ciclismo', 'Cuerda de las Banderillas', 'La Cuerda de las Banderillas es una ruta circular de mountain bike de 40 km por pistas y senderos que atraviesa las impresionantes sierras de Cazorla. Esta travesía exigente ofrece paisajes de gran belleza, con formaciones rocosas, bosques y vistas panorámicas en una de las zonas más salvajes de Andalucía.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('90714', 'ciclismo', 'Bosques de Urbasa', 'Los Bosques de Urbasa ofrecen una ruta cicloturista de 52 km con desnivel notable. Partiendo del camping de Urbasa, se recorren pistas ganaderas a través de hayedos, abetos y valles con encanto. Un recorrido por uno de los bosques más bellos de Navarra, con paisajes de gran serenidad.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('44037', 'ciclismo', 'Puertos de Beceite', 'Los Puertos de Beceite son un "rutón" de 50 km por el Matarraña y Els Ports. Naturaleza pura, laberintos forestales, balcones naturales y pistas forestales hacen de esta ruta un clásico para mountain bike en uno de los entornos más bonitos del Bajo Aragón.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('16078', 'mirador', 'Miradores de Uña', 'Los Miradores de Uña recorren la serranía conquense con paisajes kársticos, formaciones rocosas y valles profundos. Un recorrido que combina naturaleza y miradores espectaculares, ideal para disfrutar de la belleza interior de Castilla-La Mancha.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('18134', 'ciclismo', 'Vuelta al Trevenque', 'La Vuelta al Trevenque (2083 m) es un clásico de la media montaña nevadense. Sus más de 40 km con desnivel importante ofrecen contrastes de texturas y colores, con un descenso posterior lleno de adrenalina. Una ruta exigente pero muy gratificante.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('18903', 'ciclismo', 'Vuelta al Trevenque', 'La Vuelta al Trevenque (2083 m) es un clásico de la media montaña nevadense. Sus más de 40 km con desnivel importante ofrecen contrastes de texturas y colores, con un descenso posterior lleno de adrenalina. Una ruta exigente pero muy gratificante.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('90958', 'ciclismo', 'Cruz del Gorbea', 'La Cruz del Gorbea es una ruta ciclomontañera que parte de la zona recreativa de Sarria y llega al icónico pico del Gorbea. 32 km de pistas y sendas con vistas excepcionales y un final en la famosa cruz de hierro. Una de las rutas más emblemáticas del País Vasco.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('50042', 'ciclismo', 'Cruz del Gorbea', 'La Cruz del Gorbea es una ruta ciclomontañera que parte de la zona recreativa de Sarria y llega al icónico pico del Gorbea. 32 km de pistas y sendas con vistas excepcionales y un final en la famosa cruz de hierro. Una de las rutas más emblemáticas del País Vasco.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('22215', 'ciclismo', 'Sierra de Chía', 'La Sierra de Chía ofrece una travesía circular de alta montaña con cimas, hayedos y abetos. Partiendo de Seira, el GR-15 recorre valles glaciares y paisajes pirenaicos de gran belleza.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('28143', 'ciclismo', 'Vuelta a Guadarrama', 'La Vuelta a Guadarrama es un recorrido integral por los puertos de Somosierra y Fuenfría, conectando Segovia y Madrid. Valles, collados y cañadas ofrecen un viaje lleno de contrastes entre las dos mesetas.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('24194', 'cueva', 'Cueva de Valporquero', 'La Cueva de Valporquero es uno de los tesoros subterráneos más impresionantes de España. Con más de 3 km de galerías exploradas, destaca por sus espectaculares formaciones de estalactitas, estalagmitas y columnas de gran tamaño. Su belleza cristalina y la diversidad de salas la convierten en una cita imprescindible para amantes de la espeleología y el turismo subterráneo.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('12126', 'cueva', 'Coves de Sant Josep', 'Las Coves de Sant Josep son las cuevas con río subterráneo navegable más largas de Europa. Con casi 1 km de recorrido turístico en barca, destacan por sus salas con formaciones milenarias y un ambiente mágico. Un viaje subterráneo único que combina navegación y espeleología en un entorno de gran belleza.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('51001', 'cueva', 'Cuevas del Águila', 'Las Cuevas del Águila son una gruta viva con estalactitas y estalagmitas en continuo crecimiento. Sus formaciones cristalinas y la iluminación cuidadosa crean un espectáculo subterráneo de gran belleza. Una cueva accesible y bien acondicionada, perfecta para descubrir el mundo subterráneo de la provincia de Ávila.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('39076', 'cueva', 'Cuevas de Altamira', 'Las Cuevas de Altamira, conocidas como la "Capilla Sixtina del Paleolítico", albergan las manifestaciones artísticas más importantes del arte rupestre. Aunque la original está cerrada al público por conservación, la réplica exacta (Neocueva) permite admirar los famosos bisontes y figuras policromadas.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('39091', 'cueva', 'Cueva El Soplao', 'La Cueva El Soplao es uno de los sistemas de cuevas más espectaculares de España. Con más de 15 km de galerías, destaca por sus formaciones geológicas únicas y restos mineros. Abierta al público, ofrece un universo prístico y cristalino que combina geología, historia minera y belleza natural.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('29075', 'cueva', 'Cuevas de Nerja', 'Las Cuevas de Nerja son uno de los mayores atractivos turísticos de Andalucía. Con más de 1 km de galerías visitables, destacan por sus impresionantes formaciones, lagos y salas de gran tamaño. Descubiertas en 1959, son un tesoro paleontológico y geológico de primer orden.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('22004', 'cueva', 'Gruta de las Maravillas', 'La Gruta de las Maravillas es una de las cuevas turísticas más antiguas de España (abierta desde 1914). Sus más de 1 km de galerías ofrecen formaciones imposibles, lagos y salas inundadas de belleza. Un clásico del turismo subterráneo en la sierra de Aracena.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('33056', 'cueva', 'Cuevona de Cueves', 'La Cuevona de Cueves es una galería natural que sirve de túnel de acceso al pueblo en coche. Sus 300 m de longitud albergan formaciones calcáreas impresionantes y una atmósfera misteriosa con vida subterránea (ranas y salamandras).', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('22002', 'activo', 'Parque Nacional de Doñana', 'El Parque Nacional de Doñana es uno de los espacios naturales más importantes de Europa. Declarado Reserva de la Biosfera y Patrimonio Mundial, ofrece marismas, dunas, bosques y una biodiversidad única, incluyendo al lince ibérico.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('21040', 'activo', 'Parque Nacional de Doñana', 'El Parque Nacional de Doñana es uno de los espacios naturales más importantes de Europa. Declarado Reserva de la Biosfera y Patrimonio Mundial, ofrece marismas, dunas, bosques y una biodiversidad única, incluyendo al lince ibérico.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('13072', 'activo', 'Parque Nacional de Cabañeros', 'Cabañeros es conocido como el "Serengeti español" por su riqueza en fauna. Una ruta sencilla de unas horas permite descubrir sus paisajes fluviales, dehesas y puntos de interés como la villa de Robledo o la junta de los ríos. Un lugar ideal para disfrutar de la naturaleza en estado puro a lomos de un caballo.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('13049', 'activo', 'Parque Nacional de Cabañeros', 'Cabañeros es conocido como el "Serengeti español" por su riqueza en fauna. Una ruta sencilla de unas horas permite descubrir sus paisajes fluviales, dehesas y puntos de interés como la villa de Robledo o la junta de los ríos. Un lugar ideal para disfrutar de la naturaleza en estado puro a lomos de un caballo.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('50251', 'activo', 'Parque Natural del Moncayo', 'El Moncayo, techo del Sistema Ibérico, ofrece rutas a caballo que combinan selvas de hayas y robles con paisajes de alta montaña. Sus contrastes y la belleza de sus valles lo convierten en un destino perfecto para jinetes que buscan naturaleza salvaje y vistas panorámicas.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('50234', 'activo', 'Parque Natural del Moncayo', 'El Moncayo, techo del Sistema Ibérico, ofrece rutas a caballo que combinan selvas de hayas y robles con paisajes de alta montaña. Sus contrastes y la belleza de sus valles lo convierten en un destino perfecto para jinetes que buscan naturaleza salvaje y vistas panorámicas.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('51003', 'activo', 'Cordel de El Barco de Ávila', 'El Cordel de El Barco de Ávila sigue antiguas vías de trashumancia paralelas al río Tormes. La calzada romana y los paisajes de Gredos ofrecen una experiencia ecuestre llena de historia y belleza natural.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('08139', 'activo', 'Les Valls del Montcau', 'Las Valls del Montcau ofrecen rutas a caballo por un paisaje de pinos y rocas con gran valor natural. A 70 km de Barcelona, este parque es ideal para combinar deporte y naturaleza en un entorno mediterráneo.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('05089', 'activo', 'La bella Guisando', 'La bella Guisando ofrece rutas a caballo por valles y riberas con gran encanto. Un lugar perfecto para disfrutar de paisajes tranquilos y patrimonio en la provincia de Ávila.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('17114', 'activo', 'La Garrotxa', 'Volando en globo sobre la Zona Volcánica de la Garrotxa se descubre uno de los mejores ejemplos de paisaje volcánico del interior peninsular. Los conos volcánicos inactivos, valles y bosques ofrecen una panorámica inolvidable desde el aire.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('18087', 'activo', 'Granada', 'Granada ofrece uno de los mejores escenarios de España para volar en parapente o paramotor. Desde Cenes de la Vega, los vuelos permiten contemplar la majestuosidad de Sierra Nevada y la Vega desde el aire, con vistas panorámicas que alcanzan los 1500 m de altitud.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('18903', 'activo', 'Granada', 'Granada ofrece uno de los mejores escenarios de España para volar en parapente o paramotor. Desde Cenes de la Vega, los vuelos permiten contemplar la majestuosidad de Sierra Nevada y la Vega desde el aire, con vistas panorámicas que alcanzan los 1500 m de altitud.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('22084', 'activo', 'Castejón de Sos', 'Castejón de Sos es uno de los mejores spots de vuelo libre en los Pirineos. Desde sus laderas se pueden contemplar valles, ríos y cimas imponentes. Un lugar perfecto para parapente y paramotor con condiciones excelentes y paisajes espectaculares.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('22054', 'activo', 'Castejón de Sos', 'Castejón de Sos es uno de los mejores spots de vuelo libre en los Pirineos. Desde sus laderas se pueden contemplar valles, ríos y cimas imponentes. Un lugar perfecto para parapente y paramotor con condiciones excelentes y paisajes espectaculares.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('27015', 'activo', 'Vall dÀger', 'La Vall d’Àger es un paraíso del vuelo libre con ala delta y parapente. Sus condiciones térmicas excepcionales y la variedad de despegues la convierten en un destino internacional. Vuelos sobre el embalse de Camarasa y las cumbres del Prepirineo catalán ofrecen experiencias inolvidables.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('08014', 'activo', 'Montserrat', 'Montserrat es un lugar mítico para el vuelo libre. Sus agujas rocosas y el monasterio ofrecen un telón de fondo espectacular. Los vuelos desde sus paredes permiten contemplar el macizo y el paisaje catalán desde una perspectiva única.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('45168', 'activo', 'Toledo', 'Volar sobre Toledo permite contemplar la ciudad de las tres culturas desde el aire. El Tajo, la Alcazaba y el casco histórico ofrecen una vista panorámica impresionante que revela la grandeza de esta ciudad patrimonio de la humanidad.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('48085', 'activo', 'Sopelana', 'Sopelana es uno de los puntos más prestigiosos para el parapente en el País Vasco. Sus acantilados y la cercanía al mar ofrecen vuelos con vistas al Cantábrico y la costa vizcaína. Un lugar ideal para combinar mar y montaña.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('27015', 'activo', 'Montsec', 'El Montsec es una de las zonas más cotizadas de Cataluña para el vuelo libre. Sus condiciones térmicas y el paisaje del Prepirineo la convierten en sede de campeonatos internacionales. Vuelos sobre el Congost de Mont-rebei y el embalse ofrecen experiencias espectaculares.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('38001', 'fauna', 'Cachalote (avistamiento)', 'La costa sur de Tenerife, con sus profundas gargantas submarinas que descienden hasta 1000 m, es uno de los mejores lugares de España para observar cetáceos. El cachalote, el gran mamífero marino que utiliza estas profundidades como punto de paso todo el año, es la estrella.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('90776', 'fauna', 'Cachalote (avistamiento)', 'La costa sur de Tenerife, con sus profundas gargantas submarinas que descienden hasta 1000 m, es uno de los mejores lugares de España para observar cetáceos. El cachalote, el gran mamífero marino que utiliza estas profundidades como punto de paso todo el año, es la estrella.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('49262', 'fauna', 'Lobo ibérico', 'El lobo ibérico está recuperando terreno gracias a medidas de protección. En la sierra de la Culebra y otros montes del noroeste de Zamora, es posible avistarlo en su hábitat natural. Su presencia simboliza la recuperación de la fauna salvaje y es un reclamo turístico respetuoso.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('49166', 'fauna', 'Lobo ibérico', 'El lobo ibérico está recuperando terreno gracias a medidas de protección. En la sierra de la Culebra y otros montes del noroeste de Zamora, es posible avistarlo en su hábitat natural. Su presencia simboliza la recuperación de la fauna salvaje y es un reclamo turístico respetuoso.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('11035', 'fauna', 'Orca cazadora', 'Las orcas del estrecho de Gibraltar son uno de los espectáculos más impresionantes de la fauna marina europea. Durante los meses de verano, estas poderosas cazadoras persiguen a los atunes rojos frente a las costas de Tarifa. Observarlas es una experiencia única y emocionante.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('24005', 'fauna', 'El gran gato (Lince ibérico)', 'El lince ibérico, el gran gato de España, es una de las especies más amenazadas y emblemáticas de Europa. En Andújar y Doñana, gracias a los programas de recuperación, es posible avistarlo con algo de suerte. Su presencia es símbolo de la conservación exitosa de la fauna ibérica.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('30026', 'fauna', 'Delfines de todos los colores', 'El golfo de Mazarrón y Cabo Tiñoso son excelentes puntos para observar delfines (listados, mulares, calderones). Las salidas desde Mazarrón permiten disfrutar de estos inteligentes mamíferos marinos en un entorno protegido.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('33068', 'fauna', 'Oso pardo', 'El oso pardo cantábrico encuentra refugio en Somiedo y otros valles asturianos. Aunque es difícil avistarlo, las agencias de observación ofrecen experiencias respetuosas que permiten sentir la presencia del gran mamífero europeo.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('90058', 'fauna', 'Rorcual', 'El rorcual, uno de los grandes cetáceos del Cantábrico, se observa en las aguas vascas. Las salidas de observación desde puertos como Santurtzi permiten disfrutar de estos gigantes marinos en su hábitat.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('07026', 'fauna', 'Gineta', 'La gineta, un elusivo felino, se ha expandido por la Península y Baleares. En Ibiza es posible encontrarla en bosques y zonas de matorral, aunque su carácter nocturno la hace difícil de observar.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('22230', 'fauna', 'Quebrantahuesos', 'El quebrantahuesos, el último gran especialista en carroña, es una de las aves más emblemáticas de los Pirineos. Su silueta inconfundible deslizándose sobre farallones solitarios es una imagen icónica de la naturaleza española. Con programas de reintroducción exitosos, es posible observarlo en los altos valles pirenaicos.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('90272', 'fauna', 'Quebrantahuesos', 'El quebrantahuesos, el último gran especialista en carroña, es una de las aves más emblemáticas de los Pirineos. Su silueta inconfundible deslizándose sobre farallones solitarios es una imagen icónica de la naturaleza española. Con programas de reintroducción exitosos, es posible observarlo en los altos valles pirenaicos.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('23001', 'fauna', 'Quebrantahuesos', 'El quebrantahuesos, el último gran especialista en carroña, es una de las aves más emblemáticas de los Pirineos. Su silueta inconfundible deslizándose sobre farallones solitarios es una imagen icónica de la naturaleza española. Con programas de reintroducción exitosos, es posible observarlo en los altos valles pirenaicos.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('07026', 'fauna', 'Halcón de Eleonora', 'El halcón de Eleonora es un ave marina elegante y ligera, presente en los islotes mediterráneos. Su vuelo perenne y su historia ligada a la conservación lo convierten en un símbolo de las Baleares. Es especialmente visible en los acantilados de Ibiza y Cabrera.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('15012', 'fauna', 'Búho real', 'El búho real, la mayor rapaz nocturna de Europa, es un depredador formidable. En Monfragüe y otras sierras extremeñas es posible avistarlo, especialmente al atardecer. Su presencia majestuosa y silenciosa es uno de los grandes atractivos de la ornitología ibérica.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('28079', 'fauna', 'Águila imperial', 'La águila imperial ibérica es una de las aves más emblemáticas y amenazadas de España. Gracias a programas de recuperación, se puede observar en la Sierra Oeste madrileña y otros enclaves. Su poderoso vuelo sobre pinares y encinares es un espectáculo de la naturaleza.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('09012', 'fauna', 'Buitre leonado', 'El buitre leonado es una de las aves más visibles en los roquedales ibéricos. Su vuelo pausado y sus grandes alas son características. En lugares como Pancorbo o los cañones del Duero es fácil observarlos planeando en busca de carroña.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('49242', 'fauna', 'Avutarda', 'La avutarda es una de las aves más pesadas voladoras del mundo. Las lagunas de Villafáfila en Zamora son uno de los mejores lugares para observarla. Su plumaje y comportamiento la convierten en un símbolo de la estepa ibérica.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('24202', 'fauna', 'Urogallo', 'El urogallo es una de las aves más icónicas y difíciles de avistar de la península. En los bosques de la cordillera Cantábrica (León y Asturias) encuentra refugio. Su presencia es un indicador de la salud de los bosques maduros.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('35024', 'fauna', 'Pardela cenicienta', 'La pardela cenicienta es una de las aves marinas más representativas de Canarias. Sus vuelos nocturnos y regreso a tierra en colonias protegidas la convierten en un espectáculo natural único en las islas.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('10904', 'fauna', 'Cigüeña negra', 'La cigüeña negra es una de las aves más tímidas y emblemáticas de España. Aunque su población ha aumentado ligeramente, sigue siendo rara. En Doñana y en rincones del Tiétar es posible avistarla, especialmente en humedales y zonas boscosas.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('15012', 'fauna', 'Buitre negro', 'El buitre negro es la mayor ave rapaz de Europa. Aunque amenazado, en Monfragüe y otras zonas tiene poblaciones estables. Su silueta imponente es uno de los grandes espectáculos de la avifauna ibérica.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('38004', 'fauna', 'Lagarto de El Hierro', 'El lagarto gigante de El Hierro es una especie endémica extremadamente amenazada. Con poblaciones muy reducidas, es uno de los reptiles más raros de Europa. Proyectos de conservación intentan su recuperación.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('08137', 'fauna', 'Tritón del Montseny', 'El tritón del Montseny es una especie endémica y una de las más amenazadas de Europa. Su distribución es extremadamente reducida en el Montseny. Es un símbolo de la biodiversidad amenazada en Cataluña.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('30008', 'fauna', 'Arrui', 'El arrui (muflón africano) fue introducido con fines cinegéticos. Aunque no está en peligro, su presencia genera debate por su impacto en la flora autóctona.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('30039', 'fauna', 'Arrui', 'El arrui (muflón africano) fue introducido con fines cinegéticos. Aunque no está en peligro, su presencia genera debate por su impacto en la flora autóctona.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('16009', 'fauna', 'Ibis eremita', 'El ibis eremita es una de las aves más raras y amenazadas del mundo. Tras casi desaparecer, proyectos de reintroducción en el sur de Andalucía han permitido que pequeñas colonias vuelvan a prosperar. Su característico plumaje oscuro y cresta la convierten en una especie icónica de la conservación.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('90654', 'fauna', 'Ferreret', 'El ferreret es un sapo balear endémico y extremadamente amenazado. Su supervivencia depende de la conservación de charcos temporales en Mallorca.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('38026', 'fauna', 'Violeta del Teide', 'La violeta del Teide es una delicada flor endémica que crece en los baluartes pedregosos del Teide por encima de los 2500 m. Sus pétalos coloridos destacan en el paisaje volcánico y la convierten en una de las flores más altas de España.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('90548', 'fauna', 'Carballo de Cartelos', 'El carballo de Cartelos es uno de los robles más espectaculares de Galicia. Con casi 40 m de altura y una longevidad impresionante, este árbol ha resistido siglos y representa la fuerza de la naturaleza gallega. Sus bellotas se utilizan en programas de reforestación.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('03010', 'fauna', 'Silene de Ifach', 'La silene de Ifach es una planta endémica del Peñón de Ifach y otras zonas. Muy resistente a las condiciones extremas de los acantilados, es un símbolo de la conservación en la Comunidad Valenciana y Baleares.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('07026', 'fauna', 'Silene de Ifach', 'La silene de Ifach es una planta endémica del Peñón de Ifach y otras zonas. Muy resistente a las condiciones extremas de los acantilados, es un símbolo de la conservación en la Comunidad Valenciana y Baleares.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('18903', 'fauna', 'Estrella de las nieves', 'La estrella de las nieves es una flor endémica de Sierra Nevada que crece a gran altitud. Sus pétalos blancos y su adaptación a las condiciones extremas la convierten en una joya botánica de las altas montañas andaluzas.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('33053', 'fauna', 'Tejo de Bermiego', 'El tejo de Bermiego es un ejemplar legendario de más de 1000 años. Declarado monumento natural, este tejo milenario es uno de los árboles más impresionantes de Asturias y un símbolo de longevidad.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('22901', 'fauna', 'Abuelo de Maz', 'El Abuelo de Maz es un imponente abeto en la Selva de Oza. Rodeado de un paisaje glaciar espectacular, este árbol centenario representa la grandeza de los bosques pirenaicos aragoneses.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('28030', 'fauna', 'Peonia silvestre', 'La peonia silvestre, conocida como "rosa de los montes", es endémica de la Península Ibérica. Sus flores púrpura y amarillas son un espectáculo en primavera en las sierras madrileñas.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('30008', 'fauna', 'Varica de san José', 'La varica de san José es una planta endémica de la Región de Murcia con pétalos blancos y amarillos. Su presencia en litorales y sierras la convierte en una especie característica del sureste español.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('43049', 'activo', 'La Rambla', 'La Rambla es una de las rutas deportivas más icónicas y duras del mundo (9a+). En Siurana, este desplome legendario ha marcado la historia de la escalada deportiva. Su dificultad extrema y belleza la convierten en un referente mundial.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('90918', 'activo', 'Perfecto Mundo', 'Perfecto Mundo es una vía futurista de 9b+ en Margalef. Encadenada por Alexander Megos, esta línea representa la evolución de la escalada deportiva en uno de los mejores sectores de Cataluña.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('25149', 'activo', 'La Dura Dura', 'La Dura Dura (9b+) es una de las vías más duras del mundo. Abierta por Dani Andrada y Adam Ondra en Oliana, su complejidad física y mental la convierten en una obra maestra de la escalada.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('22058', 'activo', 'Ali Hulk', 'Ali Hulk es una de las rutas más icónicas de Rodellar. Con múltiples variantes de alto grado, este sector es un paraíso para la escalada deportiva gracias a la calidad de su roca caliza.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('29096', 'activo', 'Chilam Balam', 'Chilam Balam es una de las vías más controvertidas y emblemáticas de España (9b+). En el paraíso de la escalada andaluza, esta línea representa la excelencia técnica y la historia de la escalada deportiva.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('25037', 'activo', 'Fuck the System', 'Fuck the System es una de las primeras propuestas de noveno grado en España. En Santa Linya, esta vía representa los inicios de la escalada de alto nivel en Cataluña.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('45043', 'activo', 'Entropía', 'Entropía es una vía dura en el granito de Toledo. Su dificultad y calidad la convierten en un referente de la escalada en bloque y deportiva en Castilla-La Mancha.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('07020', 'activo', 'Es Pontàs', 'Es Pontàs es la mítica línea de psicobloc de Chris Sharma sobre el mar en Mallorca. Una de las vías más bellas y emblemáticas del mundo en escalada sin cuerda sobre el Mediterráneo.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('08014', 'activo', 'Tarragó Plus', 'Tarragó Plus es una vía clásica de 240 m (8c) en las paredes de Montserrat. Abierta y liberada por Edu Marín, esta ruta representa la excelencia de la escalada tradicional en uno de los escenarios más emblemáticos de Cataluña.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('22230', 'activo', 'Zaratustra', 'Zaratustra es una gran vía de varios largos en las paredes de Ordesa. Con cotación de octavo grado y 400 m de recorrido, es una de las rutas míticas del big wall aragonés.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('05004', 'activo', 'Lurgorri', 'Lurgorri es una impresionante vía de 250 m en el Naranjo de Bulnes. Abierta por los hermanos Pou, esta ruta de alto nivel es una de las más exigentes del Picu.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('05004', 'activo', 'Orbayu', 'Orbayu es otra gran vía en el Naranjo de Bulnes. Con dificultad extrema y gran exposición, forma parte del legado de los Pou en una de las paredes más míticas de España.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('22173', 'activo', 'La fiesta del bíceps', 'La fiesta del bíceps es una vía mítica de séptimo grado en los Mallos de Riglos. Su exposición y belleza la convierten en un clásico del big wall aragonés.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('08014', 'activo', 'Arco Iris', 'Arco Iris es una vía de varios largos (8c+) en la Paret de Diables de Montserrat. Abierta por Edu Marín, es una de las grandes rutas multi-pitch de Cataluña.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('22230', 'activo', 'El Imperio Contraataca', 'El Imperio Contraataca es una vía mítica en Ordesa. Con gran dificultad y longitud, forma parte del legado del big wall en el Parque Nacional.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('22028', 'activo', 'Super Weissmuller', 'Super Weissmuller es una vía alpina de alto nivel en el Petit Pic d’Ansabere. Abierta por Unai Mendi y Mikel Zabalza, combina exposición y belleza en el Pirineo aragonés.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('39015', 'activo', 'Horcados Rojos', 'Desde el teleférico de Fuente Dé se accede a los Horcados Rojos, una ascensión alpina clásica con más de 800 m de desnivel. Sus paredes rojas y la exposición ofrecen una experiencia de alta montaña inolvidable en los Picos de Europa.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('29090', 'activo', 'Torrecilla', 'La Torrecilla (1919 m) es la cumbre más alta de la Sierra de las Nieves. Su ascensión ofrece vistas impresionantes desde la Costa del Sol hasta las montañas nevadas, combinando dificultad y belleza.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('39015', 'activo', 'Peña Vieja', 'Peña Vieja (2619 m) es una de las cumbres más emblemáticas de los Picos de Europa. Su ascensión clásica combina terreno alpino, exposición y vistas panorámicas.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('22107', 'activo', 'Monte Perdido', 'Monte Perdido es una de las ascensiones más clásicas y hermosas de los Pirineos. Su cara norte y la travesía final ofrecen una experiencia alpina completa en uno de los tresmiles más emblemáticos.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('22230', 'activo', 'Monte Perdido', 'Monte Perdido es una de las ascensiones más clásicas y hermosas de los Pirineos. Su cara norte y la travesía final ofrecen una experiencia alpina completa en uno de los tresmiles más emblemáticos.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('34185', 'activo', 'Curavacas', 'Curavacas (2525 m) es una imponente montaña en la Montaña Palentina. Su ascensión por la vertiente sur es un reto técnico y estético en uno de los macizos más salvajes del norte.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('39015', 'activo', 'Pico Tesorero', 'El Pico Tesorero es una cumbre emblemática en Picos de Europa. Su ascensión combina dificultad técnica y exposición en uno de los entornos alpinos más impresionantes de España.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('22054', 'activo', 'Mulleres (Tuc de Molières)', 'Mulleres (Tuc de Molières) es uno de los gigantes del Pirineo. Su cara norte es una de las más exigentes y expuestas, ideal para montañeros experimentados.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('27014', 'activo', 'Mulleres (Tuc de Molières)', 'Mulleres (Tuc de Molières) es uno de los gigantes del Pirineo. Su cara norte es una de las más exigentes y expuestas, ideal para montañeros experimentados.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('22230', 'activo', 'Taillón', 'El Taillón es una cumbre pirenaica clásica con cara norte muy exigente. Sus rutas ofrecen gran exposición y belleza en el entorno de Ordesa.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('40139', 'activo', 'Nevero', 'El Nevero es el pico más prominente de los montes Carpetanos. Con casi 1 km de desnivel positivo, esta ascensión es un clásico del trail running en la sierra madrileña. Sus vistas panorámicas y el terreno variado lo convierten en un reto exigente pero accesible.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('90654', 'activo', 'Sa Costera', 'Sa Costera es uno de los recorridos más salvajes y panorámicos de la Serra de Tramuntana. Partiendo de la Cala Tuent, este trail combina historia, acantilados y paisajes mediterráneos en una media maratón exigente.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('07023', 'activo', 'Sa Costera', 'Sa Costera es uno de los recorridos más salvajes y panorámicos de la Serra de Tramuntana. Partiendo de la Cala Tuent, este trail combina historia, acantilados y paisajes mediterráneos en una media maratón exigente.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('39015', 'activo', 'Fuente Dé', 'Desde Fuente Dé, el kilómetro vertical y las ascensiones a las murallas de los Picos de Europa ofrecen un terreno legendario para trail running. La combinación de verticalidad y vistas es única.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('34199', 'activo', 'Espigüete', 'El Espigüete es una ascensión espectacular en la Montaña Palentina. Su cima ofrece vistas impresionantes y un terreno técnico que pone a prueba a los corredores más preparados.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('04088', 'activo', 'Desierto de Tabernas', 'El Desierto de Tabernas ofrece un trail único por paisajes de western. Sus ramblas y formaciones geológicas crean un entorno cinematográfico ideal para corredores que buscan aventura en terreno árido.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('28068', 'activo', 'La Maliciosa', 'La Maliciosa es un clásico del kilómetro vertical en la Sierra de Guadarrama. Su ascensión exigente y vistas panorámicas la convierten en una de las cimas más apreciadas por los trail runners madrileños.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('90943', 'activo', 'Aizkorri', 'Aizkorri es el escenario de la mítica maratón de Zegama. Sus crestas, prados y ambiente alpino lo convierten en uno de los trails más espectaculares del País Vasco.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('90641', 'activo', 'Redes', 'El Sobrescobio Redes Trail recorre uno de los parques más bellos de Asturias. Sus 30 km combinan bosque, montañas y gargantas en un itinerario exigente pero muy gratificante.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('33067', 'activo', 'Redes', 'El Sobrescobio Redes Trail recorre uno de los parques más bellos de Asturias. Sus 30 km combinan bosque, montañas y gargantas en un itinerario exigente pero muy gratificante.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('27015', 'activo', 'Feliz Navidad', 'Feliz Navidad es una de las vías ferratas más duras de España (K6). En Àger, esta ferrata extrema combina exposición, verticalidad y pasos muy técnicos. Solo para ferratistas experimentados.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('24116', 'activo', 'Valdeón', 'La vía ferrata de Valdeón es una de las más largas y alpinas de España. Con más de 1 km de recorrido y gran exposición, ofrece vistas impresionantes del desfiladero del río Cares.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('16078', 'activo', 'El Castillo', 'El Castillo es una ferrata urbana en la Hoces del Júcar. Sus tramos aéreos y vistas sobre la ciudad de Cuenca la convierten en una experiencia única.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('33050', 'activo', 'Puente Vidosa', 'Puente Vidosa es una ferrata espectacular en el desfiladero de los Beyos. Con puentes tibetanos y tramos aéreos, combina adrenalina y belleza en uno de los cañones más impresionantes de Asturias.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('32025', 'activo', 'El Chorro', 'La ferrata de El Chorro es una de las más aéreas y largas de Andalucía. Sus tirolinas y tramos verticales junto al Caminito del Rey ofrecen una experiencia inolvidable.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('01902', 'activo', 'Sobrón', 'Sobrón es una ferrata horizontal de 550 m sobre el río Ebro. Una de las primeras y más populares del País Vasco, con gran exposición y belleza.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('22069', 'poza', 'Cascada del Sorrosal', 'La ferrata de la Cascada del Sorrosal es una vía alpina espectacular en Broto. Con 600 m de recorrido, puentes y tramos junto a la cascada, es una de las ferratas más bonitas de los Pirineos.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('30029', 'activo', 'El Ciervo', 'El Ciervo es una ferrata técnica y expuesta en la Región de Murcia. Sus canales y verticales la convierten en un reto exigente en un entorno de gran belleza.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('50185', 'activo', 'Río Gállego', 'El Gállego es uno de los ríos más atractivos del Pirineo para el kayak extremo. Sus rápidos técnicos, desfiladeros y caudal variable lo convierten en un clásico imprescindible para los amantes de las aguas bravas.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('25123', 'activo', 'Palomeres', 'El Palomeres nace en la estación de esquí de Tavascan y ofrece secciones de aguas bravas intensas con rampas y saltos técnicos. Un río exigente y de gran calidad en el Pirineo catalán.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('27008', 'activo', 'Vallferrerra', 'La Vallferrerra es un río de aguas bravas muy técnico y continuo. Sus rápidos y ambiente alpino lo convierten en uno de los descensos más duros y bonitos de Cataluña.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('05004', 'activo', 'Río Cares', 'El Cares, famoso por su ruta de senderismo, también ofrece tramos de aguas bravas espectaculares en sus gargantas. Un descenso técnico y hermoso en el corazón de los Picos.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('27008', 'activo', 'Noguera Pallaresa', 'La Noguera Pallaresa es la cuna del kayak en España. Uno de los mejores ríos de Europa con caudal constante, rápidos de todos los niveles y un entorno privilegiado.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('22182', 'activo', 'Cinqueta', 'El Cinqueta es un clásico del Pirineo aragonés. Sus rápidos y el entorno del valle de Chistau ofrecen descensos variados y de gran calidad.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('22114', 'activo', 'Cinqueta', 'El Cinqueta es un clásico del Pirineo aragonés. Sus rápidos y el entorno del valle de Chistau ofrecen descensos variados y de gran calidad.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('31210', 'activo', 'Río Esca', 'El Esca ofrece uno de los descensos más bellos e inquietantes del Pirineo. Sus desfiladeros y caudal lo convierten en un reto técnico y paisajístico.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('50245', 'activo', 'Río Esca', 'El Esca ofrece uno de los descensos más bellos e inquietantes del Pirineo. Sus desfiladeros y caudal lo convierten en un reto técnico y paisajístico.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('27014', 'activo', 'Varradòs', 'El Varradòs es un afluente del Garona con gran caudal y rápidos exigentes. Un tramo alpino de gran belleza en el Pirineo catalán.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('22069', 'activo', 'Río Ara', 'El Ara es un río salvaje del Pirineo aragonés con tramos extremos (grado IV+). Sus cañones y cascadas lo convierten en uno de los más técnicos y espectaculares.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('22230', 'activo', 'Río Ara', 'El Ara es un río salvaje del Pirineo aragonés con tramos extremos (grado IV+). Sus cañones y cascadas lo convierten en uno de los más técnicos y espectaculares.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('36024', 'activo', 'Río Deza', 'El Deza es un río de aguas bravas en Galicia con 50 km de recorrido y secciones técnicas. Un destino interesante para kayakistas que buscan variedad en el noroeste.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('36052', 'activo', 'Río Deza', 'El Deza es un río de aguas bravas en Galicia con 50 km de recorrido y secciones técnicas. Un destino interesante para kayakistas que buscan variedad en el noroeste.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('38020', 'activo', 'Barranco de Badajoz', 'El Barranco de Badajoz es un descenso técnico y aéreo con 700 m de desnivel, 12 rapeles y gran exposición. Un barranco mítico de Tenerife con ambiente de vértigo y dificultad alta.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('18148', 'activo', 'Río Verde', 'El Río Verde es uno de los descensos más celebrados de Andalucía. Con caudal constante, toboganes, saltos y un bosque de boj único, ofrece un barranquismo espectacular.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('90654', 'activo', 'Gorg Blau', 'Gorg Blau es uno de los mejores barrancos de Europa. Técnico, con saltos, cuevas y posibilidad de llegar nadando al mar. Un clásico imprescindible en Mallorca.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('90272', 'activo', 'Cañón del Vero', 'El Cañón del Vero es la cuna del barranquismo en España. Largo, con gran caudal y ambiente espectacular, es uno de los más populares y bonitos del Pirineo.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('03137', 'activo', 'Barranc de l''Infern', 'El Barranc de l’Infern es uno de los más duros de la Comunidad Valenciana. Técnico, con rapeles y ambiente impresionante, es un reto para barranquistas experimentados.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('22058', 'activo', 'Gorgas Negras', 'Gorgas Negras es uno de los cañones más duros de Guara. Largo, aislado y técnico, requiere gran experiencia y forma física.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('22058', 'activo', 'Barranco de Mascún', 'El Barranco de Mascún es uno de los más famosos de España. Toboganes, sifones, cascadas y formaciones geológicas únicas lo convierten en un icono del barranquismo en Guara.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('22054', 'activo', 'Aigüeta de Barbaruens', 'La Aigüeta de Barbaruens es un barranco deportivo y lúdico con toboganes y saltos. Ideal para iniciados con buena forma física en un entorno espectacular.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('90950', 'playa', 'Meñakoz', 'Meñakoz es un templo del surf de olas grandes en el País Vasco. Con olas de hasta 7 m y gran potencia, es un spot selecto y exigente que atrae a los mejores surfers del mundo.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('21018', 'playa', 'Zarautz', 'Zarautz es la capital del surf en Euskadi. Sus olas versátiles, fondo de arena y ambiente vibrante la convierten en un spot ideal para todos los niveles y en sede de campeonatos internacionales.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('33076', 'playa', 'Rodiles', 'Rodiles ofrece una ola de izquierdas potente y rápida con tubos perfectos. Un spot versátil y de gran calidad en el Cantábrico asturiano.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('47011', 'playa', 'Mundaka', 'Mundaka es una de las olas más famosas del mundo. Su izquierda larga y perfecta es un icono del surf internacional.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('35016', 'playa', 'El Confital', 'El Confital es uno de los mejores rompientes de arrecife de Canarias y Europa. Sus tubos potentes y entorno volcánico lo convierten en un spot de clase mundial.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('01006', 'playa', 'Playa de Razo', 'Playa de Razo es un spot mítico de Galicia con olas consistentes y ambiente salvaje. Ideal para surfistas de todos los niveles en la Costa da Morte.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('39047', 'playa', 'El Brusco', 'El Brusco es un spot exigente en Cantabria. Sus olas potentes y el entorno natural lo convierten en uno de los favoritos de los surfers locales y visitantes.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('11039', 'playa', 'El Palmar', 'El Palmar es uno de los destinos surf más populares de Andalucía. Con 5 km de playa y olas consistentes, es un paraíso para surfers de todos los niveles.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('15087', 'playa', 'Playa de Pantín', 'Pantín es un spot legendario de Galicia con olas deportivas y consistentes. Sede de pruebas internacionales, es un clásico del surf atlántico.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('15022', 'playa', 'Playa de Pantín', 'Pantín es un spot legendario de Galicia con olas deportivas y consistentes. Sede de pruebas internacionales, es un clásico del surf atlántico.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('15036', 'playa', 'Playa de Pantín', 'Pantín es un spot legendario de Galicia con olas deportivas y consistentes. Sede de pruebas internacionales, es un clásico del surf atlántico.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('34199', 'activo', 'Pico Murcia', 'Pico Murcia es una cumbre accesible pero exigente en Fuentes Carrionas. Su travesía por la vertiente sur ofrece un descenso técnico y emocionante, ideal para freeride y skimo.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('34199', 'activo', 'Pico Tres Provincias', 'Pico Tres Provincias (2499 m) es un mirador excepcional de Cantabria, León y Palencia. Su ascensión y descenso por pala de nieve son clásicos del skimo y freeride en los Picos de Europa.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('18903', 'activo', 'Picón de Jerez', 'El Picón de Jerez es uno de los tresmiles orientales de Sierra Nevada. Su ascensión y descenso ofrecen un soberbio mirador y un terreno ideal para skimo y freeride.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('05047', 'activo', 'Zócalo del Almanzor', 'El Zócalo del Almanzor es una línea clásica de freeride en Gredos. Con gran desnivel y exposición, es un descenso exigente y espectacular.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('05267', 'activo', 'Zócalo del Almanzor', 'El Zócalo del Almanzor es una línea clásica de freeride en Gredos. Con gran desnivel y exposición, es un descenso exigente y espectacular.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('39015', 'activo', 'Torre Blanca', 'Torre Blanca es una gran clásica de skimo en los Picos de Europa. Accesible desde Fuente Dé, su pala final y vistas panorámicas la convierten en una experiencia inolvidable.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('05089', 'activo', 'La Mira', 'La Mira es un clásico del freeride en Gredos. Su cara norte con canales y pendientes pronunciadas es una de las más espectaculares de la sierra.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('39075', 'ciclismo', 'Cantabria oriental', 'Desde las marismas de Santoña, esta ruta recorre la Cantabria oriental en un itinerario de unos 65 km lleno de contrastes. Playas salvajes, pueblos marineros con encanto y caminos que serpentean entre colinas ofrecen un mountain bike explosivo y variado.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('39079', 'ciclismo', 'Cantabria oriental', 'Desde las marismas de Santoña, esta ruta recorre la Cantabria oriental en un itinerario de unos 65 km lleno de contrastes. Playas salvajes, pueblos marineros con encanto y caminos que serpentean entre colinas ofrecen un mountain bike explosivo y variado.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('05005', 'activo', 'El Angliru y los lagos de Covadonga', 'La mítica ascensión al Angliru combinada con la subida a los Lagos de Covadonga es un desafío legendario para cualquier mountain biker. Más de 2000 m de desnivel acumulado en 112 km de puro sufrimiento y belleza. Puertos míticos, paisajes de ensueño en los Picos de Europa y un terreno que pone a prueba piernas y mente.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('33053', 'activo', 'El Angliru y los lagos de Covadonga', 'La mítica ascensión al Angliru combinada con la subida a los Lagos de Covadonga es un desafío legendario para cualquier mountain biker. Más de 2000 m de desnivel acumulado en 112 km de puro sufrimiento y belleza. Puertos míticos, paisajes de ensueño en los Picos de Europa y un terreno que pone a prueba piernas y mente.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('16001', 'ciclismo', 'Los Alcornocales', 'Los Alcornocales ofrece un paraíso de mountain bike entre los mayores bosques de alcornoques del mundo. Senderos técnicos, subidas exigentes y bajadas divertidas en un entorno mediterráneo único. Una zona que combina naturaleza salvaje con un enorme potencial para rutas de varios días.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('11021', 'ciclismo', 'Los Alcornocales', 'Los Alcornocales ofrece un paraíso de mountain bike entre los mayores bosques de alcornoques del mundo. Senderos técnicos, subidas exigentes y bajadas divertidas en un entorno mediterráneo único. Una zona que combina naturaleza salvaje con un enorme potencial para rutas de varios días.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('28131', 'ciclismo', 'Silla de Felipe II', 'La Silla de Felipe II es un mirador histórico con una ruta de mountain bike exigente y panorámica. Subidas técnicas y vistas impresionantes del Monasterio de El Escorial y la sierra madrileña hacen de esta zona un clásico para bikers de la región.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('90566', 'ciclismo', 'Picos de Begues', 'Los Picos de Begues ofrecen ascensos duros y vistas espectaculares del Parque Natural del Garraf. Un terreno variado y técnico perfecto para sesiones intensas de mountain bike cerca de Barcelona.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('40195', 'ciclismo', 'Hoces del río Duratón', 'Las Hoces del Duratón son un paraíso para el mountain bike con cañones espectaculares, senderos técnicos y paisajes de gran belleza. Una ruta que combina naturaleza salvaje con un reto físico y técnico.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('40193', 'ciclismo', 'Hoces del río Duratón', 'Las Hoces del Duratón son un paraíso para el mountain bike con cañones espectaculares, senderos técnicos y paisajes de gran belleza. Una ruta que combina naturaleza salvaje con un reto físico y técnico.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('40044', 'ciclismo', 'Hoces del río Duratón', 'Las Hoces del Duratón son un paraíso para el mountain bike con cañones espectaculares, senderos técnicos y paisajes de gran belleza. Una ruta que combina naturaleza salvaje con un reto físico y técnico.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('12079', 'activo', 'Montanejos', 'Montanejos es uno de los lugares fundacionales de la escalada deportiva en España. Durante los años 80 se convirtió en un verdadero festival de aperturas que marcó el nacimiento de la escena nacional. Sus paredes de caliza compacta, con rutas de todos los estilos y grados, ofrecen un terreno perfecto tanto para quienes dan sus primeros pasos en la vertical como para escaladores experimentados que buscan progresar.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('90918', 'activo', 'Margalef', 'Margalef es, sin duda, uno de los mayores paraísos de escalada deportiva del mundo. Con más de 80 sectores y centenares de vías de todos los estilos y dificultades, este rincón del Priorat ofrece una variedad casi infinita. Sus característicos agujeros y regletas en caliza compacta permiten disfrutar tanto de vías cortas y explosivas como de líneas largas y sostenidas.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('22058', 'activo', 'Rodellar', 'Rodellar es un santuario de la escalada en caliza dentro del Pirineo aragonés. Sus impresionantes techos, desplomes y paredes verticales albergan vías de todos los niveles, desde iniciación hasta noveno grado. La calidad de la roca, el ambiente alpino y la belleza del cañón del Mascún hacen que cada sesión sea una experiencia memorable.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('46112', 'activo', 'Chulilla', 'Chulilla ofrece uno de los cañones más espectaculares de la Comunidad Valenciana. Sus largas rutas sobre caliza compacta, con pasos técnicos y aéreos, son ideales para escaladores que buscan progresar en vías de varios largos. El entorno de montaña mediterránea, con el río Turia y paisajes de gran belleza, hace de este lugar un destino completo para combinar escalada, naturaleza y tranquilidad.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('90725', 'activo', 'Etxauri', 'Etxauri es una de las escuelas más completas y queridas del norte de España. Sus paredes de caliza técnica ofrecen vías de todos los estilos y dificultades, desde placas hasta desplomes. El ambiente acogedor y la cercanía a Pamplona la convierten en un destino perfecto tanto para fines de semana como para estancias más largas.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('43049', 'activo', 'Siurana', 'Siurana es una auténtica catedral de la escalada deportiva. Sus impresionantes paredes calizas, con rutas legendarias y un entorno de ensueño en la sierra de Prades, han marcado la historia de la escalada en España. Desde vías clásicas hasta líneas modernas de alto nivel, Siurana ofrece todo lo necesario para disfrutar de la vertical en un paisaje de gran belleza natural.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('28082', 'activo', 'La Pedriza', 'La Pedriza es el gran templo del granito en la Sierra de Guadarrama. Sus bloques, agujas y paredes ofrecen un sinfín de posibilidades para la escalada deportiva y tradicional. El entorno salvaje, con formaciones rocosas espectaculares y vistas panorámicas, hace de este lugar un clásico imprescindible para los escaladores madrileños y visitantes.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('33053', 'activo', 'Quirós', 'Quirós es un paraíso de escalada en el corazón de Asturias. Sus paredes de caliza y cuarcita ofrecen rutas de gran calidad en un entorno alpino único. Ideal para disfrutar de la escalada deportiva rodeado de montañas, bosques y un ambiente auténticamente norteño.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('16078', 'activo', 'Cuenca', 'Las hoces del río Júcar y Huécar en Cuenca ofrecen un entorno espectacular para la escalada deportiva. Sus paredes calizas con vías técnicas y el paisaje de cañones profundos crean una atmósfera única que combina deporte y naturaleza de forma excepcional.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('05089', 'activo', 'Torreón de Galayos', 'El Torreón de Galayos es una referencia indiscutible de la escalada clásica en España. Sus líneas de roca granítica van desde rutas asequibles hasta vías extremadamente exigentes, con un ambiente salvaje y exposición característica de Gredos.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('28030', 'activo', 'Pico de la Miel', 'El Pico de la Miel, con sus 1384 m, es una de las cumbres más populares de la sierra madrileña para la escalada clásica. La vía Espolón Manolín ofrece 200 m de escalada variada y asequible con fisuras, placas y repisas, perfecta para iniciarse en la escalada tradicional en un entorno de gran belleza.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('22173', 'activo', 'Aguja Roja', 'La Aguja Roja es una de las formaciones más características de los Mallos de Riglos. Sus cuatro largos con dificultades de quinto grado ofrecen un itinerario perfecto para iniciarse en la escalada clásica en conglomerado. La vía normal combina exposición, calidad de roca y un ambiente único que hace de esta ascensión una experiencia inolvidable.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('24116', 'activo', 'Peña Santa de Castilla', 'Peña Santa de Castilla es una de las grandes clásicas de los Picos de Europa. La vía abierta por José González Folliot, Florencio Fuentes y Antonio Rojas en 1947 es una ruta histórica con gran exposición y belleza. Sus 300 m de escalada en caliza ofrecen un reto técnico y emocional en uno de los macizos más impresionantes de España.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('90938', 'activo', 'Espolón de Ziordia', 'El Espolón de Ziordia es una ruta clásica de 245 m en la sierra de Altzania. Su línea estética y sostenida combina pasos técnicos con un ambiente alpino único. Una de las vías más bonitas y recomendables del País Vasco para quienes buscan escalada clásica en un entorno espectacular.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('26010', 'activo', 'Peñas del Prado', 'Las Peñas del Prado ofrecen un tranquilo pero exigente terreno de escalada clásica en los montes leoneses. Sus paredes y agujas de roca proporcionan rutas variadas en un entorno de gran belleza natural, perfecto para una jornada de escalada alejada de las masificaciones.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('05004', 'activo', 'Naranjo de Bulnes', 'El Naranjo de Bulnes (Picu Urriellu) es el símbolo de la escalada clásica en España. Su cara sur, con vías como la Directa de los Martínez, ofrece rutas asequibles pero aéreas en un entorno legendario. Un lugar mítico que todo escalador clásico sueña con visitar.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('28082', 'activo', 'Risco de Peñalarco', 'El Risco de Peñalarco, con sus 100 m de granito, es una de las formaciones más famosas de La Pedriza. Sus vías clásicas combinan fisuras, placas y diedros en un entorno de bloques y agujas característico del granito madrileño.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('44125', 'activo', 'Castillo de Peñaflor', 'Junto al pintoresco pueblo de Huesa del Común se alza el imponente Castillo de Peñaflor, un antiguo baluarte musulmán encaramado en una loma rocosa. La vía ferrata que lo corona es corta pero muy emocionante: pasos aéreos, grapas bien colocadas y un entorno rural salvaje que transporta al escalador a otra época.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('29056', 'activo', 'Castillo del Águila', 'El Castillo del Águila ofrece una de las vías ferratas más imaginativas y divertidas de Andalucía. Con puentes, tirolinas y un circuito circular que conecta agujas y vacíos, es una experiencia lúdica y emocionante. Recomendable ir con guía, especialmente para disfrutar al máximo de este recorrido aéreo en un entorno de gran belleza.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('03111', 'activo', 'Redován', 'Redován alberga la vía ferrata más larga de la Comunidad Valenciana. Sus dos sectores ofrecen más de 300 m de recorrido variado, con pasos aéreos y técnicos. Es una ferrata completa y exigente que pone a prueba la resistencia y la técnica en un entorno montañoso mediterráneo.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('16170', 'activo', 'Hoz de Priego', 'En las impresionantes hoces del río Escabas, la vía ferrata de Priego es una de las más espectaculares de Castilla-La Mancha. Con pasos aéreos y un trazado vertical en un cañón de gran belleza, es ideal tanto para principiantes como para ferrateros experimentados.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('46246', 'activo', 'Ferrata del Chorrico', 'La Ferrata del Chorrico, en el barranco de Castellet, es una vía muy popular y entretenida. Sus paredes sobre el pantano de Tous ofrecen pasos técnicos y aéreos con un entorno espectacular. Perfecta para iniciarse y disfrutar de la escalada vertical en la Comunidad Valenciana.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('22059', 'activo', 'Santa Elena de Biescas', 'La ferrata de Santa Elena de Biescas combina historia, misticismo y verticalidad. Rodeada de un entorno de gran belleza en el Pirineo aragonés, ofrece un recorrido entretenido con pasos aéreos y vistas excepcionales.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('39055', 'activo', 'Camaleño', 'La ferrata de Camaleño es corta pero explosiva. Con gran exposición y vistas impresionantes de los Picos de Europa, es una de las ferratas más recomendadas de Cantabria para quienes buscan adrenalina en un entorno de alta montaña.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('25148', 'activo', 'Puig Arnau Canalda', 'Esta vía ferrata, muy utilizada como atajo por senderistas y barranquistas, ofrece un recorrido vertical y aéreo en el impresionante barranco de l’Urde ll. Es una ferrata sencilla pero muy estética, ideal para disfrutar de la vertical en el corazón del Solsonès.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('05005', 'activo', 'Río Sella', 'El Río Sella es, sin duda, el río más internacional y emblemático para el kayak en España. Conocido por su famoso Descenso Internacional del Sella, ofrece un tramo inicial de unos 15 km muy tranquilo y asequible, ideal para principiantes.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('40195', 'activo', 'Río Duratón', 'Las impresionantes hoces del río Duratón ofrecen un escenario espectacular para iniciarse en el kayak. Sus aguas mansas y delicadas, rodeadas de imponentes paredes verticales, permiten disfrutar de un recorrido tranquilo lleno de ecos y belleza natural.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('40193', 'activo', 'Río Duratón', 'Las impresionantes hoces del río Duratón ofrecen un escenario espectacular para iniciarse en el kayak. Sus aguas mansas y delicadas, rodeadas de imponentes paredes verticales, permiten disfrutar de un recorrido tranquilo lleno de ecos y belleza natural.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('15065', 'activo', 'Río Ulla', 'El Río Ulla, con sus más de 130 km de recorrido, es una de las grandes arterias gallegas. En sus tramos finales cerca de Padrón se vuelve especialmente tranquilo y accesible, perfecto para familias y principiantes. Un entorno rural mágico, con paisajes suaves y un ambiente relajado que invita a disfrutar del kayak de forma sosegada.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('21060', 'activo', 'Ría del Piedras', 'La Ría del Piedras ofrece una travesía tranquila y hermosa en la provincia de Huelva. Sus aguas mansas, marismas, playas y pinares crean un entorno ideal para principiantes. Remar por esta ría permite conectar con la naturaleza atlántica y disfrutar de atardeceres inolvidables en la Costa de la Luz.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('21021', 'activo', 'Ría del Piedras', 'La Ría del Piedras ofrece una travesía tranquila y hermosa en la provincia de Huelva. Sus aguas mansas, marismas, playas y pinares crean un entorno ideal para principiantes. Remar por esta ría permite conectar con la naturaleza atlántica y disfrutar de atardeceres inolvidables en la Costa de la Luz.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('27015', 'activo', 'Congost de Mont-rebei', 'El Congost de Mont-rebei es un cañón espectacular en la frontera entre Aragón y Cataluña. Sus aguas tranquilas entre paredes verticales ofrecen un recorrido de gran belleza, ideal para iniciarse en el kayak en un entorno salvaje y monumental.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('25196', 'activo', 'Congost de Mont-rebei', 'El Congost de Mont-rebei es un cañón espectacular en la frontera entre Aragón y Cataluña. Sus aguas tranquilas entre paredes verticales ofrecen un recorrido de gran belleza, ideal para iniciarse en el kayak en un entorno salvaje y monumental.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('22247', 'activo', 'Congost de Mont-rebei', 'El Congost de Mont-rebei es un cañón espectacular en la frontera entre Aragón y Cataluña. Sus aguas tranquilas entre paredes verticales ofrecen un recorrido de gran belleza, ideal para iniciarse en el kayak en un entorno salvaje y monumental.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('30036', 'activo', 'Costa murciana', 'La costa murciana ofrece tramos salvajes y poco urbanizados perfectos para el kayak de mar. Desde Salinas de San Pedro hasta Calblanque, se pueden recorrer calas, dunas y reservas naturales en un entorno mediterráneo de gran belleza, ideal para principiantes que quieren combinar mar y naturaleza.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('30016', 'activo', 'Costa murciana', 'La costa murciana ofrece tramos salvajes y poco urbanizados perfectos para el kayak de mar. Desde Salinas de San Pedro hasta Calblanque, se pueden recorrer calas, dunas y reservas naturales en un entorno mediterráneo de gran belleza, ideal para principiantes que quieren combinar mar y naturaleza.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('38013', 'activo', 'Los Gigantes', 'Los acantilados de Los Gigantes en Tenerife ofrecen una experiencia de kayak de mar inolvidable. Remando junto a estos imponentes farallones basálticos es posible avistar delfines y disfrutar de un entorno volcánico espectacular. Una actividad emocionante y accesible para principiantes.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('18001', 'cueva', 'Cova d''en Gispert', 'La Cova d’en Gispert es una de las cuevas marinas más grandes de la Costa Brava. Acceder en kayak a esta cavidad de más de 150 m con bóvedas de gran altura es una experiencia única y mágica, perfecta para quienes buscan algo diferente en sus primeras salidas.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('05241', 'activo', 'El Burguillo', 'El Embalse del Burguillo, rodeado por la Reserva Natural del Valle de Iruelas, ofrece un entorno tranquilo y boscoso ideal para iniciarse en el kayak. Sus aguas calmas y paisajes protegidos permiten disfrutar de una jornada relajada en plena naturaleza.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('90082', 'activo', 'El Burguillo', 'El Embalse del Burguillo, rodeado por la Reserva Natural del Valle de Iruelas, ofrece un entorno tranquilo y boscoso ideal para iniciarse en el kayak. Sus aguas calmas y paisajes protegidos permiten disfrutar de una jornada relajada en plena naturaleza.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('26061', 'sendero', 'Pico San Lorenzo', 'El Pico San Lorenzo (2271 m), techo de La Rioja, es un clásico para corredores de montaña. Desde la estación de Valdezcaray se puede realizar una ruta de unos 20 km con más de 1000 m de desnivel que combina senderos, praderas y vistas espectaculares de la sierra riojana.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('24115', 'sendero', 'Pico Teleno', 'El Pico Teleno (2185 m) es una montaña sagrada con historia templaria. La ruta desde Pontón del Arenal ofrece un itinerario de trail running exigente pero muy gratificante, con gran desnivel y paisajes de alta montaña. Un clásico leonés que combina leyenda, esfuerzo y belleza natural.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('26010', 'sendero', 'Pico Teleno', 'El Pico Teleno (2185 m) es una montaña sagrada con historia templaria. La ruta desde Pontón del Arenal ofrece un itinerario de trail running exigente pero muy gratificante, con gran desnivel y paisajes de alta montaña. Un clásico leonés que combina leyenda, esfuerzo y belleza natural.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('16215', 'poza', 'Nacimiento del río Júcar', 'El nacimiento del río Júcar en Tragacete ofrece una ruta de trail running espectacular. Con unos 600 m de desnivel en media maratón aproximada, el recorrido permite disfrutar de paisajes de hoces, cascadas y un entorno natural de gran valor.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('03002', 'sendero', 'Pico Montcabrer', 'El Pico Montcabrer es el techo del Parque Natural de la Sierra de Mariola. La ascensión desde el refugio Les Foies es exigente, con un desnivel importante y un terreno variado que pone a prueba a los corredores. Las vistas panorámicas desde la cima compensan el esfuerzo en este rincón alicantino lleno de encanto.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('19065', 'sendero', 'Hayedo de Tejera Negra', 'El Hayedo de Tejera Negra es uno de los hayedos más meridionales de Europa. En otoño se transforma en un espectáculo de colores que hace de cualquier ruta de trail running una experiencia mágica. Senderos suaves y un entorno forestal único lo convierten en un destino perfecto para correr rodeado de naturaleza.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('28093', 'sendero', 'Puerto de la Fuenfría', 'El Puerto de la Fuenfría y el Camino Schmidtt son un clásico del trail running en la Sierra de Guadarrama. Un paso histórico con múltiples senderos que permiten combinar historia, paisajes bucólicos y esfuerzo físico en un entorno muy accesible desde Madrid.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('23904', 'sendero', 'Pico Banderillas', 'El Pico Banderillas (1993 m) forma parte de un conjunto de torres calizas espectaculares en la Sierra de Segura. Sus rutas de trail running ofrecen desafíos técnicos y paisajes salvajes ideales para corredores de montaña que buscan aventura y soledad.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('22059', 'sendero', 'Ibón de Piedrafita', 'El Ibón de Piedrafita y la Sierra de Partacua ofrecen un entorno pirenaico salvaje y desafiante. Desde Piedrafita de Jaca se accede a un circo de cumbres con lagos y paisajes alpinos perfectos para trail running de alta montaña.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('33046', 'activo', 'Barranco del río Rubó', 'En la cuenca del río Cares, cerca de Trescares, el Barranco del río Rubó es una excelente opción para iniciarse en el barranquismo. Accesible por una antigua calzada romana, combina tramos acuáticos con saltos, toboganes y pozas de aguas cristalinas.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('43071', 'activo', 'Barranco de Canaletas', 'El Barranco de Canaletas es un clásico acuático ideal para principiantes. Con sifones, toboganes, cuevas y saltos, ofrece una experiencia muy divertida y completa. Rodeado de un entorno mediterráneo de gran belleza, es perfecto para mojarse y disfrutar del barranquismo en la comarca de la Terra Alta.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('29065', 'cueva', 'Sima del Diablo', 'La Sima del Diablo es una sima angosta y sombría en la serranía de Ronda. Aunque exigente y con rapeles notables, ofrece una experiencia técnica y emocionante para quienes ya tienen algo de experiencia. Un lugar con fuerte componente acuático y verticalidad en un entorno de gran belleza.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('22107', 'poza', 'Garganta de las Gloces', 'La Garganta de las Gloces es una de las joyas del barranquismo en la Sierra de Guara. Su fisura estrecha y profunda, con un entorno geológico espectacular, ofrece un recorrido técnico y muy estético. Un barranco mítico que combina aventura y belleza natural en uno de los paraísos del barranquismo español.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('51001', 'activo', 'Barranco de Arbillas', 'El Barranco de Arbillas, en la vertiente sur de Gredos, es una excelente opción cercana a Madrid. Con rapeles y toboganes en un entorno de gran belleza, combina aventura y accesibilidad, siendo muy popular entre los barranquistas de la zona centro.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('16078', 'activo', 'Los Cortados', 'Los Cortados ofrecen un abanico de opciones de barranquismo en la serranía de Cuenca. Sus estrechamientos, saltos y toboganes en un entorno de hoces espectaculares lo convierten en un lugar muy completo y variado para disfrutar del barranquismo.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('22069', 'activo', 'Barranco del Furco', 'El Barranco del Furco, en el valle de Broto, es un cañón espectacular con rapeles notables y un entorno de gran belleza en el Parque Nacional de Ordesa. Sus formaciones geológicas y el caudal lo convierten en una experiencia memorable y técnica.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('39015', 'activo', 'Coriscao', 'Coriscao es una de las ascensiones más emblemáticas que parten desde el puerto de San Glorio. La subida hasta sus más de 2000 m de altitud no tiene mucha exigencia; sin embargo, el descenso presenta una experiencia muy gratificante, con las magníficas siluetas de Peña Prieta y el Pico Tres Provincias acaparando la mirada.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('39096', 'activo', 'Coriscao', 'Coriscao es una de las ascensiones más emblemáticas que parten desde el puerto de San Glorio. La subida hasta sus más de 2000 m de altitud no tiene mucha exigencia; sin embargo, el descenso presenta una experiencia muy gratificante, con las magníficas siluetas de Peña Prieta y el Pico Tres Provincias acaparando la mirada.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('31092', 'activo', 'Okabe', 'Extraordinario mirador de las cumbres de Esterenzubi, desde este monte se contempla a vista de pájaro la maravilla forestal que constituye la selva de Irati, uno de los bosques más importantes de Europa. Una ascensión asequible y muy recomendable para disfrutar de la belleza del Pirineo navarro.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('24145', 'sendero', 'Laguna de las Verdes', 'Este escenario impoluto de alta montaña, tupido de nieves perfectas en la estación fría, está al alcance de todos ya sea con raquetas o tablas. Todo el espíritu de las tierras del norte se concentra en los relieves de Babia, que cuenta con esta laguna tan popular como admirada, a la que sube una ruta entre vegas, prados y picos escarpados desde Torre de Babia.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('26003', 'sendero', 'Laguna de las Verdes', 'Este escenario impoluto de alta montaña, tupido de nieves perfectas en la estación fría, está al alcance de todos ya sea con raquetas o tablas. Todo el espíritu de las tierras del norte se concentra en los relieves de Babia, que cuenta con esta laguna tan popular como admirada, a la que sube una ruta entre vegas, prados y picos escarpados desde Torre de Babia.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('18098', 'sendero', 'La Sagra', 'Montaña solitaria y altiva, que se levanta en un extremo olvidado de Sierra Nevada, considerada por muchos como una de las cumbres más bonitas de cuantas tenemos en España. Es una mole piramidal que brota abruptamente de unos llanos áridos e interminables, ofreciendo una estampa muy reconocible y singular.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('18164', 'sendero', 'La Sagra', 'Montaña solitaria y altiva, que se levanta en un extremo olvidado de Sierra Nevada, considerada por muchos como una de las cumbres más bonitas de cuantas tenemos en España. Es una mole piramidal que brota abruptamente de unos llanos áridos e interminables, ofreciendo una estampa muy reconocible y singular.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('18903', 'sendero', 'La Sagra', 'Montaña solitaria y altiva, que se levanta en un extremo olvidado de Sierra Nevada, considerada por muchos como una de las cumbres más bonitas de cuantas tenemos en España. Es una mole piramidal que brota abruptamente de unos llanos áridos e interminables, ofreciendo una estampa muy reconocible y singular.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('31023', 'ciclismo', 'Vuelta al valle de Aranguren', 'La propuesta es una travesía corta y popular por una de las rutas más celebradas de la Cuenca de Pamplona. La forman una treintena de kilómetros sin desnivel destacable, con buena parte del firme bien acondicionado por una vía verde, y atravesando varias fuentes y merenderos.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('16219', 'mirador', 'Miradores de Uña', 'Pinares interminables y formas calizas caprichosas dan pábulo a los misterios en la serranía de Cuenca, cuyos enigmas se pueden descifrar a golpe de pedal recorriendo una ruta de 40 km que parte de Callejon de las Majadas. Una sucesión de acantilados forma estos miradores de excepción, desde los que dejarse llevar por la serenidad del valle del Júcar o los bosques de Valdecabras.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('23050', 'activo', 'Jabalcuz', 'Laderas altivas y escarpadas bajan desde el techo de Jaén. El Jabalcuz, con sus 1618 m, ofrece un desafío de primera a quien se atreva a rodar en medio del ambiente de vértigo de crestas y barrancos que desafían el dominio de los cielos andaluces.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('90714', 'sendero', 'Hayedo de Urbasa', 'Una veintena de kilómetros son los que se precisan para coronar los puertos de la sierra de Urbasa, sembrados de hayedos y leyendas. Se circula por un hermosísimo laberinto forestal que invita a perderse para conquistar el alma de este mundo mágico y diferente de bosques sobrecogedores y profundos cortados.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('19067', 'sendero', 'Senderos del Alto Jarama', 'Bucólico paisaje madrileño capaz de poner a prueba la resistencia del ciclista de montaña, este paraíso de sendas y viejos rincones de montaña es una suerte de laberinto natural y laboratorio de la técnica y la destreza biker. Para descubrir estos entornos puede realizarse una ruta circular con salida y llegada en Valdepeñas de la Sierra, siguiendo 34 km en los que se vadean ríos (incluido, evidentemente, el Jarama) y se siente muy cercana la rica vida silvestre de las serranías del Sistema Central.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('28088', 'sendero', 'Senderos del Alto Jarama', 'Bucólico paisaje madrileño capaz de poner a prueba la resistencia del ciclista de montaña, este paraíso de sendas y viejos rincones de montaña es una suerte de laberinto natural y laboratorio de la técnica y la destreza biker. Para descubrir estos entornos puede realizarse una ruta circular con salida y llegada en Valdepeñas de la Sierra, siguiendo 34 km en los que se vadean ríos (incluido, evidentemente, el Jarama) y se siente muy cercana la rica vida silvestre de las serranías del Sistema Central.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('37005', 'sendero', 'Peña de Francia', 'Antiguos caminos de peregrinos ganan estas alturas que se rinden a 1727 m, donde se alza un vértice geodésico tan popular como accesible, pero que supone un grato desafío para toda una jornada ciclomontañera en las entrañas del Parque Natural de Las Batuecas-Sierra de Francia. Siguiendo, por ejemplo, el muy ciclista sendero GR-10, se accede tras 30 km a una cumbre que después presenta un descenso algo técnico y muy emocionante hacia el solitario valle del río Agadón, un verdadero territorio para explorar.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('23028', 'sendero', 'Bosques de Cazorla', 'Roca viva, bosque denso y agua limpia: he aquí los tres elementos que mejor definen el Parque Natural de las Sierras de Cazorla, Segura y Las Villas; aunque tampoco le quedarían mal adjetivos como “escarpado” y “severo”. En otras palabras, intensa sensación de aventura en un territorio magnífico para homologar ruedas.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('90528', 'sendero', 'Vía Nova', 'Esta milenaria calzada romana surca los relieves escondidos de la Terra de Trives en Ourense. Una ruta de 25 km, con un desnivel muy cómodo, discurre por un tiempo pasado y difícil, en el que no faltan rocas que cuentan historias de sus puentes originales.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('34010', 'sendero', 'Vía Nova', 'Esta milenaria calzada romana surca los relieves escondidos de la Terra de Trives en Ourense. Una ruta de 25 km, con un desnivel muy cómodo, discurre por un tiempo pasado y difícil, en el que no faltan rocas que cuentan historias de sus puentes originales.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('90866', 'sendero', 'Camí Natural de l''Antic Trenet', 'La primera línea ferroviaria de vía estrecha que se inauguró en España, allá por el año 1864, unía las estaciones de Carcaixent y Dénia, y ahora se ha convertido en lugar de peregrinaje para adeptos al outdoor de toda condición. En bicicleta de montaña se puede recorrer más de 20 km por un agradable paisaje mediterráneo, en un paseo suave, pero escénico y variado.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('45004', 'sendero', 'Camí Natural de l''Antic Trenet', 'La primera línea ferroviaria de vía estrecha que se inauguró en España, allá por el año 1864, unía las estaciones de Carcaixent y Dénia, y ahora se ha convertido en lugar de peregrinaje para adeptos al outdoor de toda condición. En bicicleta de montaña se puede recorrer más de 20 km por un agradable paisaje mediterráneo, en un paseo suave, pero escénico y variado.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('31195', 'espacio', 'Selva de Irati', 'He aquí uno de los parajes más imprescindibles de nuestros grandes espacios (y no son precisamente pocos). Ejemplo de cómo la comunidad local puede cuidar de su entorno, en el norte de Navarra podemos disfrutar en plenitud de uno de los mayores y mejor conservados bosques de hayas y abetos de toda Europa.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('31185', 'espacio', 'Selva de Irati', 'He aquí uno de los parajes más imprescindibles de nuestros grandes espacios (y no son precisamente pocos). Ejemplo de cómo la comunidad local puede cuidar de su entorno, en el norte de Navarra podemos disfrutar en plenitud de uno de los mayores y mejor conservados bosques de hayas y abetos de toda Europa.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('33028', 'espacio', 'Bosque de Muniellos', 'Árboles fuertes y resistentes que en su día sirvieron para la construcción de los barcos de la Armada Invencible; mantos vegetales vírgenes que recorren las brumas y las leyendas; musgos, líquenes y sauces junto a la ribera del río; tejos, acebos y hayas en las alturas, acompañando el reinado indiscutible del roble albar. Ubicado en el Parque Natural de las Fuentes del Narcea, en esta masa forestal asturiana hay pura riqueza natural y sentimental.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('42069', 'espacio', 'Hayedo del valle de Urbión', 'La sierra de la Demanda cuenta con un amplio catálogo de espacios encantados, pero pocos tan sorprendentes como este frondoso hayedo que brota en la profundidad de un valle bañado por el río Urbión. En otoño se viste de gala, pero en cualquier época del año merece la pena pasarse por este territorio húmedo y umbrío, pleno de fascinantes rincones donde el agua parece contener un misterioso secreto.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('10096', 'espacio', 'Bosques de Ambroz', 'Un suave sendero se interna durante una veintena de kilómetros por el valle de Ambroz, un popular espacio natural al norte de Cáceres. Aquí un sinfín de castaños, robles, alisos, chopos, olivos, encinas y alcornoques lanzan su canto de sirena, mudo pero colorido, marcando un brutal contraste con las ásperas faldas de Gredos.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('90958', 'espacio', 'Hayedo de Otzarreta', 'En la vertiente vizcaína del Parque Natural de Gorbeia se alzan hayas solemnes entre las que se filtran luces enigmáticas que dan al lugar un aspecto salvaje y encantado. Una suerte de utopía natural, de fantástico colorido, donde el rumor del río y el piar de sus moradores transportan a épocas más sencillas.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('17114', 'espacio', 'Fageda d''en Jordà', 'Inspiración para artistas y poetas, e imprescindible para los senderistas, este delicioso bosque de hayas crece sobre la colada de lava del volcán del Croscat, en La Garrotxa (Girona). Territorio de sombras alargadas y misticismo, es uno de esos lugares en los que dejarse abrazar por el grito del silencio.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('17184', 'espacio', 'Fageda d''en Jordà', 'Inspiración para artistas y poetas, e imprescindible para los senderistas, este delicioso bosque de hayas crece sobre la colada de lava del volcán del Croscat, en La Garrotxa (Girona). Territorio de sombras alargadas y misticismo, es uno de esos lugares en los que dejarse abrazar por el grito del silencio.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('39012', 'espacio', 'Secuoyas del monte Cabezón', 'Allá por el año 1940 se plantaron estos árboles fabulosos, inhabituales en Cantabria, convertidos ahora en un bosque inmenso y longevo, con troncos de dimensiones majestuosas y copas robustas que engalanan las laderas del monte de Las Navas. Son centenares de gigantes olvidados, declarados con razón Monumento Natural.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('01017', 'espacio', 'Fragas do Eume', 'Al hablar de escenarios mágicos y misteriosos no puede faltar algún rincón de Galicia. Aunque, más que rincón, esto es una ingente masa forestal de 9000 Ha de exuberancia única y espíritu atlántico. Helechos y líquenes afloran entre troncos primigenios de alisos, castaños, robles y fresnos.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('15050', 'espacio', 'Fragas do Eume', 'Al hablar de escenarios mágicos y misteriosos no puede faltar algún rincón de Galicia. Aunque, más que rincón, esto es una ingente masa forestal de 9000 Ha de exuberancia única y espíritu atlántico. Helechos y líquenes afloran entre troncos primigenios de alisos, castaños, robles y fresnos.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('28088', 'espacio', 'Hayedo de Montejo', 'Reconocido como Patrimonio Mundial por la Unesco, las estribaciones madrileñas de la sierra de Ayllón acogen este singular espacio, objeto de estudio de científicos y hogar de árboles centenarios. Diversas rutas serpentean por sus rincones, incluida una circular que corre junto al río Jarama, aunque para todas ellas hará falta solicitar un permiso por lo sensible de su ecosistema.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('38012', 'espacio', 'Sendero del Bosque Encantado', 'Tenerife es una tierra de fuertes contrastes donde tan pronto uno puede perderse por inmensidades volcánicas como por este bosque húmedo y primigenio, coqueta muestra de los bosques de laurisilva que resisten desde la Era Terciaria. Mucho valor ecológico y rutas asequibles por los caminos de la Reserva Natural Integral de El Pijaral es lo que aguarda en esta auténtica fantasía natural.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('33036', 'playa', 'Torimbia', 'En esta playa, una de las más salvajes de Asturias, la fuerza del mar y la tranquilidad de los helechos configuran un panorama colosal que se expande hacia unos horizontes orlados de verdes lomas. Forma una concha apabullante en el concejo de Llanes, recogida por los acantilados y batida por los vientos, y tiene una larga tradición nudista; de hecho, es uno de los arenales naturistas mejor considerados de España.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('30016', 'playa', 'Playa Larga', 'No es que su nombre deje mucho a la imaginación, aunque para los que no conozcan estas costas de Calblanque, en Cartagena, es de rigor comentar que se trata de uno de los ecosistemas más portentosos de todo el Mediterráneo. 3 km de arenas soleadas y conectadas con una cadena de playas forman un espacio natural protegido y frágil en el que uno puede mostrar fácilmente su empatía con el entorno.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('01007', 'playa', 'Carnota', 'Playa en un estado de conservación ejemplar, que se extiende más de 7 km, lo que la convierte en la más larga de la costa gallega. Con bajamar puede tener hasta 500 m de anchura, momento en el que también se forman coquetas pozas que se pueden usar a modo de jacuzzi natural.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('35034', 'playa', 'Playas de Papagayo', 'Conjunto de playas de arenas doradas rodeadas de acantilados superlativos calcinados por las eras y por el Sol, localizadas en el sur de Lanzarote, a los pies del Monumento Natural de Los Ajaches. Absolutamente fotogénicas, con someras aguas de color turquesa, desde aquí se avistan la vecina isla de Fuerteventura y el islote de Lobos, formando un horizonte abrumador que invita a dejarse llevar por los sueños del viento.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('07006', 'playa', 'Macarella y Macarelleta', 'Las clásicas aguas centelleantes de Menorca encuentran aquí recodos privilegiados, abrazados por encinas y pinos que se estiran hacia el mar, envidiosos de la suerte que tiene los humanos al poder descender a estas pequeñas y depuradas calas, de espíritu virgen, pero, eso sí, muy visitadas y fotografiadas durante la temporada alta.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('04017', 'playa', 'Ensenada de los Genoveses', 'Extenso arenal, resplandeciente y fino, que se extiende hasta convertirse en la segunda playa más extensa del cabo de Gata, formando un enclave único, ideal para disfrutar en familia y sacar la cámara de paseo por el amable y delicioso litoral de Níjar. Aguas mansas lamen estas costas exquisitas, vestidas de dunas y vegetación.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('36005', 'playa', 'Barra', 'En Cangas de Morrazo, provincia de Pontevedra, se encuentra la playa de Barra, otro conocido espacio naturista que cuenta con un sinfín de encantos: solitaria, resguardada de los vientos, carácter prístino, arenas suaves y aguas gélidas. Al fondo se levantan las islas Cíes, completando el hermoso escenario de esta larga, fina y elegante playa de dunas.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('05008', 'playa', 'Playa del Silencio', 'Playa muy especial, de fácil acceso, pero poco transitada. Sin duda se trata de una de las muestras más bellas del modelado del Cantábrico, salvaje como toda la costa asturiana, y hasta hace poco bastante secreta, aunque la democratización de la fotografía la han convertido en un destino imprescindible a la hora de retratar la magia de nuestros escenarios más insólitos.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('18001', 'playa', 'Cala Aiguablava', 'Oda a las bellezas más minimalistas, y considerada una de las playas más bonitas de Cataluña, su topónimo se queda corto a la hora de describir estas aguas deslumbrantes que bañan fondos poco profundos de arena fina y dorada. Esta playa exclusiva, al sur de Begur, aglutina todas las bondades naturales de la Costa Brava.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('38012', 'playa', 'Playa de Benijo', 'Escoltado por el Roque Benijo y el Roque La Rapadura, este arenal es uno de los más fotogénicos de todo el archipiélago canario. Sus arenas negras se extienden en la costa norte de Tenerife, en el área de Anaga, y es muy poco transitada por el turismo, por lo que se ha conservado salvaje, sin equipar, como una suerte de templo local para recordar la belleza masiva de estos entornos volcánicos tan melancólicos como enérgicos.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('38002', 'playa', 'Playa de Benijo', 'Escoltado por el Roque Benijo y el Roque La Rapadura, este arenal es uno de los más fotogénicos de todo el archipiélago canario. Sus arenas negras se extienden en la costa norte de Tenerife, en el área de Anaga, y es muy poco transitada por el turismo, por lo que se ha conservado salvaje, sin equipar, como una suerte de templo local para recordar la belleza masiva de estos entornos volcánicos tan melancólicos como enérgicos.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('05005', 'espacio', 'Lagos de Covadonga', 'Enclave edénico, extremadamente popular y hermoso, los lagos glaciares de Enol y Ercina, más conocidos como Lagos de Covadonga, son visitados cada año por miles de turistas, aunque quien busque épocas tranquilas disfrutará de un escenario genial a más de 1000 m de altura en el macizo occidental de los Picos de Europa. Lo que aguarda son aguas espejadas y espíritu añejo asturiano.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('22204', 'espacio', 'Ibones de Anayet', 'Conjunto de joyas lacustres situadas por encima de los 2000 m, a los pies del espléndido pico Anayet. Se trata de una delicia natural encajonada entre gigantes pirenaicos, cuyo acceso requiere de un buen pateo, por lo que este recóndito lugar del valle del Tena nunca está masificado.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('90654', 'espacio', 'Gorg Blau', 'Embalse custodiado por los picos del Puig Major y el Puig Massanella, hundido en un valle majestuoso de la sierra de Tramuntana, esta perla mediterránea concentra buena parte de la riqueza paisajística y natural del interior mallorquín. Aquí se recogen tanto las aguas del deshielo como viejas historias sobre damas del agua cuyo peligroso amor causaba magnetismo entre los hombres, o de bandoleros ocultos tras cumplir algunos de sus inconfesables objetivos.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('27007', 'espacio', 'Lac de Mar', 'Son muchos los lagos maravillosos que acoge el Parc Nacional d’Aigüestortes i Estany Sant Maurici, así que más que escoger uno, sencillamente lo destacamos por la calidad de sus aguas, tan limpias como el aire que lo rodea, a más de 2000 m de altitud, en pleno corazón de la Val d’Aran. Escenario para quemar el obturador o pegarse un baño extremo, recompensa tras completar uno de los trekkings más interesantes de estas periferias pirenaicas.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('50117', 'espacio', 'Laguna de Gallocanta', 'Ocupando una colosal cuenca cerrada a 1000 m de altitud, esta laguna zaragozana es un importantísimo refugio de aves migratorias, cuartel de invierno para numerosas especies, aunque es la grulla la que se lleva el protagonismo, juntándose aquí decenas de miles de ejemplares en lo que supone uno de los espectáculos ornitológicos más sobresalientes de toda Europa, excusa perfecta para asomarse a sus aguas al amanecer, teleobjetivo en mano, e intentar (y a duras penas conseguir) retratar esa reserva natural esencial.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('13014', 'espacio', 'Lagunas de Ruidera', 'Parque natural que se extiende entre Ciudad Real y Albacete, compuesto por un mosaico heterogéneo de lagunas, conectadas entre sí por cascadas y canales subterráneos. Un puñado de rutas recorren este humedal donde también caben otras actividades como el kayak, la pesca e incluso el buceo.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('42215', 'espacio', 'Laguna Negra', 'Enigmático lago glaciar, encajonado entre las abruptas moles de los picos de Urbión, cuyas paredes oscuras se replican sobre este espejo natural ofreciendo un reflejo estremecedor. Legado de olvidados periodos glaciares, nos encontramos en un terreno de alta montaña que no rinde fácilmente sus secretos.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('05105', 'espacio', 'Laguna Grande de Gredos', 'Por aquí han peregrinado todos los montañeros de la zona centro, pues el circo de Gredos luce una belleza sosegada, inspiradora de grandes relatos alpinos. A casi 2000 m de altitud, y a los pies de titanes como el Almanzor, pernoctar aquí es un canto a la fraternidad, a nuestro pasado más indómito y al amor por las cumbres.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('29055', 'espacio', 'Laguna de Fuente de Piedra', 'Precisamente por hallarse en Málaga, hogar de magníficas playas, la Reserva Natural Laguna de Fuente de Piedra, la más extensa de Andalucía, permanece salvaje y muy bien conservada, a la vez que acoge la colonia de flamencos más grande de la península. Suaves relieves donde brotan olivos y cereales rodean este bucólico humedal salino de la comarca de Antequera.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('22204', 'activo', 'Llena Cantal', 'Comenzamos este repaso por algunas de las montañas más idílicas de nuestros incontables relieves con la Llena Cantal. De milagro este esbelto cono alpino no llega a los 3000 m, aunque a su semblante soberbio poco le importa. Pirámide impecable de los reinos montañosos del Alto Gállego, forma parte de una corona afilada que incluye el Piedrafita, el Gran Facha y el Gaurier.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('90258', 'activo', 'Txindoki', 'En la legendaria sierra de Aralar, en Gipúzcoa, territorio de culturas ancestrales donde las montañas custodian una estampa de campas hermosas y robustos caseríos, se levanta esta montaña mágica y brava, de aspecto desafiante pero con laderas acogedoras. Su genial vértice, que domina los llanos desde los 1342 m, es puro magnetismo montañero y ejerce una llamada que pocos rechazan.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('24130', 'activo', 'Cervino de León', 'En la Montaña Oriental Leonesa aparece esta delicada torre calcárea, conocida popularmente como el “Cervino de León”, cuya silueta, idílica como la que hubiera dibujado un chaval, se abalanza sobre las aguas del embalse de Riaño, en el parque regional del mismo nombre. Parece un cohete de piedra que se estira para tocar los cielos lanzando un hechizo irresistible al imaginario montañero.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('25082', 'activo', 'Els Encantats', 'Moldeadas por los hielos glaciares, las agujas gemelas de Els Encantats (2748 m) dominan un intenso escenario de barrancos, lagos, cascadas y colosos de granito en medio del Parc Nacional d’Aigüestortes i Estany Sant Maurici. Estampa emblemática y demoledora, existe una ruta, precisamente conocida como Els Encantats, que ofrece varias jornadas de senderismo por estos paisajes de cuento, con salida y llegada en Vielha.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('35034', 'activo', 'Montañas de Fuego', 'Apenas superan los 500 m de altitud, pero su tamaño modesto es de sobra compensado por lo fascinante de su semblanza. Nos encontramos ante uno de los lugares más asombrosos de Canarias, que no es decir poco. En el Parque Nacional de Timanfaya, en Lanzarote, surge esta cadena de volcanes, calcinada por el Sol, el tiempo y las entrañas del mundo, convertida en tierra de leyendas.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('90949', 'activo', 'Anboto', 'He aquí otra montaña de leyenda, esta en territorio vasco, cuyos paisajes están siempre cargados de misterio, cultura montañera y viejas historias mitológicas. El Anboto es una cúspide elegante y demoledora, que a pesar de su modesta altitud (1331 m), se eleva poderosa y descomunal como una suerte de fortaleza inexpugnable sobre los caseríos y pastizales del valle de Atxondo.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('08190', 'activo', 'Pedraforca', 'Su emblemática forma, producto de la erosión y tan curiosa como atractiva, la ha convertido en el emblema de la sierra del Cadí. Formada por dos cumbres, como dientes afilados mordiendo estos cielos pálidos, gran obra del viento y el tiempo, su silueta reconocible la aleja de una belleza clásica para acercarla a una hermosura poderosa y enérgica.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('18042', 'activo', 'Alcazaba', 'En el podio de montañas más altas de Sierra Nevada se encuentra este bellísimo titán, en cuyas vertientes nace el río Genil y que alcanza nada menos que los 3371 m. Su presencia magnífica la ha convertido en uno de los lugares de peregrinaje clásicos del alpinismo en el sur peninsular; además, ofrece un montón de posibilidades para calzarse las botas y disfrutar de trekkings sencillos o ambiciosos por uno de los paisajes nevadenses más imponentes.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('22230', 'activo', 'Cilindro de Marboré', 'La punta más septentrional del célebre triplete que completan el monte Perdido y el pico Añisclo es este macizo que reina sobre el Parque Nacional de Ordesa y Monte Perdido. Además de su emblemática figura, su entorno puede ser explorado desde el refugio de Góriz, uno de los más históricos de nuestras montañas.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('22107', 'activo', 'Cilindro de Marboré', 'La punta más septentrional del célebre triplete que completan el monte Perdido y el pico Añisclo es este macizo que reina sobre el Parque Nacional de Ordesa y Monte Perdido. Además de su emblemática figura, su entorno puede ser explorado desde el refugio de Góriz, uno de los más históricos de nuestras montañas.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('01005', 'mirador', 'Faro del cabo Vilán', 'Fieles atalayas para los mareantes, el del cabo Vilán es el epítome de faro, levantado tras el naufragio del acorazado HMS Serpent en 1890. Adaptado a las orografías de esta montaraz sección de la Costa da Morte, el viento juega aquí a favor del espectáculo visual.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('27051', 'mirador', 'Faro de la Isla Pancha', 'No es ninguna casualidad que Galicia cuente con algunos de los faros más bellos e imponentes de nuestras costas, pues el azote salvaje de sus aguas ha hecho claudicar incluso a los más afortunados y curtidos navegantes. Hete aquí otra muestra, edificada en la parte más occidental de la ría de Ribadeo, que se presenta precioso, fotogénico y aislado.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('07037', 'mirador', 'Faro de Cavalleria', 'Enclavado en la vertiginosa costa norte de Menorca, vigilando oleajes y precipicios, se encuentra este peculiar faro al que se puede acceder en coche, aunque no por eso deja de presentar un ambiente indómito. Junto a él hay, además, una cueva a la que se puede acceder y que ofrece unas vistas sublimes de los románticos atardeceres mediterráneos.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('01001', 'mirador', 'Torre de Hércules', 'Se cuenta que el mismísimo Hércules erigió esta colosal obra de ingeniería para conmemorar su victoria sobre el gigante Gerión. Pero la realidad es casi más interesante, pues se trata del faro en funcionamiento más antiguo del mundo, el segundo más alto de España y todo un símbolo de A Coruña.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('04017', 'mirador', 'Faro del cabo de Gata', 'Calas pequeñas ocultándose del afán humano, rocas como agujas y acantilados como planetas, salpicadas con bravura por el agua cristalina del cabo de Gata... Nos encontramos en un lugar bellísimo, el arrecife de las Sirenas cuyas antiguas chimeneas volcánicas se elevan por encima del nivel del agua, y sobre el que se alza la estructura más representativa del Parque Natural del Cabo de Gata-Níjar y cuya panorámica es de las imprescindibles en el haber del visitante.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('35030', 'mirador', 'Faro de la Entallada', 'Montañas desoladas y abismos contundentes abrazan este peculiar edificio construido en 1953, que se levanta en las costas del municipio de Tuineje, en Fuerteventura, y que custodia el punto más cercano a África de todas las Canarias. Inmensas vistas del Monumento Natural de los Cuchillos de Vigán y sus grandes acumulaciones de coladas volcánicas hacen su llamada tanto a científicos como a fotógrafos.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('30016', 'mirador', 'Faro del cabo de Palos', 'Sobre el montículo rocoso más alto del cabo de Palos, en tierra murciana, reposa este faro declarado Bien de Interés Cultural. Cargado de historia, aquí primero se levantó un templo dedicado al dios romano Saturno, que después fue reconvertido en puesto de vigilancia contra los asaltos de piratas berberiscos.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('48017', 'mirador', 'Faro del cabo Matxitxako', 'Encuentro de dos épocas, el viejo y el nuevo faro de este rinconcito vizcaíno proyectan su mirada hacia el bravo mar Cantábrico. Se encuentra al final de las estribaciones del monte Sollube, en Bermeo, ofreciendo unas vistas poco conocidas del famoso islote de San Juan de Gaztelugatxe que se alargan hasta el poderoso cabo de Ogoño, todo envuelto por la brumosa naturaleza de la Reserva de la Biosfera de Urdaibai.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('33013', 'espacio', 'Palacio Real de Olite', 'Emblema indudable del viejo reino de Navarra y obra cumbre de Carlos III el Noble, este palacio de ensueño con jardines colgantes le remite a uno a cuentos y películas fantasiosas. A pesar de la aparente anarquía de su construcción un complejo de torres, galerías, patios y centenares de estancias , su semblante majestuoso continúa levantando el interés por nuestras obras arquitectónicas más soberbias.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('26071', 'espacio', 'Ermita de San Felices', 'Dominando los Riscos de Bilibio y sus afiladas crestas, desde esta histórica ermita se puede obtener una panorámica ideal del Ebro internándose entre las campas y viñedos de La Rioja, a su paso por las Conchas de Haro. Es un paraje solitario excepto a finales de junio, cuando una alegre comunidad local se reúne para celebrar la Batalla del Vino, que ha sido nombrado en alguna ocasión como el mejor rincón de España.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('28027', 'espacio', 'Buitrago de Lozoya', 'En uno de los incontables meandros del madrileño río Lozoya se levanta esta villa rodeada todavía por murallas de origen árabe, a los pies del puerto de Somosierra, puerta de entrada a la sierra de Guadarrama. Su iglesia gótica, su viejo alcázar y su torre del reloj conservan el ambiente medieval de esas villas de antaño, una de las imprescindibles de la zona centro.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('90689', 'espacio', 'Castillo de Butrón', 'Se puede emprender un viaje evocador de viejas batallas entre banderizos de la nobleza vizcaína visitando esta obra arquitectónica de enorme belleza, situada en Gatika, sobre el peñascal de Gantzurritz. Además de atalaya defensiva, constituye un esfuerzo artístico inigualable, una atracción visual.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('48017', 'espacio', 'San Juan de Gaztelugatxe', 'No podía faltar este icónico escenario de la costa de Vizcaya, más visitado que nunca por obra y gracia de los rodajes de Juego de Tronos. Una isla, conectada con tierra por un puente de piedra, se convierte en enclave místico, y sus rocas podrían contar infinidad de leyendas, recordar intensas batallas o hablar de la pericia marinera vasca.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('42173', 'espacio', 'Ermita de San Saturio', 'Cuando el Duero pasa sereno por Soria es contemplado con la misma tranquilidad por esta ermita que cuelga de un modesto roquedal cuyas grutas naturales fueron aprovechadas para su construcción. Escenario de milagros varios, nos quedamos con el orquestado por la propia naturaleza, en especial cuando el cielo estrellado y sus muros azafranados se reflejan sobre las aguas espejadas.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('40057', 'espacio', 'Castillo de Coca', 'Legado del más importante arte mudéjar, la villa segoviana de Coca cuenta con un castillo idílico, presidido por una impactante torre del homenaje. Se levanta sobre los meandros del río Voltoya, cuyos escarpados territorios servían de foso natural.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('26130', 'espacio', 'Monasterios de San Millán de Yuso y de Suso', 'Hace más de un milenio, entre los muros de este recinto monástico, unos sabios monjes escribieron las primeras palabras en romance, embrión de nuestra lengua castellana. Este incalculable legado lingüístico bien le valía su declaración como Patrimonio Mundial de la Unesco.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('09215', 'espacio', 'Ermita de San Bernabé', 'Multitud de cuevas y galerías interconectadas se internan en las tripas del complejo kárstico más importante de España, el Monumento Natural de Ojo Guareña. Localizadas en la localidad burgalesa de Merindad de Sotoscueva, una de estas bóvedas fue aprovechada para construir una ermita que hoy es objeto de visita para todos aquellos que gustan de ligar la naturaleza con la historia.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('18002', 'espacio', 'Pont Vell de Besalú', 'Salvando el curso del río Fluvià, este puente medieval se ha convertido en uno de los monumentos más populares de la Garrotxa, en Girona. Reconstruido en varias ocasiones, incluida la que se llevó a cabo tras un bombardeo durante la Guerra Civil, las rocas del Fluvià siempre han estado disponibles para apuntalar este acceso único al casco antiguo de Besalú, villa que ocupa un lugar destacado en todos los listados de pueblos más bonitos de España.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('09905', 'poza', 'Orbaneja del Castillo', 'Burgos cuenta con un catálogo inabarcable de pueblos pintorescos, incluida esta villa medieval cuyas idílicas y muy bien conservadas casitas orillan un esplendoroso torrente, que acaba desembocando en el Ebro tras dejar una postal impecable de pozas turquesas. A pesar del estruendo de sus aguas, esta villa es un remanso de paz para el espíritu, a la vez que un ajetreado escenario para los fotógrafos.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('37364', 'poza', 'Pozo de los Humos', 'El río Uces, afluente del Duero, encuentra aquí un enorme escollo de 50 m que resuelve con un salto de tal magnitud que hasta Unamuno quedó prendado de él. “La caída de esas aguas es una de las más hermosas que pueden verse en aquellos adustos tajos”, escribía el poeta al describir este lugar, destinatario principal de los halagos que recibe en Parque Natural de Arribes del Duero.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('09050', 'poza', 'Salto del Nervión', 'Si uno se acerca por el puerto de Orduña podrá disfrutar de las mejores vistas de esta cola de caballo, una de las cascadas más sobrecogedoras y la más grande del país. Forma un espacio mágico, rodeado de enormes hayedos, en el que el agua realiza una caída libre de casi 300 m sobre roca viva.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('48074', 'poza', 'Salto del Nervión', 'Si uno se acerca por el puerto de Orduña podrá disfrutar de las mejores vistas de esta cola de caballo, una de las cascadas más sobrecogedoras y la más grande del país. Forma un espacio mágico, rodeado de enormes hayedos, en el que el agua realiza una caída libre de casi 300 m sobre roca viva.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('10096', 'poza', 'Chorrera de Hervás', 'Entre coloridos robles y castaños brota una de las cascadas más bonitas de Cáceres, excelente excusa para visitar el valle de Ambroz e internarse por estas estribaciones poco conocidas por los foráneos de la sierra de Gredos en su vertiente extremeña. Tampoco hay que pasar por alto el barrio judío de Hervás, conjunto en excelente estado de conservación que mantiene con vida el pasado histórico de la región.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('38009', 'poza', 'Cascada de Colores', 'Un muro artificial levantado para contener las aguas de la Caldera de Taburiente, uno de esos lugares marcianos de la isla de La Palma, ha sido víctima de los caprichos de la naturaleza, pues el hierro y el musgo han pintado la tierra volcánica, dejando un gracioso espectáculo que bien puede servir de recuerdo de esa simbiosis olvidada entre el hombre y la Tierra.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('38027', 'poza', 'Cascada de Colores', 'Un muro artificial levantado para contener las aguas de la Caldera de Taburiente, uno de esos lugares marcianos de la isla de La Palma, ha sido víctima de los caprichos de la naturaleza, pues el hierro y el musgo han pintado la tierra volcánica, dejando un gracioso espectáculo que bien puede servir de recuerdo de esa simbiosis olvidada entre el hombre y la Tierra.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('03048', 'poza', 'Fuentes de Algar', 'El modelado del río Algar, en Alicante, deja aquí un mosaico de cascadas y manantiales naturales, pretérita fuente de salud para los locales, aptas para baños refrescantes y paseos familiares. Este solitario vergel, que contrasta con la cercana Benidorm, conserva una riqueza natural que lo ha convertido en una escuela viva de la educación medioambiental.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('16078', 'poza', 'Nacimiento del río Cuervo', 'Situado en el extremo noroccidental de Cuenca, sobre la muela de San Felipe, este manantial salvaje atesora uno de los valores geomorfológicos y paisajísticos más importantes del espacio natural que lo rodea, y es objeto de peregrinación eterna entre serranías abruptas, bañadas aquí por aguas que surgen de las profundidades de la tierra formando cascadas y pozas vestidas de musgo y enigmas.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('02023', 'poza', 'Nacimiento del río Mundo', 'Ese oasis que es la sierra de Segura encuentra aquí uno de sus espacios más alucinantes. Una ruta desde la localidad de Riópar, en Albacete, emprende su camino a la búsqueda de este salto de agua que nace en una cueva a decenas de metros del suelo y cuyas características producen un fenómeno muy celebrado por los amantes del turismo rural, el conocido “reventón”, cuando las precipitaciones provocan una furiosa respuesta de la cascada, generalmente en tiempo otoñal.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('19291', 'poza', 'Cascada de Trillo', 'Trillo es una maravillosa villa surcada por el agua y el atronador silencio. Aquí, el río Cifuentes divide el pueblo en dos partes mientras se despeña por unas geografías de vida abundante que desembocan en el Tajo. Constituye una de las elecciones más sencillas para comenzar cualquier viaje a la Alcarria por las históricas sendas de Guadalajara.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('50192', 'poza', 'Monasterio de Piedra', 'A su paso por la villa de Nuévalos, el río Piedra forma un soberbio paraje natural en torno a este monasterio fundado por los monjes cistercienses en el s. XII, uno de los lugares más visitados de Zaragoza. Aquí, la sinfonía del agua pasando por grutas y saltando entre cascadas convierte un escenario árido en un vergel exuberante.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('36015', 'astro', 'Illas Atlánticas', 'Los archipiélagos de las islas Cíes, Ons, Sálvora y Cortegada, además de un paraíso de la conservación y la sostenibilidad, destino de mochileros y buscadores de paz, son también uno de los puntos más emocionantes para buscar fotografías con nocturnidad y alevosía. Cielos sin contaminación y amplios horizontes esperan en uno de nuestros destinos más prístinos.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('36003', 'astro', 'Illas Atlánticas', 'Los archipiélagos de las islas Cíes, Ons, Sálvora y Cortegada, además de un paraíso de la conservación y la sostenibilidad, destino de mochileros y buscadores de paz, son también uno de los puntos más emocionantes para buscar fotografías con nocturnidad y alevosía. Cielos sin contaminación y amplios horizontes esperan en uno de nuestros destinos más prístinos.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('39052', 'astro', 'Urros de Liencres', 'Estos pequeños e insólitos islotes que se levantan en la costa cántabra, separados de tierra firme por el tiempo y las mareas, evocan algunas de las archiconocidas formaciones de la playa de las Catedrales, pero sin ingentes cantidades de turistas al acecho. Escenario solitario, hermoso y monumental, invitan a largas exposiciones al caer el Sol.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('38033', 'astro', 'Roque de los Muchachos', 'Hay veces que la belleza es inexplicable, como sucede cuando la oscuridad cubre el roque de los Muchachos, el punto más alto de La Palma, donde se sitúa su célebre observatorio astrofísico. Sus impresionantes cielos ofrecen, sin duda, una de las mejores vistas de entre todas las que regalan nuestros paisajes.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('38009', 'astro', 'Roque de los Muchachos', 'Hay veces que la belleza es inexplicable, como sucede cuando la oscuridad cubre el roque de los Muchachos, el punto más alto de La Palma, donde se sitúa su célebre observatorio astrofísico. Sus impresionantes cielos ofrecen, sin duda, una de las mejores vistas de entre todas las que regalan nuestros paisajes.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('45053', 'astro', 'Molinos de Consuegra', 'Los gigantes de El Quijote coronan el cerro Calderico en una de las estampas más conocidas de la provincia de Toledo. Estos 12 molinos de viento recuperados, siempre bulliciosos de visitantes, ofrecen su mejor cara cuando se iluminan por la noche, dominando un panorama que completan los brillos de la histórica localidad de Consuegra.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('27015', 'astro', 'Parc Astronòmic del Montsec', 'Los buscadores de la Vía Láctea tienen aquí un lugar donde maravillarse hasta que salga el Sol. Ubicado en Àger, en la comarca iler-dense de La Noguera, este parque astronómico es un lugar privilegiado para la observación y el conocimiento de las estrellas.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('39015', 'astro', 'Hotel Áliva', 'Además de permitir al viajero disfrutar de la cuidada gastronomía de la comarca de Liébana y de servir de punto de partida de un sinfín de actividades alpinas, el Hotel Áliva, situado en la cota superior del teleférico de Fuente Dé, ofrece una de las imágenes nocturnas más impresionantes que puedan contemplarse: una gigantesca y completa Vía Láctea, de lado a lado del cielo, sobre prados y montañas de alma gentil y semblante añejo.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('10037', 'astro', 'Augustóbriga', 'El esqueleto de esta antigua ciudad romana, levantada a orillas del Tajo entre las actuales Mérida y Talavera de la Reina, ofrece un panorama estupendo para jugar con nuestras lentes, sobre todo por la noche, cuando la luz de luna cubre de sombras y misterios su pórtico, y sus columnas hablan de las viejas y las nuevas civilizaciones.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('45173', 'astro', 'Castillo de Barciense', 'Un enorme león rampante controla el muro principal de este castillo toledano que vigila las praderas de la comarca de Torrijos. Aunque el paso de los siglos se ha dejado notar en su sillería y mampostería, su silueta reconocible contra el cielo nocturno es digna de una buena sesión fotográfica, tan provocadora por sus cielos limpios como por las historias susurradas por el viento sobre los pastizales.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('24002', 'astro', 'Observatorio Andaluz de Astronomía', 'A pocos kilómetros de Alcalá la Real, en la aldea de La Pedriza, se encuentra este observatorio de primer orden para la divulgación astronómica, que aprovecha los cielos oscuros e impresionantes que ofrece la sierra Sur de Jaén. Recientemente certificado como Reserva Starlight, la comunidad local muestra un firme compromiso para que las nuevas generaciones tengan un fácil acceso a la luz de las estrellas.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('33036', 'playa', 'Playa de Gulpiyuri', 'Entre verdes prados asturianos, el mar buscó una forma de conquistar el paisaje, horadando una cueva hacia el interior cuyo hundimiento posterior nos ha legado un rinconcito impactante, una playa tierra adentro. Conocida como la playa más pequeña del mundo, el concejo de Llanes acoge con orgullo esta maravilla geológica que ha despertado un creciente interés turístico en los últimos años.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('90654', 'espacio', 'Sa Calobra', 'Encajonada entre gigantescos acantilados del norte de Mallorca se encuentra una playa diminuta, íntima e icónica, de aguas azuladas y transparentes. El imponente cañón del Torrent de Pareis culmina en un idílico escenario que deja al visitante la boca abierta y los pies bien frescos.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('09905', 'poza', 'Pozo Azul', 'En el pueblo de Covanera, en la frontera entre Burgos y Cantabria, se encuentra esta calita de aguas resplandecientes, con un manantial que vierte sus aguas al río Rudrón. Lo más curioso es que sus aguas se sumergen bajo la montaña, hundiéndose más de una decena de kilómetros, formando un territorio que llama a los espeleo-buceadores más audaces a explorarlo.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('21049', 'espacio', 'Minas de Riotinto', 'Como decía el poeta Paul Éluard, “Hay otros mundos, pero están en este”, y Riotinto es el paisaje extraterrestre por excelencia gracias a sus tierras y aguas de un rojo intenso. Su paisaje, configurado por el afán de dominio del hombre desde la Edad del Cobre, cuando comenzaba a explotarse este caos de tierras yermas, hoy constituye una de las postales más surrealistas que puedan encontrarse.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('38004', 'espacio', 'Sabinas de El Hierro', 'La sabina ha adquirido la categoría de icono en todas las islas Canarias, pero es en El Hierro donde su legado se celebra con mayor júbilo. Los ejemplares de estos árboles que sobrevivieron a la actividad volcánica y al progreso humano son hoy un vestigio del poder de la naturaleza, y sus formas retorcidas y caprichosas, efecto de los vientos alisios, bien pueden servir de metáfora de nuestro impacto en ella.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('90714', 'espacio', 'Río Urederra', 'Con nacimiento en el Parque Natural de Urbasa-Andia, y recorriendo apenas una veintena de kilómetros antes de rendir su cauce en el Ebro, hallamos uno de los ríos más hermosos y coloridos de cuantos surcan las tierras españolas, importantísimo rincón para la biodiversidad en Navarra. El anfiteatro rocoso que acoge el origen de su curso es de notable belleza y su riqueza ambiental justificó su calificación como reserva natural.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('04021', 'espacio', 'Geoda de Pulpí', 'Descubierta en 1999 en la Mina Rica de Almería, las dimensiones y la perfección de esta geoda la convierten en un fenómeno único. Impresionante obra de las dolomías de la sierra de Aguillón, sus cristales inmaculados de selenita nos recuerdan por qué los artistas han tenido siempre en la naturaleza su fuente de inspiración.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('08223', 'cueva', 'Cova Simanya', 'Objetivo persistente de senderistas catalanes, la cueva más conocida del Parc Natural de Sant Llorenç del Munt i l''Obac, en la comarca del Vallès Occidental, es accesible tras una amable ruta que rodea la cima del Montcau. Sus cientos de metros de galerías inspiran a contar historias y sirven para acumular recuerdos.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('90536', 'espacio', 'Catoira', 'El primer domingo de agosto se celebra una original romería vikinga hacia este lugar onírico y tranquilo de Pontevedra, una fiesta profana y colorida que conmemora la defensa gallega frente a los piratas normados y sarracenos que pretendían los tesoros de Santiago de Compostela. Quizá por ser uno de los eventos más tradicionales y espectaculares de Galicia, las celebraciones han hecho sombra al lugar que lo enmarca, Catoira, una delicia natural orlada de molinos de viento, bosques y marismas de las Rías Baixas, todavía engalanada con antiguos vestigios arquitectónicos.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('48907', 'espacio', 'El Bosque Pintado', 'En el bosque de Oma, en Vizcaya, no hace falta elucubrar sobre la fusión entre la cultura y la naturaleza, pues ya se encargó de ello Agustín Ibarrola en la década de 1980. Usando los árboles como lienzo, el artista trazó una suerte de galería al aire libre, donde colores y formas únicas dotan a los troncos de los árboles de un aspecto alegre pero encantado, a la vez nostálgico y efervescente.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('37313', 'espacio', 'Meandro del Melero', 'En la frontera natural entre Salamanca y Cáceres que forman la conjunción de la sierra de Francia y Las Hurdes surge este meandro tan característico del río Alagón. Pozas naturales y el silencio de los pinos y castaños son protagonistas de un espacio para la contemplación y la protección, donde toca poner a trabajar los prismáticos para descubrir la presencia de especies icónicas y amenazadas, como el buitre negro o la cigüeña negra.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('10108', 'espacio', 'Meandro del Melero', 'En la frontera natural entre Salamanca y Cáceres que forman la conjunción de la sierra de Francia y Las Hurdes surge este meandro tan característico del río Alagón. Pozas naturales y el silencio de los pinos y castaños son protagonistas de un espacio para la contemplación y la protección, donde toca poner a trabajar los prismáticos para descubrir la presencia de especies icónicas y amenazadas, como el buitre negro o la cigüeña negra.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('16078', 'espacio', 'La Ciudad Encantada', 'Figuras de formas casi humanas, pero moldeadas por los antojos calcáreos de este rincón de Cuenca, son un escenario fabuloso para regalar la retina de pequeños y mayores. Para ello basta realizar un sencillo recorrido por esa maravilla nunca olvidada que es la Ciudad Encantada, instalada en el imaginario de todas las generaciones de amantes de las naturalezas más arbitrarias.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('90795', 'espacio', 'Las Médulas', 'Los romanos explotaron aquí una de las mayores minas de oro a cielo abierto de su imperio, donde pusieron en práctica su ingeniería más avanzada, alterando un paisaje que hoy es una inusual muestra de los encantos del Bierzo leonés, en un ambiente cargado de misterio e imposible de concebir sin la mano destructora del ser humano.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('30026', 'espacio', 'Gredas de Bolnuevo', 'El salitre y el viento han erosionado esta tierra murciana de sílice y aluminio para formar un peculiar entorno, de aire fantasmagórico. Este paisaje encantado en primera línea de playa es habitual escenario de performances artísticas, objeto de deseo de fotógrafos y rareza natural protegida a los pies de la sierra de las Moreras.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('35025', 'espacio', 'Roque Nublo', 'Alzándose sobre los abruptos contornos del municipio de Tejeda, surge un grupo de formaciones de roca volcánicas y singulares que constituye uno de los espacios más emblemáticos de Gran Canaria. Refugio de cultos desde tiempos muy pretéritos, aquí la naturaleza ha esculpido sus anhelos profundos.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('10115', 'espacio', 'Los Barruecos', 'Incontables bolos graníticos esparcidos aquí y allá, entre grandes charcas, forman parte de la cuenca del río Salor, hogar de nutrias y tritones. Se trata de un paraje imponente, a pocos kilómetros de Cáceres, donde convergen dos zonas de especial protección para las aves, la sierra de San Pedro y los Llanos de Cáceres.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('31032', 'espacio', 'Bardenas Reales', 'Este parque natural, que también es Reserva de la Biosfera, constituye uno de los paisajes más conocidos de nuestra naturaleza: desierto de arcillas y areniscas, territorio de formas improbables, que desafían la gravedad y la imaginación, con un aspecto fiero y cinematográfico. Se puede inmortalizar este vasto territorio a golpe de obturador, sobre todo cuando el sol arranca contrastes a sus caprichos geológicos.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('31232', 'espacio', 'Bardenas Reales', 'Este parque natural, que también es Reserva de la Biosfera, constituye uno de los paisajes más conocidos de nuestra naturaleza: desierto de arcillas y areniscas, territorio de formas improbables, que desafían la gravedad y la imaginación, con un aspecto fiero y cinematográfico. Se puede inmortalizar este vasto territorio a golpe de obturador, sobre todo cuando el sol arranca contrastes a sus caprichos geológicos.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('11035', 'espacio', 'Duna de Bolonia', 'Un sorprendente domo arenoso se eleva más de 30 m sobre uno de los espacios menos transformados y mejor conservados de la costa gaditana. Sus centenares de metros lineales batidos por los vientos del Parque Natural del Estrecho, en el istmo de Punta Camarinal, constituyen uno de los valores naturales más notables de Andalucía.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('16046', 'espacio', 'Lagunas de Cañada del Hoyo', 'Área protegida formada por siete lagunas de colores diferentes, objeto de estudio y devoción, ecosistema frágil donde todavía sobreviven algunos de los últimos galápagos europeos. A su tranquilidad se une el rumor de la brisa que sobrevuela areces, quejigos y tejos.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('04023', 'espacio', 'Arrecife barrera de Posidonia', 'Entre las poblaciones almerienses de Aguadulce y Roquetas de Mar se encuentra este Monumento Natural, uno de los últimos reductos de resistencia de los arrecifes de posidonia en las costas del Mediterráneo. Su necesidad de aguas limpias y oxigenadas convierte esta barrera en un espacio amenazado por el progreso y en un testigo privilegiado del cambio climático.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('03035', 'espacio', 'Navegar hasta la isla de Tabarca', 'Antiguo refugio de piratas, la isla de Tabarca es ahora uno de los rincones más románticos del litoral alicantino, un lugar prácticamente desierto donde gozar de las emociones más íntimas de la vida en pareja mientras se recorre la historia del lugar a través de la Casa del Gobernador, la iglesia de San Pedro o los vestigios de viejas murallas.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('90247', 'cueva', 'Cueva de Jentilzubi', 'Escondido entre los prados verdes del valle de Arratia, custodiado por las moles calizas del Parque Natural de Urkiola, en la sierra de Aramotz, se oculta un mágico complejo geológico, abrazado por la historia y las leyendas locales de la villa de Dima. Aquí, la actividad espeleológica es tan variada y divertida que uno parece que quiera vestirse de barro.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('10215', 'espacio', 'Cabañas en la sierra de Gata', 'En un encantador paraje dominado por masas de robles y helechos, dentro de los dominios de Villasbuenas de Gata, en la provincia de Cáceres, se encuentran estas cabañas en los árboles dispuestas a hechizar al visitante a base de vistas de altura del bosque, amén de ser una opción ecológica y respetuosa, perfecta para un fin de semana de recreo y ocio activo.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('37323', 'espacio', 'Castillo del Buen Amor', 'Una cena privada en un torreón, mayordomo incluido; masajes relajantes y catas de vino; un paseo por jardines suntuosos; dormir en estancias medievales originales... La verdad es que pocos planes más románticos hay que pasar unos días de recreo con la pareja en este castillo de Topas (Salamanca) con más de 1000 años de historia, reconvertido hoy en posada de excepción.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('15062', 'espacio', 'Cabañiñas do Bosque', 'Esta veintena de cabañas elevadas en un frondoso bosque de la costa de Outes, en A Coruña, en las que no se ha escatimado en confort, son el mejor reclamo para conocer los parajes de la ría de Muros y Noia. Si a ello se suman las playas, las mansiones palaciegas y los copiosos platos de marisco, se vivirá una inmersión completa en los bosques autóctonos gallegos de esas tierras solitarias de la Costa da Morte.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('28076', 'espacio', 'Monte Holiday', 'Parejas cariñosas y familias aventureras encontrarán en Gargantilla de Lozoya un espacio único para recrear la vista y el espíritu. Varias cabañas situadas a hasta 8 m de altura en los árboles del madrileño valle de Lozoya sirven de punto de partida para diversas excursiones ecoturísticas o actividades de multiaventura.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('13072', 'espacio', 'Ecolodge Cabañeros', 'En el bosque húmedo mediterráneo de Ciudad Real se ha construido un alojamiento ecológico, compuesto por tres cabañas, que sirven de puerta de entrada al Parque Nacional de Cabañeros, todo un paraíso ornitológico. Ofrecen un variado programa de actividades, aunque quizá la más singular consiste en tratar de avistar al lince ibérico en los memorables atardeceres que cuelgan sobre el pueblo de Retuerta del Bullaque.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('48041', 'espacio', 'Castillo de Arteaga', 'La Reserva de la Biosfera de Urdaibai es un compendio de maravillas naturales y culturales del territorio vasco. Pueblos de historia viva, como Bermeo o Gernika, y grandes espacios salvajes rodean este castillo que invita a sumergirse en otra época; para ello, hay que reservar una de sus reconocidas cenas románticas o dejarse abrazar por los ecos de otro tiempo que aún brotan en secreto en sus bien conservados elementos ornamentales.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('31232', 'espacio', 'Hotel Aire de Bardenas', '¿Qué tal dormir en una habitación de espectacular diseño, en una burbuja de techo acristalado que ha sido merecedora de más de 30 premios de arquitectura e interiorismo? Junto al Parque Natural de las Bardenas Reales, en Navarra, se encuentra esta joya que de noche se convierte en pura magia, como lo son las formaciones de esas Bardenas que sería imperdonable no visitar si uno se acerca a esta región sublime y sosegada.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('01062', 'sendero', 'Ruta del agua de Berganzo', 'Guiados por el río Inglares nos internaremos en la sierra de Cantabria, paraíso de los planes familiares en una naturaleza virgen y llamativa. Con punto de partida en el municipio de Berganzo pondremos rumbo a uno de los saltos de agua más hermosos de Euskadi, la cascada de las Herrerías, a través de esas selvas alavesas sobre las que gravitan tanto la serenidad como el misterio.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('28069', 'sendero', 'Antiguos molinos de La Hiruela', 'En plena Reserva de la Biosfera de la Sierra del Rincón se estira una agradable y tranquila senda que lleva por los antiguos molinos de cereales que orlan el cauce del río Jarama a su paso por La Hiruela. Esperan bellos escenarios serranos de carácter rural, muchos espacios para perderse y áreas recreativas que salpican unas riberas protegidas por robledales centenarios.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('33071', 'sendero', 'Ruta del Agua de Taramundi', 'Ruta circular en la que se respira el clásico ambiente mágico asturiano, que parte del encantador pueblo de Taramundi y discurre por bosques de galería y brezales, caminos ocultos, cascadas solitarias y localidades suspendidas en el tiempo, como As Veigas u Os Teixos. El recorrido sirve de testimonio de la armonía entre el hombre y las fuerzas de la naturaleza, una simbiosis que a buen seguro también disfrutará nuestro perro.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('45024', 'sendero', 'Barrancas de Burujón', 'Las aguas turquesas del río Tajo y la fuerza del viento han esculpido un paisaje arcilloso deslumbrante sobre el embalse de Castrejón, en la provincia de Toledo. Este laberíntico conjunto de lomas desnudas y barrancos rojizos, declarado Monumento Natural, se puede explorar a través de la Senda Ecológica que parte desde el municipio de Burujón.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('48032', 'sendero', 'A la cumbre del Udalaitz', 'Se puede poner a prueba la resistencia del mejor amigo del hombre ascendiendo a una exigente atalaya fronteriza entre Gipúzcoa y Vizcaya. Son apenas 1100 m de altitud, que reinan en la crestería del macizo de Udala, pero que requieren de buenas piernas o patas para alcanzar su cima.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('05004', 'sendero', 'Invernales de Vanu', 'Ideal para unas primeras aventuras caninas por los Picos de Europa, un calmo sendero se interna paralelo al río Cares desde el pueblo de Arenas de Cabrales hasta los invernales de Vanu, donde se ha levantado un área recreativa que ofrece una imponente vista del Picu Urriellu. Robles, hayas, el silencio del bosque y el rugir del río acompañarán al caminante y a su amigo de cuatro patas.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('31128', 'sendero', 'Ruta de las Golondrinas', 'Se puede conectar el pasado con el futuro en una ruta de varios días a través de los bosques, cumbres y valles del macizo de Larra. Homenaje a la migración de las mujeres pirenaicas a principios del s. XX, recorre el corazón de estos parajes exuberantes y singulares y busca refugio en las villas de Belagua, Lescún y Zuberóa.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('37012', 'sendero', 'Bosque de los Espejos', 'A modo de puerta abierta a la imaginación en el Parque Natural Las Batuecas-Sierra de Francia, esta sencilla ruta circular puro arte modernista integrado en la naturaleza permite ir descubriendo tanto las diferentes esculturas como un escenario histórico y arrollador, uniendo las localidades salmantinas de San Martín del Castañar, Las Casas del Conde y Sequeros, donde las calles estrechas, los balcones desbordados de macetas y sus gentes tranquilas conectan al visitante con unos tiempos más sencillos.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('50041', 'cueva', 'Cueva de Mairuelegorreta', 'Cultura, espeleología y tradición se mezclan en esta cueva que se interna en las entrañas del monte Gorbea. Se trata de una de las cuevas más clásicas alavesas, tanto por la estampa imponente de su sala principal como por un recorrido sencillo de galerías, apto para todo tipo de perfiles.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('11019', 'sendero', 'Pinsapar de Grazalema', 'Singulares abetos de montaña son los protagonistas de este paisaje a recorrer por un sendero bien señalizado que se adentra en el bosque, a pocos kilómetros de Grazalema. Primera Reserva de la Biosfera declarada en la península ibérica, este entorno permite excursiones asequibles por un rincón único en Europa, vigilado constantemente por el buitre leonado.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('90031', 'sendero', 'Sendero del Acantilado de Barbate', 'En el Parque Natural de La Breña y Marismas del Barbate discurre este sendero con unas imponentes vistas de los perfiles accidentados y las esculturas naturales labradas por los mares gaditanos. Siguiendo este cordón, se va de Barbate a Caños de Meca en un recorrido por playas y acantilados salvajes coloreados por el azul del agua y el verde de los pinos.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('39083', 'poza', 'Nacimiento del río Asón', 'Inmensas paredes de roca custodiando eternos valles verdes, surcados por torrentes salvajes, en los que la climatología se muestra caprichosa y severa; o lo que es lo mismo: auténtico escenario cántabro para una de sus postales imprescindibles. Eso sí, la ruta propuesta hacia el nacimiento del río es bien sencilla y de fácil acceso para todos los públicos.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('22090', 'sendero', 'Cañón del río Vero', 'Farallones de roca inmensos custodiando al caminante en uno de los rincones más sobrecogedores de la sierra de Guara. Terreno kárstico conquistado por la acción del agua, que horadó grandes cavernas donde buscaron abrigo diversos pueblos del Neolítico y la Edad de Bronce, y cuyas inquietudes artísticas forman parte del Arte Rupestre del Arco Mediterráneo, Patrimonio Mundial de la Unesco.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('10130', 'poza', 'Garganta de las Nogaledas', 'Robles, alisos y, obviamente, nogales rompen filas en esta ribera del valle del Jerte, que se puede descubrir en una sencilla ruta circular de 4 km, bien equipada con pasarelas y escaleras naturales, que se recorre mientras se van buscando sus espectaculares saltos de agua. El punto de partida de esta joya natural es el municipio de Navaconsejo, en Cáceres.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('09109', 'sendero', 'Desfiladero del río Ayuda', 'Este cordón que une Okina y Sáseta se está convirtiendo en una ruta clásica entre los que buscan planes asequibles y familiares. La senda sigue el bonito curso del río Ayuda mientras lucha contra el hechizo de los bosques de hayedos y robles, todo un regalo para la vista.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('05105', 'sendero', 'Músicos en la Naturaleza', 'Artistas y grupos de la talla de Bob Dylan, Deep Purple, Pet Shop Boys o Mark Knopfler han rendido tributo a las glorias naturales de la sierra de Gredos en este festival que se celebra en la localidad de Hoyos del Espino (Ávila) desde el 2006. Un escenario realmente majestuoso abraza a grandes maestros del pop y el rock mundial en una de esas citas a las que acudir al menos una vez en la vida... aunque lo más probable es que se acabe repitiendo.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('15061', 'sendero', 'Festival de Ortigueira', 'Espíritu de libertad y carácter folclórico se juntan en este Festival Internacional del Mundo Celta, impulsado en la década de 1970 por la Escola de Gaitas de Ortigueira, que se ha ido transformando en un conclave ¡gratuito! en el que se celebran la música, la artesanía y unas tradiciones que todavía brotan con fuerza en las salvajes profundidades gallegas.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('17117', 'sendero', 'Festival de Cap Roig', 'A los pies de un castillo, en el corazón de un jardín botánico, con un escenario al aire libre, se oficia uno de los festivales de música y danza más interesantes de nuestro país, cuyo cartel siempre presenta figuras nacionales e internacionales de relumbrón, que llevan su talento a este rincón aristocrático de la Costa Brava. Bailes, mucha algarabía e inspiración frente a un mar tranquilo y a la vez caprichoso.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('38011', 'sendero', 'Tenerife Walking Festival', 'Referencia de los festivales de senderismo en Europa, se trata de un encuentro abierto donde disfrutar tanto del destino como de sus valores culturales, amén de su apuesta por una fuerte concienciación por el cuidado de la naturaleza. Responsabilidad y deporte se aúnan en este cada vez más exitoso encuentro de formato innovador.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('22204', 'sendero', 'Pirineos Sur', 'Dos décadas lleva Pirineos Sur confirmándose como uno de los encuentros culturales más importantes del país. Sobre las montañas Sallent de Gállego, en Huesca, se celebran los sonidos del mundo, juntando artistas de fama internacional en un escenario flotante sobre el embalse de Lanuza.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('18012', 'sendero', 'Cerdanya Happy Walking', 'La comarca de la Cerdanya y su red de caminos invitan a los caminantes a este encuentro senderista, con rutas guiadas, salidas de observación de fauna y sesiones nocturnas que son puro deleite astronómico.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('18903', 'sendero', 'Sun & Snow', 'Música indie, electrónica y deportes de nieve se juntan en esta concentración en Sierra Nevada muy enfocada a la sostenibilidad, con medidas que buscan alcanzar el impacto cero durante su celebración. Son dos días en los que se combinan actividades outdoor y la algarabía del festival, todo a pocos kilómetros de la siempre atractiva Granada.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('24004', 'poza', 'Cascada de la Cimbarra', 'Los buscadores de sí mismos pueden acceder a un sorprendente paraje del Parque Natural de Despeñaperros, rincón de luz y vida protegido por las atalayas de Sierra Morena. La cascada de la Cimbarra es una fantasía natural escondida en un bosque mediterráneo, donde es fácil dejarse arrullar por el ronroneo del río Guarrizas.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('29084', 'ciclismo', 'Bicicleta de montaña por la sierra de las Nieves', 'Sí, es exigente, pero también hermosísima. Una ruta circular recorre los relieves kársticos y mágicos, modelados por la inspiración del agua, en el Parque Natural de la Sierra de las Nieves, donde brotan esculturas naturales y salvajes pasos de montaña, donde es fácil trazar itinerarios ciclo-montañoñeros para todos los estilos y niveles, todos ellos con algo en común: la ausencia humana.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('28076', 'sendero', 'Cascadas del Purgatorio', 'El valle de Lozoya ofrece multitud de posibilidades outdoor, pero pocas tan reflexivas quizá tenga algo que ver su nombre como este sendero que se puede comenzar frente al antiguo monasterio de Santa María del Paular. Sauces, avellanos, pinos y robles, alimentados por arroyos y silencio, dan sombra a un camino que deposita al caminante en un salto de agua de más de 10 m donde no resulta nada complicado conectar con la chispa primigenia de la naturaleza.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('25017', 'sendero', 'Porta del Cel', 'Su evocador nombre hace justicia a esta ruta senderista con la que tocar el cielo y encontrar la soledad. Ascensiones muy interesantes, incluidos la Pica d’Estats (techo catalán de 3143 m), los espejados lagos glaciares y otros parajes típicamente pirenaicos, hacen de esta ruta de varios días toda una delicia para un viaje interior con la mochila a cuestas.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('46106', 'sendero', 'Ruta del Agua de Chelva', 'Desde la plaza Mayor de Chelva se puede seguir un recorrido muy bien señalizado, plagado de paneles informativos, que combina de forma estupenda la naturaleza con la cultura de este espacio valenciano poco transitado. En todo momento guiado por el rumor del agua que brota de las fuentes y lavaderos, o por el susurro del río Chelva, el caminante pasa por puentes de madera, visita playas fluviales y finalmente regresa para admirar el legado histórico de unos pueblos de diversidad ancestral.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('39052', 'sendero', 'Trail running por Costa Quebrada', 'Aquellos a los que correr en solitario les cueste un mundo, tal vez encuentren en este corredor ecológico una excusa perfecta para cambiar de opinión. Son 12 km de acantilados batidos por el Cantábrico, puentes de roca, bahías y dunas que componen un mosaico tan divertido como asombroso; además, se pisan unos litorales que hablan de grandes acontecimientos geológicos y continentales, expuestos de forma contundente en la abrupta costa de Cantabria.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('39073', 'sendero', 'Trail running por Costa Quebrada', 'Aquellos a los que correr en solitario les cueste un mundo, tal vez encuentren en este corredor ecológico una excusa perfecta para cambiar de opinión. Son 12 km de acantilados batidos por el Cantábrico, puentes de roca, bahías y dunas que componen un mosaico tan divertido como asombroso; además, se pisan unos litorales que hablan de grandes acontecimientos geológicos y continentales, expuestos de forma contundente en la abrupta costa de Cantabria.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('30013', 'sendero', 'Cañón de Almadenes', 'No por ser una de las rutas más célebres de Murcia, estas gargantas dejan de ofrecer un pintoresco espacio de recreo para una experiencia con uno mismo. Hablamos de ambientes verticales, vistosos y robustos, a transitar por una ruta circular que conecta las villas de Cieza y Calasparra.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('30019', 'sendero', 'Cañón de Almadenes', 'No por ser una de las rutas más célebres de Murcia, estas gargantas dejan de ofrecer un pintoresco espacio de recreo para una experiencia con uno mismo. Hablamos de ambientes verticales, vistosos y robustos, a transitar por una ruta circular que conecta las villas de Cieza y Calasparra.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('40076', 'sendero', 'Ascensión a la Pinareja', 'La vertiente segoviana de la Pinareja (2197 m) es una auténtica oda a los escenarios vacíos, el sonido del viento y los recuerdos. Desde su alta cima, un vértice para la contemplación más pura y ensimismada, hay que echar un vistazo interminable a los valles y llanuras que frenan el avance de la sierra de Guadarrama o a los contornos elegantes del cordal de la Mujer Muerta.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('37250', 'poza', 'Pozo Airón', 'Una sencilla y muy poco transitada senda parte de Pereña de la Ribera, en Salamanca, hasta un torrente que se despeña entre brutales tolmos graníticos, y que se puede contemplar desde ambos lados, ya que cuenta con una pequeña cueva natural de fácil acceso. Territorio de soledad y emociones profundas, hay que visitarlo sobre todo en época de lluvias, cuando las aguas del arroyo de los Cuernos se vuelcan con fiereza en el cauce del Duero.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('90930', 'sendero', 'Ruta Jurásica de Préjano', 'Al amparo de la sierra de Peñalmonte se extiende el valle de Cidacos, lugar de alto valor paisajístico e histórico y ambiente muy riojano. Para conocerlo, lo mejor es partir desde Arnedillo por su vía verde, bien acondicionada y muy cómoda para sillas de ruedas.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('26119', 'sendero', 'Ruta Jurásica de Préjano', 'Al amparo de la sierra de Peñalmonte se extiende el valle de Cidacos, lugar de alto valor paisajístico e histórico y ambiente muy riojano. Para conocerlo, lo mejor es partir desde Arnedillo por su vía verde, bien acondicionada y muy cómoda para sillas de ruedas.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('33064', 'sendero', 'Vía verde del Oso', 'Esta vía verde, una de las más antiguas de España, es muy asequible (existe alguna limitación puntual que exigirá cierta ayuda) y transcurre por un exuberante paisaje de desfiladeros y bosques que abrazan los municipios de Quirós, Santo Adriano, Proaza y Teverga, en la comarca de los Valles del Oso, refugio de una de las últimas poblaciones de oso pardo cantábrico.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('33072', 'sendero', 'Vía verde del Oso', 'Esta vía verde, una de las más antiguas de España, es muy asequible (existe alguna limitación puntual que exigirá cierta ayuda) y transcurre por un exuberante paisaje de desfiladeros y bosques que abrazan los municipios de Quirós, Santo Adriano, Proaza y Teverga, en la comarca de los Valles del Oso, refugio de una de las últimas poblaciones de oso pardo cantábrico.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('33052', 'sendero', 'Vía verde del Oso', 'Esta vía verde, una de las más antiguas de España, es muy asequible (existe alguna limitación puntual que exigirá cierta ayuda) y transcurre por un exuberante paisaje de desfiladeros y bosques que abrazan los municipios de Quirós, Santo Adriano, Proaza y Teverga, en la comarca de los Valles del Oso, refugio de una de las últimas poblaciones de oso pardo cantábrico.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('33053', 'sendero', 'Vía verde del Oso', 'Esta vía verde, una de las más antiguas de España, es muy asequible (existe alguna limitación puntual que exigirá cierta ayuda) y transcurre por un exuberante paisaje de desfiladeros y bosques que abrazan los municipios de Quirós, Santo Adriano, Proaza y Teverga, en la comarca de los Valles del Oso, refugio de una de las últimas poblaciones de oso pardo cantábrico.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('22028', 'sendero', 'Valle de Linza', 'Un sendero apto para personas con movilidad reducida alcanza el valle de Linza, en Ansó, un encantador escenario que combina pastizales con hayedos y que cuenta con áreas de descanso en las que no faltan mesas adaptadas para sillas de ruedas. En el mismo municipio se han acondicionado el centro de interpretación del Parque Natural de los Valles Occidentales y el refugio de montaña de Linza, para así facilitar una experiencia más que completa.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('45028', 'sendero', 'Ruta de la Jara', 'Las orillas del Tajo siempre ofrecen rutas hermosas, pero la que se interna por las frondosidades de la sierra de Altamira cuenta además con 20 km perfectamente equipados para realizarse en silla de ruedas o hand-bike. Partiendo de la solitaria estación de tren de Calera y Chozas (Toledo), se sigue el paso del tiempo a través de viejas infraestructuras ferroviarias y túneles que hoy se funden con el intenso paisaje jareño.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('22230', 'sendero', 'Pradera de Ordesa', 'Algo más de 2 km forman la ida y vuelta de esta senda adaptada que se interna en el valle de Ordesa siguiendo el curso del río Araza. Rodeados de escarpadas paredes, labradas por el hielo glaciar durante miles de años, y a través de un idílico hayedo llegaremos hasta el imponente circo de Cotatuero y su fulgurante salto de agua, uno de los más impresionantes del Pirineo.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('28076', 'sendero', 'Valle del Lozoya', 'Flanqueado por la Cuerda Larga, los montes Carpetanos y la sierra de la Morcuera, el valle del Lozoya es uno de los escenarios de mayor valor natural de los alrededores de Madrid, además de uno de sus espacios más visitados. Aquí esperan una buena oferta de rutas adaptadas, y también es posible alquilar una Joëlette, una suerte de silla todoterreno que se desplaza con asistencia inventada por Joël Claudel.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('90598', 'sendero', 'Ruta del Carrilet', 'Atravesando tres comarcas y 12 pueblos, una cincuentena de kilómetros conforman esta vía verde que recorre los valles de los ríos Fluvià, Brugent y Ter. Todo el trazado está bien acondicionado, no presenta grandes pendientes y cuenta con puentes, barandillas y señalización, aunque el tramo más recomendable es el que une Anglès con Sant Feliu de Pallerols.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('30015', 'sendero', 'Vía verde del Noroeste', 'Este paseo cómodo que conecta los municipios murcianos de Baños de Mula y Caravaca de la Cruz, totalmente accesible en silla de ruedas, también puede servir de desafío deportivo ya que se puede estirar más de 40 km. El camino sigue la pista de un antiguo trazado ferroviario y ayuda a descubrir el alma peregrina de estos parajes lunares de Murcia.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('30029', 'sendero', 'Vía verde del Noroeste', 'Este paseo cómodo que conecta los municipios murcianos de Baños de Mula y Caravaca de la Cruz, totalmente accesible en silla de ruedas, también puede servir de desafío deportivo ya que se puede estirar más de 40 km. El camino sigue la pista de un antiguo trazado ferroviario y ayuda a descubrir el alma peregrina de estos parajes lunares de Murcia.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('43001', 'sendero', 'Sendero del Navazo', 'Una pequeña ruta permite internarse en el Paisaje Protegido de los Pinares de Rodeno, en la sierra de Albarracín. Partiendo de la pista forestal asfaltada de Albarracín, basta seguir una senda muy equipada, que pasa por cuatro abrigos de pinturas rupestres y continúa hasta un mirador desde el que se domina un escenario protagonizado por los cortados de arenisca y la fosa del Jiloca.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('34056', 'sendero', 'El Robledal del Oso', 'En Cervera del Pisuerga se encuentra este parque de aventura que ofrece diferentes circuitos adaptados a todos los niveles, uno de ellos especialmente diseñado para su disfrute por parte de personas con movilidad reducida. Tierra de grandes y pequeños tesoros, será cosa de cada uno decidir a qué categoría pertenece esta joya para toda la familia en pleno bosque palentino.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('07012', 'cueva', 'Coves del Hams', 'Visitar el lago interior de esta perla mallorquina es uno de los grandes cebos para acercarse a Porto Cristo, núcleo costero del municipio de Manacor. Como reclamo funciona la mar de bien gracias a su docena larga de salas y su espectacular Mar de Venecia, en el que se ofrecen hechizantes conciertos en barca.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('48022', 'cueva', 'Cueva de Pozalagua', 'En el Parque Natural de Armañón, hundida en las Peñas del Ranero, se halla esta cavidad con acceso y trazado accesibles, testimonio de las viejas orogenias vizcaínas. Caprichosas estructuras excéntricas se combinan con estalagmitas y estalactitas para construir una poderosa catedral subterránea perfectamente acondicionada.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('26034', 'sendero', 'Vivanco', '¿Qué tal visitar uno de los denominados mejores museos de vino del mundo y una de las bodegas más célebres de nuestro país? Cultura del vino al alcance de todos merced a unas instalaciones que están adaptadas en su totalidad a personas con movilidad reducida.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('04017', 'sendero', 'El Albardinal', 'Un sorprendente y singular jardín botánico brota en el desierto almeriense, muy cerca del pueblo minero de Rodalquilar. Bautizado en honor a una planta endémica, el albardín, ofrece un recorrido que permite conocer algunas de las especies amenazadas y exclusivas de la sierra volcánica del cabo de Gata, que hablan mejor que nadie de adaptación y supervivencia.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('08002', 'sendero', 'Vía del Nicolau', 'Un sencillo itinerario comienza en Bagà siguiendo un viejo trazado ferroviario, orlado de túneles y pasarelas, incluido un puente colgante de más de 30 m de longitud. Esta ruta, ideal para conocer el Alto Llobregat, es perfecta para recorrerla en familia y ofrece un primer contacto con el vértigo y la aventura.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('90009', 'mirador', 'Faro de Punta Albir', 'Desde la localidad alicantina de Alfas del Pi, integrada en el Parque Natural de la Serra Gelada, parte una bonita y muy asequible ruta hacia el faro de Punta Albir, inaugurado en 1863. Además de las inmensas vistas del océano y la sierra, se descubre la restaurada torre Bombarda, en su día puesto de vigilancia ante los frecuentes ataques de piratas berberiscos.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('31236', 'sendero', 'Bosque de Orgi', 'Tras siglos de explotación, este robledal que se extiende por el sur del valle de Ultzama está experimentando un poderoso proceso de regeneración natural, del que se puede ser testigo gracias a una red de senderos preparados para el paso con carritos y dotados de numerosos servicios. Árboles milenarios de Navarra cuentan historias sobre la sabiduría y la nobleza.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('09014', 'sendero', 'Ruta de los Almendros', 'El pueblo burgalés de Poza de la Sal ha usado sus almendros como fuente de inspiración para crear una ruta circular en la que admirar la explosión de una prometedora primavera, ruta que se puede recorrer año tras año para conocer todas las caras de estas tierras en constante transformación.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('90272', 'mirador', 'Mirador del Vero', 'Empujar enérgicamente el carrito de bebé es condición ineludible para conocer las callejuelas de Alquézar y su coqueto ambiente medieval, pero es que además servirá de entrenamiento para una atractiva ruta por las pasarelas del río Vero (en la que hay algún paso que obligará a portear al pequeño) que culmina en un mirador de órdago.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('22059', 'sendero', 'Parque Faunístico de los Pirineos', 'Las dos décadas de trabajo respetuoso se dejan notar en el bioparque de Lacuniacha, donde se puede disfrutar en un entorno seguro de la flora y fauna del Pirineo oscense. Al lado del pequeño pueblo de Piedrafita de Jaca, en pleno valle del Tena, encontramos esta propuesta que cuenta con una senda de 4 km por el bosque de La Pinosa, siempre alejado de la influencia humana.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('50002', 'sendero', 'Vía verde del Parque Lineal del Nervión', 'Tras abandonar la seguridad de la sierra Salvada, las aguas del Nervión se abren paso al Cantábrico por los imponentes espacios del valle de Ayala, uniendo los pueblos de Laudió y Amurrio. La ruta que discurre por estos contornos colosales se estira durante 8 km y es una excusa perfecta para visitar en familia un célebre salto de agua, una de las postales más imprescindibles de nuestras geografías.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('50008', 'sendero', 'Vía verde del Parque Lineal del Nervión', 'Tras abandonar la seguridad de la sierra Salvada, las aguas del Nervión se abren paso al Cantábrico por los imponentes espacios del valle de Ayala, uniendo los pueblos de Laudió y Amurrio. La ruta que discurre por estos contornos colosales se estira durante 8 km y es una excusa perfecta para visitar en familia un célebre salto de agua, una de las postales más imprescindibles de nuestras geografías.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('10087', 'sendero', 'Ruta de las Ermitas', 'Aunque con algo de esfuerzo por sus 300 m de desnivel, la senda que conecta las históricas ermitas de los alrededores de La Puebla de Guadalupe merece un tiento. Un conjunto monumental coronado por un viaducto, en el que estaremos acompañados de campos de olivos y viñas primero, y por pinares y madroños más adelante.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('08137', 'sendero', 'Font del Frare', 'Itinerario circular y adaptado que comienza en el recinto de Can Cascades, punto de información del Parc Natural del Montseny. Pasamanos y caminos asfaltados permiten disfrutar tranquilamente de estos paisajes de un marcado aire mediterráneo, donde lo majestuoso de las masías rivalizan con la soberbia de los bosques.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('33034', 'espacio', 'El pirata de Luarca', 'A un pueblo con tan arraigada tradición marinera no le faltan relatos y leyendas, pero ha ido ganando fuerza especialmente la del Cambaral, pirata berberisco que aterrorizaba estos litorales hasta que quedó prendado de una joven local; el romance terminaba, por supuesto, en tragedia. Puede descubrirse toda la letra pequeña de esta fábula preguntando a los vecinos de Luarca mientras se degustan algunas exquisiteces propias de este recogido rincón de la costa occidental asturiana.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('40156', 'espacio', 'Castillo de Pedraza', 'Una gran leyenda de romance y venganza, con fantasmas deambulando por los recovecos del castillo, surte de enigmas un puesto defensivo reconvertido en parador, que se levanta sobre un rico paisaje segoviano. El pueblo que defiende merece también una visita, pues ha sabido conservar a la perfección su esencia medieval.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('90936', 'espacio', 'Bosque de San Juan Xar', 'Declarado Reserva Natural en 1987, este santuario natural y espiritual, al que se accede desde el municipio navarro de Igantzi, es atravesado por sombríos senderos sobre los que danza la hojarasca, tratando de ocultar tremendas historias sobre cazas de brujas e ignorancia patriarcal, y trayendo los ecos de la cercana y célebre cueva de Zugarramurdi.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('90949', 'espacio', 'La diosa vasca', 'Muchas de las montañas de Euskadi están plagadas de leyendas, pero especialmente sugestivo es el mito sobre la diosa Mari, dama del Amboto, de cuyo estado de ánimo dependía la meteorología, amén de servir de jueza para castigar el robo, la mentira y el orgullo. Los pastores y agricultores miraban con respeto hacia arriba rezando por cielos despejados sobre las montañas de Urkiola, sin duda una de las cordilleras más fascinantes del territorio vasco.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('90603', 'espacio', 'Lago de Banyoles', 'Conocido por su gran cantidad de misterios sin resolver, el lago natural más grande de Cataluña cuenta con su propio monstruo marino capaz de predecir desastres. Más allá de la leyenda, se trata de un tranquilo atractivo turístico que invita al paseo: una ruta circular rodea el perímetro de esta masiva laguna (unos 12 km) que, más que enigmas, ofrece serenidad.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('50265', 'espacio', 'El castigo de Trasmoz', 'A pesar del paso de los tiempos, el pueblo de Trasmoz, en Zaragoza, continúa excomulgado por la celebración de supuestos aquelarres y fiestas paganas. Una curiosidad histórica, y relato de épocas más lejatorias, sobre el que también pesa una maldición impuesta por el abad del monasterio de Veruela, a cuyos deseos no se plegaba esta combativa villa.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('39037', 'espacio', 'El hombre pez de Liérganes', 'Una elegante escultura en Liérganes conmemora la odisea vivida por un joven local llamado Francisco de la Vega, desaparecido en la ría de Bilbao en 1674 y encontrado con vida cinco años más tarde en la bahía de Cádiz. Devuelto a su tierra natal, la tristeza se hizo presa de su ánimo, hasta que finalmente regresó, para siempre, al mar.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('31118', 'espacio', 'Teodosio de Goñi', 'El diablo, un dragón con apetito, arcángeles furiosos y un noble celoso protagonizan una cinematográfica historia que se ubica en el valle de Goñi, en Navarra, tierra muy rica en mitos y leyendas. Pueblos rendidos a la bruma y praderas verdes que se detienen abruptamente ante los bosques de montaña conforman el paisaje de un territorio que vale la pena recorrer con la libreta en la mano.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('37011', 'cueva', 'Cueva de Salamanca', 'Enclave legendario donde, según la tradición, el diablo daba clases de nigromancia a aquellos incautos interesados en las artes ocultas. La historia de esta cripta, que pertenecía a la antigua iglesia de San Cebrián, ha trascendido fronteras y servido de fuente para un buen montón de relatos.', 'mil_lugares');
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente) VALUES ('42173', 'espacio', 'Monte de las Ánimas', 'Gracias a la pluma fantástica de Gustavo Adolfo Bécquer son muchos los que conocen el inquietante relato que rodea esta loma de Soria, refugio de almas templarias que custodia un paraje bello y melancólico. Una visita debe incluir siempre un paseo por el esqueleto en ruinas del monasterio de San Juan de Duero.', 'mil_lugares');

